/* 平成25年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h25.committeeSessions.push(...[{"id":"h25-20130826-8","meetingId":"h25-cm08","date":"2013年8月26日","dateIso":"2013-08-26","committee":"建設委員会","time":"午後 １時００分～午後 ４時３９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を71件抜き出しています。","topics":[{"id":"topic-01","title":"」を行います。 初めに、(1)「区民住宅（あき家）入居予定者登録募集","agenda":"」を行います。 初めに、(1)「区民住宅（あき家）入居予定者登録募集","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"１個だけいいですか。あき次第抽選するということで、抽選で順位を決めるということだと思うんですが、現時点であき家はあるのでしょうか。その点をお聞かせください。","respondent":"大串住宅担当課長","answer":"ただ、これは今後、またこの１年間の中で退去が出てくる可能性がありますので、これはちょっと流動的な数字になろうかと思いますが、今現在のところは２１戸、ただし、２戸は審査中という、そういった状況になっております。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"大体どのくらいの応募があるんですか。１年間待って、また新たにということですよね。どのくらい応募があるのか。","respondent":"大串住宅担当課長","answer":"昨年の申込総数は１３６件です。１３６件申し込みがあったんですけれども、登録という形でされた方が１１１件という形になっております。毎年、大体これぐらいの数字になっております。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"これ、申込用紙はいろいろ基準があると思うんですが、一応要項の中には書いてあると思うんですが、実際応募されて、規定外ですよということで却下という形になる場合は、どのようにお知らせをして、そういうケースがあるのかどうか。いかがですか。","respondent":"大串住宅担当課長","answer":"当然一定の基準というのはありますので、それに漏れる方というのは申し込みはできませんという形でお断りはしますし、また逆に、これは即入居ということではなくて、入居の予定登録という形になりますので、先ほども申し上げましたように。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"要は、基準があって、それに合わないという形の場合には、事前に、あなたは規定から外れますよということでお断りするのか。でも、受付は受付でしてしまって、順番が来た段階で規定に対してどうかということをするのか、いつの時点で見分けというのをするのでしょうか。","respondent":"大串住宅担当課長","answer":"その時点でこちらは該当しませんよということでお答えはさせていただいていますので、そういった方まで全部受けてしまうと、抽選の順番だとか、そういったものが全て狂ってきてしまう可能性が出てきますので、あくまでも登録されている方というのは。","id":"exchange-004"}]},{"id":"topic-02","title":"平塚橋会館跡高齢者福祉施設等の整備について","agenda":"平塚橋会館跡高齢者福祉施設等の整備について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"図面を見せていただいたんですけれども、複合施設ということで、いろいろ使い勝手は、お互いの部門のところで連絡をとって考えていると思うんですけれども、特にシルバーセンターが新しいタイプというところで、設計のところで工夫があるのかどうかと、１階のところのコミュニティ室とか、レクリエーション室とか、その辺の使い方とか、あと、地域の方への。","respondent":"大串住宅担当課長","answer":"災害時の要援護者の関係ですが、こちらについても高齢者関係の施設のほうでの受け入れですとか、そういったことは検討の俎上に上がっているというふうには聞いておりますけれども、詳細につきましては。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"意見","question":"どこか変更があったところがあるのかどうかというのと、私は詳細を見たのは初めてなので、単純に感じたのは、エレベーターホール、エレベーターが中心部にありますよね。もちろん２方向の確保はできていると思うんですけれども、大勢の人がいろいろな目的で使う複合施設というところで、そういう検討があったのかどうか、意見が出たのかどうか、その辺を聞かせてください。","respondent":"大串住宅担当課長","answer":"これまでお示しした図面との変更点ということですが、すみません、高齢者関係の施設には若干変更点が幾つか出てきているのかと思うんですけれども、区営住宅に関しましては、当初の予定から大きくは変更はしてございません。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"住宅担当課長のお答えなので、そこの部分になってしまうかと思うんですけれども、初めてのタイプのというか、複合のいろいろな機能を含めているという面では、十分使い勝手をさまざまな角度から検討して、人の流れがスムーズに行くように考えていただきたいので、私は今日はここまでしか言えないんですけれども、ぜひご検討いただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"一つは、移転先が４８戸で、退去が２世帯、空室が３戸で五つあくんですよねというのと、それから、区営住宅の方の駐輪場の数、それと、ほかの施設を使うところの駐輪場の仕切りというのは、どういう形になっているのか、はっきりと分けられてわかるようになっているのか。ここは完全に住居者だけの出入りとしてセキュリティがきちんとかかるような形になるのかというのを教えてください。","respondent":"大串住宅担当課長","answer":"エレベーターの関係ですが、区営住宅の入り口のエレベーターホール、こちらについてのセキュリティ、今のところ防犯カメラ等々の設置を考えておりまして、セキュリティについては十分入居者の方のセキュリティを確保できるような形で対応していきたいと。","id":"exchange-008"},{"speaker":"西本委員","kind":"意見","question":"駐輪場なんですが、４８戸分はとってありますよということなんですが、逆に、色のついていないところの駐輪場は２１台と書いてあるんですよね。防犯カメラだけだと、別に出入りは自由なわけであると思うんですが、そこら辺をもう少し、セキュリティに関してどういう対策をとられるのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"最後にちょっとだけ。駐輪場の件なんですが、要は、お断りという形はそれはわかるんですが、構造的にほかの方が使えないような構造になっているんですか。なので、どういう形で仕切りをつくって区分けをするんですか、それがないと、いろいろ入ってきてしまいますよということなんです。その部分はいかがですか。","respondent":"大串住宅担当課長","answer":"こちらの施設が入っているんですけれども、そこの中を入ってくるような形になりますので、まず一般の方がここはオープンな駐輪場だというふうな認識はできないような状況になっています。","id":"exchange-010"},{"speaker":"伊藤委員","kind":"確認","question":"やっぱり議会としてそれを確認したいので、例えば、国の補助金なんでしょうか。東京都の補助金なんでしょうか。どういった補助金が遅れたのかというのを確認したい点と、それから、同じ行政同士ですので、もしそういうことがわかるのであれば、事前から手を組んでスケジュールを組むことはできなかったのでしょうかという二つの質問ですが、ご答弁をお願いいたします。","respondent":"大串住宅担当課長","answer":"先ほど申し上げましたように、こちら、１日も早く開設したいという思いでいろいろ調整を進めてまいりましたけれども、残念ながら最終的なところで東京都の判断、それぞれの両部門からの判断ということで、補助金の申請ですとか、決定ですとか。","id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問","question":"つまり、東京都が高齢者部門と住宅部門の補助金を出しますということですよね。やっぱり１日も早くここに入りたいという思いがあるでしょうから、繰り返しませんけれども、そういう情報なり、都側の動きを事前にとらまえた上で対応することはできなかったのでしょうかというのは。","respondent":"大串住宅担当課長","answer":"先ほど申し上げましたように、東京都が窓口になって国の補助金も含めて交渉をしてまいりました。そうした中で、都側の最終的な回答として、両部門、品川区が求めるような時期での補助金のスキームは難しいというご回答をいただきましたので、このような結果になっています。","id":"exchange-012"},{"speaker":"大沢委員","kind":"質問","question":"３の今後の整備スケジュールで、解体が終わってから本体まで６カ月ぐらいあるんですけれども、そこの当該敷地をどのような形状であけておくのかが一つ。２階、３階の当該施設については介護職員室ということがあるんですけれども、例えばここの総合事務室というのは、どの課が主に仕切るというか、どの事業部が中心になってここは切り盛りをされるか教えてください。","respondent":"大串住宅担当課長","answer":"そうしたときには、いわゆる覆いをさせていただきまして、本体工事が始まるまでの間、何かあっては困りますので、その辺については十分管理していきたい、このように考えておるところです。それから、１階の事務室の関係です。","id":"exchange-013"},{"speaker":"大沢委員","kind":"質問","question":"高齢者の部門の方が仕切るということで、このレクリエーション室、コミュニティ室、ちょっと見たところ、地域振興事業部というところだと思うんですけれども、そこらの取り扱いといいますか、要は何が言いたいかというと、私、担当の課ではないのでわかりませんというようなことがあると困るなと思って聞いたんですけれども、そこのところはどういうふうに対応がとられるのか教えてください。","respondent":"大串住宅担当課長","answer":"委員おっしゃっていただいたような、よくある課をまたがったがゆえに利用される方への不都合が生じかねないのではないかですが、こちらにつきましては、一体的な管理を行うというところで、そのような状況が発生しないような形に努めていきたい、このように考えております。","id":"exchange-014"},{"speaker":"原委員","kind":"質問・要望","question":"これ、厚生委員会の部分なんだろうと思うんですけれども、先ほど、ほかの委員からもお話があったように、新しいタイプ、何が新しいのかということを聞いていればお答えいただきたいというのと、それからあと、スタジオですが、これはどんな形で使っていくのかなというのと、僕は全体的には結構いいデザインというか、設計をされているのかなと思うんですが、その向かいに備蓄倉庫があるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"原委員","kind":"質問","question":"そこまで入らなくていいですよ。答えられる範囲で結構。後の質問と絡んできますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"原委員","kind":"質問・要望","question":"すみません、あえてお聞きしてしまったのは、本題はこれからなんですけれども、区営のほうなんですけれども、まず一番初めに、所管としてお考えを、区の考えでもいいんですけれども、２ＤＫ、３４平方メートル、２ＤＫ、５３平方メートル、これがちょっと大きさ的にどうなのかなという、これが質問第１です。ゼネレーターが乗っかってきて、両脇に室外機がある。","respondent":"大串住宅担当課長","answer":"こちらにつきましては、地下１階をつくりまして、地下１階に大きな設備等々は埋め込むという予定を考えておりますので、地下室といいますか、地下部分については、そういった設備関係が入るといったことになっております。","id":"exchange-017"},{"speaker":"原委員","kind":"質問","question":"非常に理想的な理想形の形だと思うんです。ですから、この区営の部分と福祉の部分というのかな、そういう意味での兼ね合いをうまく利用して、非常に品川区は先駆的な立場に、今でも立っていますけれども、それ以上に立っていけるようにお願いをしたいので、そこの点でご意見があればお願いいたします。","respondent":"大串住宅担当課長","answer":"そちらにつきましては、常時、補修等々をやりまして、長寿命化を図っているところですが、やはり早晩、どうしても築年数の関係で建て替えということも検討せざるを得ない、こういう状況になってこようかと思います。","id":"exchange-018"}]},{"id":"topic-03","title":"大崎西口公園の整備に向けて","agenda":"大崎西口公園の整備に向けて","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"概要のところの説明に、整備主体が大崎駅西口南地区市街地再開発組合、組合が主体となっていて、品川区の公園になるというご説明だったと思うんですが、もともとの大崎西口公園というのは区の公園ですよね。新たなここのところで、この公園は品川区立の公園になるんですか。品川区の公園が変わるのだったら、その辺も説明をしていただきたいと思います。","respondent":"溝口都市開発課長","answer":"公園の考え方ですけれども、まず、従前の大崎駅西口公園につきましては、大崎駅西口南地区の市街地再開発事業の区域内にあった公園を、今回、拡充する形で、現在、資料の下の図に黒く塗られているところに移設して新たに都市計画変更して定めたものになっております。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問","question":"質問は、品川区立でいいんですね。区立の公園という立場は変わらないと。開発組合が整備をするけれども、区立だということでよろしいんですね。","respondent":"溝口都市開発課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"地元への説明中とあるんですが、この説明中というのは、どういう形で、ごめんなさい、今後の予定のところなんですが、「基本計画を地元町会等へ説明中」という、その辺の手法がどうなっているのかというのと、近日中に意見募集の努力をされるという、この辺、現地に表示がされるだけなんでしょうか。もうちょっと広く利用者がいらっしゃると思うんですが、その辺はどうなんですか。","respondent":"溝口都市開発課長","answer":"続きまして、意見募集の関係ですが、広く意見を聞きたい、また、ここにも説明、コンセプト等に、基本方針にも書いてありましたが、ここに住まわれている住民だけではなくて、就業者、または来街者、そういったものに対して広く意見を問いたいということで、町会だけでなく。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"この隣の交通広場の予定というイメージもちょっと浮かばないんですけれども、駅前の大事な地域であるし、帰宅困難者問題とか、災害時に備えても重要な広場になるのではないかと思っていますので、ぜひいろいろな部門で意見を集めてほしいなと思うのと、あと、具体的に災害用でマンホールトイレと、かまどベンチと書かれていますけれども、この辺は、どのくらいにしていくのか。","respondent":"溝口都市開発課長","answer":"マンホールトイレにつきましては、今回、資料の裏面の基本計画図のところになりますが、階段下に公衆用のトイレを整備する関係がありますので、マンホールトイレとしては非常用ということで、４基程度を想定しているところではありますが。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"防災性というのはかなり求められていくと思うので、ぜひその辺は十分検討して配置をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"大沢委員","kind":"質問","question":"今後の予定で、「現在、整備方針・基本計画を地元町会等へ説明中」ということで、これを使って説明をしているんですね。この整備方針と基本計画、整備方針は読んでよくわかるんですけれども、計画図でこれ、丸がいっぱいついているのは、これ、何の略、どういう説明、何か全然この計画図がわからないんですけれども、これは何を意味しているんですか。","respondent":"溝口都市開発課長","answer":"町会等の説明についてですが、裏面の整備方針、基本計画図、こういったものをお示ししながら説明していっているものです。続きまして、基本計画図の丸なんですが、すみません、高木の植栽をあらわしているものです。","id":"exchange-024"},{"speaker":"大沢委員","kind":"質問","question":"今の説明を受けたのでわかるんですけれども、これ、説明をもらわないと何の丸かよくわからないんですけれども、地元の方たちには、これは説明しているんですか。","respondent":"溝口都市開発課長","answer":"すみません、地元の方には、図の見方を含めて説明しているというふうに聞いております。申しわけありません。","id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問","question":"今のに続けてですけれども、この基本計画図をパッと見たときに、補助１６３号線がどこに走っているかわからないんです。おそらくカラープリンタでしようとしたものをカラーコピーにしたんでしょうけれども、もうちょっと配慮があってよかったんじゃないかという、そうすれば、今のような質問は出なかったでしょうし、建設委員会でも、もう少し指摘がちゃんとできたと思うんですが、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"非常に下の地図等が見づらくて、道路の位置、また、交通広場との境、そういったものがわかりづらいまま資料を出しまして、これにつきましては申しわけありません。以後こういったことがないように、皆様方にわかりやすい資料の作成には努めていきたいというふうに考えております。","id":"exchange-026"}]},{"id":"topic-04","title":"使用済小型電子機器等（小型家電）の回収について","agenda":"使用済小型電子機器等（小型家電）の回収について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"そういった面では、そういった働きかけというか、進んでいるのかどうか、ぜひそういう部分では、リサイクルは販売ルートでそのまま戻していくのがすごく有効かなと思っているので、その辺の働きかけがどうなっているのかと、あと、リサイクル費用の負担が新しい法律のところでどういうふうになっているのか教えてください。","respondent":"小林品川区清掃事務所長","answer":"これらの品物については、家電のその他の品物、特定な品物、例えばエアコンですとかテレビですとか、４品目についてとられているようなリサイクル費用というのは徴収されておりませんので、今も無償の回収になっておりますが、これから区の回収も含めて。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"意見","question":"実際に今行われている拠点のところで回収というところは、やはり区の負担になっていきますよね。運搬とか、今までよりも増えますよね。","respondent":"小林品川区清掃事務所長","answer":"今回できるだけそういった負担を新たに発生させずに効率的に進めていくということで、従前の拠点回収のシステムに相乗りするということを発想したわけですが、ただ、そうは申しましても、回収箱等を使うもので、そのトラック４台分ほどの費用は新たな負担になります。","id":"exchange-028"},{"speaker":"伊藤委員","kind":"確認","question":"確認を含めてなんですけれども、これ、持ち去りが当然考えられるわけであるので、そうすると、拠点回収事業、この時間、人がいて、回収ボックスを監視するような形になるのでしょうかというのが１点と、それからあと、携帯電話をやるとなると、個人情報の消去の問題も、ここに書かれていますけれども、どう説明したらいいんだろう、ある程度、問い合わせがあった場合に備えるとしても。","respondent":"小林品川区清掃事務所長","answer":"こういったものについては、従前の事業者、ドコモショップ何々というようなところの責任をということについては、おっしゃるとおりで、基本的には各店舗で回収をしておりますので、何かお問い合わせがあれば、おついでがあれば買ったところへお持ちになるのがいいですね。","id":"exchange-029"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、そういう管理の中で回収すること自体は問題ないんでしょうけれども、その後のさまざまなルートの中で、万が一品川区のこういう回収システムの中で個人情報が表へ出てしまったということになると、それは非常にあってはならないことというか、あまりよくないことですので、だからといって、私たちは税金を使って全部それを対処しろとは言いません。それはできない話ですから。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"木村委員","kind":"質問","question":"すみません、一言だけ。この一番最後のところにリサイクルの流れが書かれておりますけれども、ちょっといい話ではないんですけれども、これによってどこかが利益を出すというようなことはあるんでしょうか。","respondent":"小林品川区清掃事務所長","answer":"その関係があるので、国の指導は、一定の規模で価値ある資源も混入してトータルで回っていくようにという地域的な配慮と、一定のスケールメリットで、そこを何とか採算ベースに上げていこうというのがねらいでございまして、それに耐え得る事業者をあらかじめ事業計画を出させて。","id":"exchange-031"},{"speaker":"木村委員","kind":"質問","question":"これ、国が相手の事業になると思うんですけれども、これによって、金、銀、銅、レアメタル等で大体どれぐらいの量が、都市にある鉱山みたいなものですけれども、その中からどれぐらいの量がとれるのか、わかったら教えてください。","respondent":"小林品川区清掃事務所長","answer":"新聞報道やいろいろなもので都市鉱山という形でいろいろな数字が出てくるんですけれども、それぞれいまいち責任をもってこのぐらいでしょうというところまで、申しわけありません、不勉強で出ていないのが現状です。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"ある程度の費用については補助金としてまかなえる部分であって、品川区の持ち出しをどのような、全くないと思っているのか、そこら辺はどういう形なんですか。","respondent":"小林品川区清掃事務所長","answer":"それで、それは本来、ここのところ採算ベースが悪化しているので問題視されているのは事実ですけれども、基本的には役割分担の中でそれは国と事業者の責任においてやっていこうというのが基本的なスタンスだったというふうに私は理解しているので、逆に。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"ということは、かなり担当の方の交渉能力といいますか、必要でしょうし、大変だろうなと思うんですけれども、それに対しては、そうは言っても、国の責任というのはあるんだと思うんです。それについては、こちらサイドから指導されよという形で請求はできるものなんでしょうか。それはどう考えていますか。","respondent":"小林品川区清掃事務所長","answer":"ただ、実証実験が進む中で、逆にそれがネックになって回収が進まないということになりますと事業目的を失いますので、その段階では、別途、国が若干助成をしても、それをシステムとして成り立たせる責務が国にはあるということは求めてまいりたいと思っています。","id":"exchange-034"},{"speaker":"原委員","kind":"質問・要望","question":"私もほかの各委員と同じような考えでして、やはり費用対効果だと思いますので、施策としては遅いぐらいかなと、逆に言うと、いろいろなメリットがあって、いっぱい粗大ごみが減っていくとか、ただ、やはりここでボックスをつくったり、１点質問なんですが、こういう小型家電回収中みたいな旗をつくるのかなと、これも費用に入るのかなとか、いろいろなことを考えてしまうんですけれども。","respondent":"小林品川区清掃事務所長","answer":"もちろんおっしゃるとおり、いろいろな資源の有効利用のほか、ごみの減量化と、それから各家庭での意識啓発等にも寄与するところ、これは一定の効果、価値としてコストの中にも反映していく必要はあろうかと思いますが。","id":"exchange-035"},{"speaker":"伊藤委員","kind":"質問","question":"２３区も東京都も全国の自治体もやるわけだろうから、となると、例えば、この時期の財調算定を考えていくとか、それから、２３区の清掃一部事務組合の事業で検討していくとか、やっぱり品川区単独でやるというよりは、もっと広範囲に考えていくのがいいのかどうかわからないまま質問しているんだけれども、たくさん集めたほうがいいのか、スケールメリットがあるほうがいいのかどうか。","respondent":"小林品川区清掃事務所長","answer":"各２３区の動きといたしましては、この施行が平成２５年、本年の４月に施行したばかりですから、まだまだ２３区全部に拡大しておりませんが、品川区を除きまして、今年度中に実施済みないしは近々実施というところは、拠点回収では５区、それから。","id":"exchange-036"},{"speaker":"伊藤委員","kind":"質問","question":"実証実験という話を聞いたんですけれども、これは言葉はおかしいですけれども、実証実験ごとに見た事業と判断していいですか。たまたま品川区がそういう指定をされたということなのか。何を言いたいかというと、この事業は実証実験で終わるんですか。そうではなくて、この事業をやるけれども、実証実験として今位置づけられているというふうに理解したらいいのか、その理解の仕方をもう一度お願いします。","respondent":"小林品川区清掃事務所長","answer":"説明が下手で申しわけございません。","id":"exchange-037"},{"speaker":"伊藤委員","kind":"意見","question":"よくわかりました。そうしたら、ある意味、さっき西本委員が指摘されましたよね。やっぱり２３区に働きかけをしていく、それから、２３区だけの事業の中で考えるのであれば、財調算定も考えられるでしょうし、それから、清掃一部事務組合の事業としても勧誘ができるわけだから、そういうことも将来視野に入れて、まずは実証実験を成功しますようにお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"回収方法のところでは、これまで小型家電も回収しますということですから、今まで古着だとか、廃食油だとかを回収している方々、いわゆるここに書かれている地域のところで、シルバーの方がやっていらっしゃったのでしょうか。そこら辺の確認、ごめんなさい、がやってくださっているのか。","respondent":"小林品川区清掃事務所長","answer":"それと、ご指摘のありました、今、拠点ではシルバーの方を中心に対応していただいておりますので、その皆さんにその場でお尋ねがあったときに、こういうことで安心ですよというような対応も含めてできるように、研修を含めて徹底してまいりたいと思います。","id":"exchange-039"}]},{"id":"topic-05","title":"大井町駅区営自転車等駐車場大井陸橋下の供用開始並びに大崎駅東口区営自転車等駐車場の台数変更について","agenda":"大井町駅区営自転車等駐車場大井陸橋下の供用開始並びに大崎駅東口区営自転車等駐車場の台数変更について","exchanges":[{"speaker":"こんの副委員長","kind":"質問","question":"大崎駅のほうの駐輪場には、チャイルドシートつきの自転車利用者からの声ということで、それを踏まえて平置きスペースをとあるんですが、大井町駅のほうは、これはどのようになっていらっしゃるのでしょうか。","respondent":"谷口交通安全担当課長","answer":"大井町のほうにつきましても、６７台を設置する予定です。","id":"exchange-040"},{"speaker":"こんの副委員長","kind":"質問","question":"ということは、６７台分、どこの場所かというのは、今のところわからないんですね。わかりました。そうすると、どこに置かれるかわかりませんが、この陸橋下の奥のほうだと、本当に今までも出し入れが非常に難しいということもあるので、まだその場所が決まっていないというのであれば、手前側のほうにして差し上げるといいかなというふうには思いますが、その点はいかがでしょうか。","respondent":"谷口交通安全担当課長","answer":"委員ご指摘のとおり、ラックであれば出し入れはしにくいんですが、今回の場合は平置きスペースを確保していますので、出し入れについては特に問題ないと考えておりますので。出し入れしやすい場所の設置を考えております。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"今の件ですが、６７台、平置きということですけれども、これは区別がつくんですか。例えば、ここはチャイルドシートつきの自転車しかだめよという限定つきなんですか。そうしないと、ほかの自転車が置かれてしまいますよね。それはどういう形になるのでしょうか。","respondent":"谷口交通安全担当課長","answer":"当然、委員ご指摘のとおり、そういうのが区別つくように、ちゃんとスペースはチャイルドシートつきということで設けてありますので、それは大丈夫なように整備しています。ご理解いただきたいと思います。","id":"exchange-042"},{"speaker":"西本委員","kind":"意見","question":"形はそうなっていても、だれでも入れるわけでしょう。ということは、せっかく６７台確保しても、チャイルドシートつきの自転車ではなくて、普通のママチャリが入れられてしまう可能性もありますよね。それの区別をどうされるのか。","respondent":"谷口交通安全担当課長","answer":"その件につきましては、定期利用と当日利用がありますので、ご利用の方につきましては、ちゃんと定期利用の番号もちゃんとしていますので、それは安心していただければと思います。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"それは定期利用だけということで、当日利用にはないですよということの理解ですか。","respondent":"谷口交通安全担当課長","answer":"当然、当日利用も準備しています。ただ、平置き、一応専用ということでやってありますが、何でも置けばいいということにはしてございませんので、係員もおりますので、その辺は巡回しながらやっていきますので、よろしくお願いしたいと思います。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"これは、では、どうしたらいいか。定期利用はいいと思うんですよ、定期利用はその自転車ですから。きっちりと目的に合わせるように、ニーズにマッチするようなつくり方だったらわからないではないんですけれども、だれでも彼でも使えるようになっている現状で、専用につくりましたと言っても、実際に使われていないとなれば、むだですよねという考え方になりませんか。","respondent":"谷口交通安全担当課長","answer":"委員のご指摘のとおりそうだと思うんですけれども、実際は、９月１日に移設しましてから、利用状況等を踏まえながら、その実態を踏まえて、また引き続き、どのような方たちの利便性が向上するかということで検討しながら進めてまいりたいと思います。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"結局、ニーズがあって、それに合わせました、要望を聞き入れていろいろ工夫されました、それはとてもいいことだと思いますし、そういう考え方でこれからもやっていただきたいんですが、でも、実際使っていただきたい方々が使えないというようなことでは、何の意味もないと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]},{"id":"topic-06","title":"国道１５号線徒歩帰宅者支援対策の実施について","agenda":"国道１５号線徒歩帰宅者支援対策の実施について","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"何点か確認させてください。地震のときには、病院はまた別な機能があるでしょうけれども、見たところ、何の表示もないから、そういう国道１５号線に近い病院については、何か検討されたような気がするんですけれども、いかがでしょうかというのが一つと、それから、大井消防署の記入がないので、１５号線沿いの立会小の対面のところにあるので、それはぜひ記入してください。いかがでしょうか。","respondent":"鈴木防災課長","answer":"実は、医療関係については、課内で地図をつくるときに、もしくは構成員を考えるときに、話し合いの中で出ているんですが、実は区としまして、今、災害時の医療連携会議といいまして、災害時医療を担っていただく病院もしくは医師会、関係団体の方との調整を進めながら。","id":"exchange-047"},{"speaker":"伊藤委員","kind":"意見","question":"そうすると、これからさまざまなところと調整をとっていくということですので、ほかのところもあるでしょうけれども、例えば、国道１５号線沿いでは、山手通りの交差点に品川医師会がたしかありますね。車検を受けて品川ナンバーを取るところ、すみません、今、正式名称が出てこないんですけれども、要は、行政機関ですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"伊藤委員","kind":"質問","question":"陸運局か。陸運局の施設も、あれも広大なスペースがあるでしょうから、それはいろいろな検討なりを加えてはいかがでしょうかという質問なんてすが、いかがでしょうか。","respondent":"鈴木防災課長","answer":"ただ、今回につきましては、基本的に徒歩帰宅者を支援するというところを中心に考えたものですので、一応、区の施設のほうは当然一時的な休憩とかの受け入れは考えておりますが、基本的には地域の資源の団体、機関の方には、水の提供だとか、情報の提供。","id":"exchange-049"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、それを帰宅困難者の方々に一時的に開放することがもしできれば、費用もほとんどかからないで一晩ぐらいはそこで過ごせる可能性があると思いますので、南大井六丁目のところですけれども、そういうことも含めて連携をとっていただけますように、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"大沢委員","kind":"質問・要望","question":"２点伺います。背景の左のほうで、徒歩帰宅者支援対策を活性化させるというふうに説明があるわけですけれども、おのおの上に課題が書いてありますけれども、何をどう活性化させるのか、そこのところをどういうふうにお考えなのかを教えていただきたいのが一つ。要は、発信するために行うという意識ではいけないと思うんです。だから、そこのところはどういうふうに考えているのか教えてください。","respondent":"鈴木防災課長","answer":"それから２点目の発信が目的なのか、具体的な行動ができる対策なり考え方を決めるのが目的なのかというご質問ですが、当然、実際にしっかりとした対策を講じるための体制、もしくは役割分担等を話し合って、実際の支援ができるような体制、環境をつくることが目的です。","id":"exchange-051"},{"speaker":"大沢委員","kind":"質問・要望","question":"要は、到達点に対しての意識が強過ぎてしまって、せっかく一から段取りを立てられて、準備会、訓練、協議会、また実地訓練と至る過程の中で、そこの中で到達点ばかりにとらわれてしまって、要は、事業自体が上滑りしないかということがちょっと心配するんですけれども、そこのところはしっかりとした意識を持ってやっていただきたいんですけれども、それを受けてもう１回。","respondent":"鈴木防災課長","answer":"もしそれが理由で補助が出ないのであれば、区の単独の経費でやってもしっかりと実績を出すということでお話をさせていただいて、都のほうも協力を了解いただいたということがありますので、今後も委員ご指摘のように、目的をはき違えることなく。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"そうすると、全体的に考えたときに、東京都の考えもあるかと思うんですが、スケール的にどのぐらいの避難者があって、それに対する対応を考えていくことになるのか、３・１１を踏まえ、また、その後の企業に対する対策もいろいろある中で、こういう１５号線の帰宅困難者というレベルは、どのぐらいのレベルと考えた形で訓練をというふうに言っているのか、その辺はいかがでしょうか。","respondent":"鈴木防災課長","answer":"企業のほうでも、留め置き、帰宅困難者対策条例のいろいろな取り組みとか、それから駅、大規模集客施設についても、やはり取り組みが始まっておりますので、その部分についても当然関係する部分についてはお声かけをするなり、協議会に入っていただく、もしくは入らなくても。","id":"exchange-053"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひうまくいっていただきたい。想定人数、スケールによって、具体的にどういう、トイレの問題にしても、お水の問題にしても、どのぐらいのスケールで配置しなければいけないのか、協力していただかなければいけないかというのは、とても大切なシミュレーションの一つだと思うので、そういう意味では、全部動いていくなと思うので、それをしっかりとしていただきたいなと。ぜひ成功をさせてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"木村委員","kind":"質問","question":"これは実験的な取り組みだというようなことだったと思うんですけれども、でも、これはせっかくのチャンスでもあると思います。徒歩帰宅者に対しての事業だということだと思うんですが、これをどのように今度は実際にそういう方々に周知するのか、そういう方法というのは何か考えているのでしょうか。","respondent":"鈴木防災課長","answer":"それと、事業者の方です、徒歩帰宅者になる可能性のある社員を抱えている事業者の方、それから主要な鉄道事業者、もしくは主要な駅、その辺に協力を依頼しながら対策の支援の中身と支援される側にも知っておいていただくといい情報だとか、もしくは協力をしていただくような項目。","id":"exchange-055"},{"speaker":"木村委員","kind":"質問","question":"そこで、例えば５００メートルおきぐらいに、１５号線だったら１５号線の地図のようなものを、先ほど書いてありますよね、こういうところに、ここから２５０メートル先、５００メートル先、後ろは５００メートル先はこういう施設がありますよみたいなものをつくるような、そういうふうな話にもこれからなっていくような可能性というのはどうでしょうか。","respondent":"鈴木防災課長","answer":"ただ、それがマップ、地図のような配れる紙資料になるのか、もしくは音声による情報なのか、もしくはご質問にあったような地図情報なのか、その情報の提供の仕方によっても、タイミングや情報の中身によって変わってくると思いますので。","id":"exchange-056"},{"speaker":"木村委員","kind":"意見","question":"これには国道１号線、そして１５号線、中原街道ということが出ているわけですけれども、これ以外にもいろいろな道があろうと思います。ここだけを通るわけではなく、それ以外にもたくさんあろうと思いますけれども、これがうまくいくようであれば、もっとどんどん品川区内中もっと広げていくというお考えとか、そういうふうにしなければならないと思いますけれども、お考えをお聞かせください。","respondent":"鈴木防災課長","answer":"その後につきましては、まずは先ほど申し上げましたように、国道１号線、それから中原街道と同じような帰宅支援道路、指定されている道路がありますので、地域の事業者の方やいろいろな資源を見極めながら、もし可能性があるところであれば、当然お声かけをして。","id":"exchange-057"},{"speaker":"伊藤委員","kind":"質問","question":"１点だけ。国道１５号線沿いに、いわゆるホテルがありますよね。ビジネスホテル。今、実際、協力は結んでいるはずでしょうから、だけれども、新たに帰宅困難者対策のために、例えばロビーを一時開放してもらうなり、必要最小限の水、それから情報提供をしてもらうなりすると、ある程度、人数が収容できるスペースが当然あるでしょうからと思うんですが、いかがでしょうか。","respondent":"鈴木防災課長","answer":"ただ、ホテルのほうでもそういうようなスペース、もしくは滞在するための施設ですので、いろいろな備品とかもそろっているので、協力できるときはぜひしたい、できますと言っていただけるんですが、実際には通常の利用客の方への対応も当然事業者としていますので。","id":"exchange-058"},{"speaker":"伊藤委員","kind":"質問・要望","question":"港区と大田区と協力してお話ししていくわけですから、当然３区にもそれぞれホテルがあるでしょうし、それは協力をして中で対応していただきたいと思います。ただし、そういう個々の事情はありますので、それはお任せします。それから同じように、１５号線だけではなくて、１号線と中原街道も同じこともあるでしょう。それはさまざまなところから検討していっていただきますようにお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"こんの副委員長","kind":"質問","question":"そこら辺はやはり押さえていくということになると、どういった形でその数字が出てくるのか、数字だけではないんですけれども、そこら辺を押さえられる意味でも、企業が帰宅困難者を、社内で社員の方をきちんと避難の体制がとれる、おうちに帰らなくもいい体制をとられているかというところのデータは必要かなというふうに思うんですけれども、いかがでしょうか。","respondent":"鈴木防災課長","answer":"は具体的に、先ほど申し上げましたように、これから地域に入って事業の概要なり目的を説明するときに、あわせて、これは事業者に限らず、商店街や町会の町会長にもお聞きする予定なんですが、２年前の東日本大震災の実際のときに、どのような状況であったか。","id":"exchange-060"},{"speaker":"あべ委員長","kind":"質問","question":"すみません、私からも１点お伺いしたいと思います。ベースとして２年前の経験ということが大きいと思うんですけれども、当時は、東京都はハード面では大きく被災したわけではなくて、交通機関の不通によって帰宅困難者が大勢出現したという状況だったと思います。あるいは、橋が崩落している。この一連の対策においては、どういった状況を前提にされての訓練になるのかということを教えてください。","respondent":"鈴木防災課長、松代防災まちづくり事業部長","answer":"ただ、これはこの対策に、徒歩帰宅者支援に限らないのですが、一応最大の考えられるところに想定をしたもので備えておきながら、実際にはその考え方や役割、必要な対応を状況に応じて実際には行動していただくというのが防災の考え方で。先ほど他の委員からも質問がありましたように、それをなぜやるかといいますと、少しでも広域的な観点を品川区内で困っている、そういった意味では区の中に滞留されている方への支援ということですけれども。","id":"exchange-061"}]},{"id":"topic-07","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"飯沼委員","kind":"提案","question":"本日も出されたと伺っているんですが、この辺の取り扱いを区はどう受けとめているのかなというのも今日ぜひタイムリーなのでお伺いしたいなと思ったんですけれども、私の手元に届いている要望書を部分的に読み上げていきたいと思いますが、一つは、住民の暮らしと安全・環境を守る会から出されているんですが、「東京都が募集している木密不燃化特区制度に対して。","respondent":"品川木密整備担当課長","answer":"要望書の中で補助２９号線の、先ほど説明しました1)番のところかと思います。不燃化特区のところの部分のお答えをいたします。基本的には、この補助２９号線をやる、やらないの判断、これは東京都がした判断です。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"提案","question":"東京都の判断を品川区が受けて一緒にやろうじゃないかということなんですかね。よその区の状況はどうなんですか。そういった中で、車両火災は一切想定をしていないという東京都のお答えをいただいたんです。今後なんですけれども、いろいろ地区も５地域なので、私はぜひ地域の皆さんからこの２９号線、これを切り離して提案すべきではないということを議論していただきたいなと思うのが１点です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"伊藤委員","kind":"提案","question":"当然それはある。これだけのことだから。だけど、裏返して言えば、それだけのことを大きな税金を投入して事業を展開していくわけだから、改めて言うけれども、東京都、品川区のこの事業を展開する目的、そしてこれが将来完成した暁には、これだけの生命、財産が大災害から救われるんですよという具体的なことを示してほしい。そういうことでよろしいんですね、今の提案としては。そんなことを今思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"西本委員","kind":"提案","question":"今、伊藤委員の提案での中間情報ですね、これはきちんと当委員会の中で話して提案していかなければいけないと思うんですね。文句のない……。〔「意見」と呼ぶ者あり〕 意見のある人が大体来るんですね。これは今までやったことないので、どういう方法があるのか、皆さんのご意見を聞いて、可能かどうかということを議論したいとは思うんですけれども、そういうのもそろそろ考えてもいいんじゃないかなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"西本委員","kind":"意見","question":"限らずです、はい。この委員会の中ではなくて、もっと違うものもできるのではないか。もちろん私たちはそういうのを持っていかないということは、すごく大きなことなので、一方的な意見だけをたくさん持っていてもしようがなくて、隠れている意見もやっぱり収集していくのが私たちの仕事ではないかということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"木村委員","kind":"質問","question":"やっぱり今、いろいろな委員から、いろいろなそういう延焼遮断帯の問題、いろいろ出ております。いろいろなところでそういう説明会を聞いたり、いろいろな話を聞きます。ですから、そういう中で、この延焼遮断としての効果というものをしっかりともっと調査をしていただいて、少しでも住民の皆さんにそれがしっかりと説明できるようなことをやるべきではないかなとも思っています。","respondent":"あべ委員長","answer":"安全なまちをつくっていくということ自体は、その手段と将来的にということで、効果の調査、そして生活の支援あるいは補償について勉強していくということですね。","id":"exchange-067"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ただし、区民の方々の中でも、この事業に一定程度理解をされて、自分の財産を守るために、もしくは災害を減災するための目的に賛同しますという方もいらっしゃるでしょうから、そういう方々の声もどんどん行政から出していただきたいということを、繰り返しになりますけれども、この事業の目的と方向性については、それが名指しされて行政が悪いことをしているんだというような議論が非常に目立つので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、あくまでも、特に一番強調して職員の方にお願いしたい、担当者レベルでは特にまたお願いしたいんですけれども、国や都の代弁者ではないという、これは逆に方向性が同じであるからといって、全く同じという返事ではなくて、あくまでもやはり品川区の職員なんだという、区民に対して一番身近なところにいるんだよというプライドを持って当たっていただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"原委員","kind":"質問","question":"正確などこまでというはっきり、測量と言っても、逆に言えば、じゃあ、それが１０メートルずれるのかと言ったら、基本的にはずれるわけはないことでございまして、基本的にはですよ、実際には区議会議員の中でも勉強されている会派は、もう図面を自分たちでつくり上げて、それを町場の人に、こんな形になるのではないですかと、参考にどうでしょうと持っている議員もいると覚え聞きます。勉強している議員は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問・要望","question":"資料はぜひ事実を明らかにするために、いろいろ、これからもこんな資料をとお願いしたら出していただきたいなと思うのと、もう一つは、先ほど、ほかの委員からも出されておりましたけれども、この委員会の、形は問わないんですが、物事には反対される方も賛成される方もいるし、どちらともいえないとおっしゃる方もいらっしゃるけれども、とにかく幅広く意見を聞いていく姿勢、特に議会としては、東京都。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/483820?Template=document&Id=4082#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":64607,"voices":177}},{"id":"h25-20130826-9","meetingId":"h25-cm08","date":"2013年8月26日","dateIso":"2013-08-26","committee":"文教委員会","time":"午後 １時００分～午後 ３時２４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件抜き出しています。","topics":[{"id":"topic-01","title":"(1)平成２６年度新入学生の学校選択希望理由調査の実施","agenda":"(1)平成２６年度新入学生の学校選択希望理由調査の実施","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ちょっと確認なんですけども、ここに出ていた小学校と中学校のそれぞれの円グラフの数字というのは、希望を選択した人、小学校では６３７人、中学校では３５９人の内訳という理解なんですか、ということが１つと、それからあと、じゃあ希望を選択していない人は、数ではここに出ているんですけれども、こういう具体的な項目ではとっていないんですか。ちょっとそのあたりをまず伺いたいなと思います。","respondent":"和氣学務課長","answer":"今回お出ししたのは希望した人のみというのは、アンケートを今回２６年度に実施するのが希望したのみの方たちなので今回出しましたが、数字は別に持ってあります。全部同じ項目でとってありますので、学校選択をしていない方たちの数字もあります。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、そういうところの状況も、文教委員会ですから教えていただきたいというふうに思っているので、今日ではなくてもいいんですけれども、機会を改めてでいいんですが、近々教えていただきたいということで、かいつまんでどういうことを皆さんが考えていらっしゃったのかをぜひ教えていただきたいと思います。今はかいつまんで。その点についてはいかがでしょうか。","respondent":"和氣学務課長","answer":"２５年、２６年が比較してご提示できるようにしていきたいというふうに思っております。そのときに全体もあわせて、２５年のものはお示ししたいというふうに考えております。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"子どもにとっても、教員、あるいは保育園の職員にとっても、なかなかそういう事業を、交流をすること自体が、日常の教育活動、保育活動プラスアルファのところだと思うので大変なんだろうなと、私はそういうふうに思って見ているんですけれども、そういう点でこの、ここに出ている数字、中学校は一定年齢が離れているのでこういう数字になっているのもあるのかなと思ったんですが。","respondent":"和氣学務課長","answer":"実際に保幼小がうまく連結して、小１プロブレムを解決するというのが一番の目的ですので、そういう点から、また別の評価をしてくれるハガキもあります。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"改めて今回のところにも入れたという基本的な概念、教育委員会の、その辺はどういうことなのか。その教育委員会の思いはこういう数字にあらわれていることがどうなのかというところを、もう一度ちょっと説明を伺いたいと思います。","respondent":"和氣学務課長","answer":"保幼小は新しく入れたんですけれども、そういう意味でいいますと、傾向をあくまでも知りたいということで入れた限りですので、これについては先ほど私のほうで回答させていただいたとおりのことであります。","id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"正確なところをちょっと後で訂正していただければありがたいんですけれども、そういうものもつくって保育課というんですかね、保育課と、それから子ども未来事業部としてと、それから教育委員会として連携してそういう新しい事業を立ち上げて、それぞれ頑張って力を入れているという、そういう品川区のコンセプトと、区民の方々が見ている学校教育というところに一定の、残念ですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"大倉委員","kind":"質問・要望","question":"お伺いしたいのは、このアンケート自体が複数回答ありとなっていて、いろいろな意見を聞いて、できるだけこう、どういった要望があるのか、需要があるのかというのを聞くということなんですが、学校選択を希望されている方で、さらにその保護者がどういったことを重点的に捉えているかというのをもう少し反映できるような選択肢というのは可能なんでしょうか。","respondent":"和氣学務課長","answer":"この場合、今の既存のアンケート機能というのがあるんですけれども、それを使ってやっているものですから、もし１位、２位とやると、それをまた開発しなきゃいけないとか、民間に委託して別の集計をかけなきゃいけないということもございまして。","id":"exchange-006"}]},{"id":"topic-02","title":"鮫浜小学校通級指導学級（情緒障害等）開設（平成２６年度）","agenda":"鮫浜小学校通級指導学級（情緒障害等）開設（平成２６年度）","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そういう、情緒障害ですから一概にそういうふうな発症率みたいなのはないんじゃないかなと、全然わからないんですけれども、ちょっと思ったりするんですが、情緒障害がこれだけの規模増えていくだろうというふうに予想をする、その何というんですか、理由というかしら、発症の状況というのはどういうふうに見たらいいのかなというのが、ちょっと１つ教えていただきたい。","respondent":"渋谷指導課長","answer":"今、ご質問ありました発症の状況、発症率というのはなかなか難しいというところでございまして、過去、平成２０年度から２５年度までの実際の子どもの数から見た通級利用率というものをもとにしまして、直近の２３年、２４年、２５年あたりの利用率から。","id":"exchange-007"},{"speaker":"南委員","kind":"質問","question":"２学級に設置したときに３名の教員を配置するということで、じゃあ鮫浜小学校は、とりあえず１学級ですよね。普通に考えても１学級となると思うんですけれども、そうすると教員配置は２人というふうになるのか。そしてまた同時に、もう少し、３０年度は７,０００人にもなるわけですから、鮫浜に１学級だけでなくて、２学級、３学級と必要だったら、ここで増やしていくという、そういう考え方なんですか。","respondent":"渋谷指導課長","answer":"ただ、１クラスについて１名教員配置、プラス１名ということになりますので、１クラスだと２名、２クラスだと３名というような形で増やすことは十分考えられることだというふうに考えます。","id":"exchange-008"},{"speaker":"本多委員","kind":"質問・要望","question":"予算的なところをもう少し教えていただきたい。教員が２学級に３名とかいうところなんですけれども、今までの区の予算がどのぐらいで、２６年度はこのぐらいとか、概要で結構なので。","respondent":"渋谷指導課長","answer":"その教室整備等で若干工事関係のお金がかかるというようなことで、これはこの後予算要求をしていくものです。ただ、水回り等の大きな工事がないので、それほど大きな工事にはならないというふうに思っております。","id":"exchange-009"},{"speaker":"塚本委員","kind":"確認","question":"新たに大井と八潮ブロックになかったのでということなので、ここに地理的に空白のところを埋めていこうというような考え方で鮫浜小学校にということなんですが、そうすると、今まで宮前、源氏前、まあ宮前はないかもしれないですけれども、例えば浅間台の通級に通っていた方が、鮫浜のほうが近いので今後は鮫浜にというような形で移っていくということもあるのかなと思うんですけれども、そのときに。","respondent":"渋谷指導課長","answer":"新たな学級が設置されることによって、保護者の方のご要望に応じて通学の便、また、それから発達障害のお子さんですので、環境が変わることによっての戸惑い等もありますので、その辺は十分配慮させていただきながら対応させていただきたいというふうに考えております。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問","question":"これから非常に増えていくという予想がされているということなんですけれども、いわゆる通級ですから、通常は普通学級に属されていて、ちょっといろいろ通級でフォローしたほうがいいんじゃないかというような方が通っていくということなので、その辺の、いわゆる発達障害ということになると、必ずしも手帳を持っているというふうに限らないので、いわゆるグレーゾーンといいますか。","respondent":"渋谷指導課長","answer":"具体的に、就学相談は保護者の方のお申し込みから始まりまして、保護者の意思を確認させていただきながら就学相談、判断会というもので、そこで専門的に判断をさせていただいて、ご相談しながら進めていくと、そういう手順です。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、学校あるいは教師の側から通級に行ったほうが望ましいのではないかというような、保護者に全くその考えを持っていなくて、そういうアプローチというのは、基本的にはないんでしょうか。","respondent":"渋谷指導課長","answer":"各学校、配慮の必要なお子様については校内委員会を設けておりまして、そこで相談をしながら、また保護者の中にはなかなか障害受容のできない方もいらっしゃいますので、時間をかけながら。","id":"exchange-012"},{"speaker":"沢田副委員長","kind":"質問","question":"今の塚本委員の質問とちょっと関するところもあるんですけれども、ということは、もう大体、例えばこの八潮とか大井地区で鮫浜小学校につくるということは、その鮫浜小学校に通級指導学級をつくるということは、そのニーズというか、どれだけここにそういう子どもたちがいるかというのを把握されているかと思うんですけれども、今回１クラス１０名ということでおさまるというふうに考えて。","respondent":"渋谷指導課長","answer":"実際保護者の方がそこをご希望されるかどうかということまでは、まだ調査をしていないのでわからないんですけれども、現在３つの情緒障害学級に在籍している子どもたちの住所はわかっておりまして、それを全部地図上に落とし込んでいったときに、鮫浜小学校。","id":"exchange-013"},{"speaker":"沢田副委員長","kind":"質問","question":"そうすると今、例えばその通級学級に通っていなくて、この地域で発達障害の方とかも、普通の学級に行っている方は余り入っていないという形なんですか。","respondent":"渋谷指導課長","answer":"そこまでのニーズは正確には把握していないですが、余りそんなに必要な方は多くないだろうというふうなことは見込んでおるところです。","id":"exchange-014"},{"speaker":"高橋委員","kind":"質問・要望","question":"この鮫浜に１クラスという想定なんですけれども、先ほど都のほうから教員が来るわけですが、そのときに１クラスだったら１人ないし２人になるかというところですけれども、そこに来られる先生というのは、教員の方は、こういった通級に経験がある、特に品川区で、ほかのところで経験された方に、立ち上げのところなので、来ていただくように区のほうからかなり、何といいますかね、そういう要望を出して。","respondent":"渋谷指導課長","answer":"経験のある方を要望していくのとともに、そういったものがかなわなければ、区内での人材を有効に活用するような人事配置については、十分検討してまいりたいというふうに思います。","id":"exchange-015"},{"speaker":"高橋委員","kind":"意見","question":"小学校でこれまで通級で培われた指導について、どのように鮫浜で活かしていくかという、その体制というか、鮫浜のところだけというのではなくて、宮前ではこうでした、源氏前ではこうでしたみたいな、そういうものをどう活かして、そういう体制が実際あるならばその辺の話とか。","respondent":"渋谷指導課長","answer":"そういったところでの横の連携等々、議員もおっしゃられたような今までの区のノウハウの蓄積をきちんと継承しながら、鮫浜小学校だけということではなくて、区全体の特別支援教育の充実に取り組んでいるところです。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"すみません。ちょっとそのあたり教えていただきたい。それから週１、２回ということなのですが、ちょっと余り私も詳しくわからないので、この際教えていただきたいんですけれども、通級だからその子どもにとって、私なら私が１週間に１、２回通うということで、１クラス１０人ですからいろいろな子がいて、通級学級が１週間開催されていると、こういう考え方なんですか、ちょっとその辺わからないので。","respondent":"渋谷指導課長","answer":"それから今の通う形は、議員がおっしゃったとおり、子どもにとっては週１回ですけれども、月曜日行く子、火曜日行く子、水曜日行く子というような子がいて、それが１学級で１０名、在籍が１０名という形で、ずっと開いているという形になります。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"そうしますと通学の関係なんですけれども、歩いていければ一番いいし、そういう年齢の、小学校１年生からも含めて、発達していく、成長していくわけですから、自分で歩いていくということはいいのかな、大事かなとも思うんですけれども、なかなかちょっと、交通の便というのもある程度考慮したほうがいいんじゃないかなと私は思うんですね。","respondent":"渋谷指導課長","answer":"電車やバスを使うことを前提に、公共の交通機関の利便性をということではなく、どちらかというと全体の地域のバランスを見て徒歩圏、８００メートルというのは大体１分８０メートルだから１０分以内で歩いていける範囲というような。","id":"exchange-018"}]},{"id":"topic-03","title":"品川区子ども・子育て会議","agenda":"品川区子ども・子育て会議","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それと、とりわけ保護者の方々は、ここによると公募区民が３人と保護者の方が５名ということになっているんですけれども、そういう方々だけじゃなくて、やっぱり公聴会を開くとか、いろいろな形での区民の方々の意見をできるだけ拾い上げていくという、そういう作業もやるべきだというふうに思っているので、その辺について。","respondent":"今井制度改革・待機児童対策担当課長","answer":"会議の今後のスケジュールですが、常任審査の際に７月１日のときにこれからの会議のスケジュールでお示しさせていただいたところですけれども、来年度も会議の進行を含めて、年度内、少なくとも３回は開催する必要があるのではないかと考えておりますが、今後。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"その点について見解を伺いたいと思います。２４の私立の保育園の中で、１１が株式会社立ということですので、半数近い状況ですよね。品川区の、公私立が合わせて６７園あるんですけれども、そこのうちで見ると１６％という状況になっている株式会社立の保育園を、やっぱり私はこれ以上増やしてほしくない、そういうところなので、きちんとその点についての見解を伺っておきたいというふうに思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"２点目の子ども・子育ての中での考え方ですけれども、前回の子ども・子育ての条例のところでもご説明したところですが、この子ども・子育て支援法自体が、質の高い幼児期の学校教育・保育の総合的な提供ということを１つの大きな目的としております。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"開設準備金だとか、開設の前家賃だとかと、そういうこともあるので、必ずしも毎年毎年投入されているというわけではないというふうに思うんですけれども、品川区がこれまで、どこの保育園に開設していただくためにどれだけ補助金を提供してきたかという数字を、文教委員会ですから、これからもっともっと株式会社が参入してくるということを予想したときに実態をつかんでおきたいというふうに思いますので。","respondent":"今井制度改革・待機児童対策担当課長","answer":"開設準備経費につきましては、安心こども基金を含めて８分の７とか、そういうふうな補助基準が示されているところですが、運営費も含めまして、今手元に資料がございませんので、また改めて正副委員長等とご相談しまして、確認させていただきたいと思います。","id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"それと東京都と品川区がそれぞれ補助金を出している、その実態をこの文教委員会としてつかんでおく必要があるんじゃないかなと思ったので質問もさせていただいたんですが、今、答弁がちょっとということなので、ぜひ委員長のほう、正副のところでご協議いただいて、出していただけるようにお願いしたいというふうに思っておりますので、次回でいいですから、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"とりあえず出していただけるよう要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"塚本委員","kind":"質問・要望","question":"最初にちょっと１つ確認させていただきたい。","respondent":"今井制度改革・待機児童対策担当課長","answer":"２３区の状況ですが、２３区では基本的に子ども・子育て会議については条例設置でするところと要綱設置でするところ、それから次世代で重ねるところと、ほかにも児童福祉関係の協議会等に含んで子ども・子育てを実施しているところがありますので、２３区の対応はそれぞれです。","id":"exchange-024"},{"speaker":"塚本委員","kind":"質問・要望","question":"じゃあ、今お伺いして、品川区としては兼務という形で次世代育成支援と子ども・子育てとをやるということで、兼ねるようになさったという意図をもう少し詳しく、兼務という形にした意図をもう少し詳しくお聞きしたいのと、あと構成２０名の中で子ども・子育て支援に関する事業等に従事する者１０名という中で、商工会議所というのがあるんですけれども、これが従事するということでいうと。","respondent":"今井制度改革・待機児童対策担当課長","answer":"最初に商工会議所の関係ですが、こちらのほうにありますとおり、次世代のほうの委員構成につきましては、品川区の次世代対策推進協議会とあわせて子ども・子育てのことを審議していただくために、次世代の育成推進協議会のときの構成も踏まえながら。","id":"exchange-025"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"この委員構成の確認をさせていただきたいんですけれども、区立小学校というのは、区立小学校の校長先生でよろしかったのかというのと、それから日本労働組合総連合会というもの、これは教職員の方のことなのかということと、それから保育事業経営者、品川区私立幼稚園協会、品川区私立保育園連合会とあるんですけれども、保育事業経営者というのは品川区立の保育園連合会以外の。","respondent":"今井制度改革・待機児童対策担当課長","answer":"委員の構成と公募委員についてのご質問です。初めに、区立小学校というふうにありますのは、校長、区立小学校の校長を充てるものと考えております。","id":"exchange-026"},{"speaker":"沢田副委員長","kind":"確認","question":"その委員会構成、日本労働組合総連合会の中で選んでいただいたということでよろしいということだと思います、その辺を確認させてください。教職員じゃないのかということを確認しました。それからあと、今の３名ということで、そういったことで選ばれたということがわかりました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"２点目の出席状況ですが、今欠席というふうに伺っておりますのが、医師会の方がちょうど、何というんですか、ご自身の医療のほうに当たられるということでご欠席というふうに聞いておりまして、あとお一人、保護者の中でご欠席になるというふうに聞いている以外は。","id":"exchange-027"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"２回目以降、また１１月となっていますけれども、やはり保護者の方というのはなかなか、特に保育園に預けられている方というのは平日の日中仕事をされている方がほとんどだと思いますし、幼稚園もそういう方がいらっしゃると思いますので、また日程のほうはご検討をしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"３回目までのスケジュールが示されているんですけれども、２回目はどんな内容でとか、ちょっと一定の考えていることがあったら教えていただきたいなというふうに思っておりますし、私はぜひ冒頭に質問としていろいろな会議の、公聴会はやらないというふうにはっきりおっしゃられたんですが、それも会議の主体性で、会長さん等々の会議運営の姿勢であっていいんじゃないかなというふうに思っているので。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今後の審議のスケジュールですが、この中身自体も今後会議の中で諮ってまいる内容ですけれども、前回スケジュールの中でお示ししたとおり、今年度の末までには東京都のほうに量の見込みの部分は報告、協議することになっておりますので、私どもも次回、２回、３回の審議を経て。","id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"確かにいろいろと周知のところであったと思いますけれども、ちょっと私今、全部記憶していないので、また第１委員会室なので、一定程度の傍聴の人数というのはキャパがあるんじゃないかなとちょっと思ったんですが、改めて何人ぐらい傍聴席を用意していただけているのか、そのあたり教えていただきたいということと、それから年度末まで保育事業の量を報告することになっているというので、当然１１月。","respondent":"今井制度改革・待機児童対策担当課長","answer":"最初に傍聴人数ですが、傍聴人数は１０名という形で、先着というふうに予定しております。次に事業計画ですけれども、先ほども申しました量の見込みは今年度末で、この計画自体は２７年の３月までに事業計画と各方策を含めたものを東京都の方に最終的に出します。","id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"傍聴は１０名なんて少な過ぎると思います。本当に今大変な、保育園に子どもを預けることも含めて、子育て支援への期待が非常に高まっている中だけに、これからの品川区の事業内容がここで決まっていくというわけですから、広く聞くという、そういう姿勢を大事にしていただきたいということを、ちょっとくどいですけれども、強調して意見として終わりたいと思います。","respondent":"若林委員長、立川保育課長","answer":"ほかにございませんか。ご発言がないようですので、これで本件および報告事項を終了いたします。それで認定こども園の特徴ですけれども、こちらについては、いわゆる内容的に保育および教育を一体的に提供して、またなおかつ地域における子育て支援を実施する機能を備えるということが原則でございまして。","id":"exchange-031"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"園によってもそれぞれ違うと思うんですけれども、一番多い、４・５歳児で１人の職員に対して３０人を超えている最大の数は幾つなのか、あるいは最低が幾つなのかとか、ちょっと年齢に応じてそれぞれ、どういう状況なのか教えていただきたいと思います。","respondent":"立川保育課長","answer":"現状、区立につきましては、年齢で区切った場合の３０名以上のクラスというのはございません。","id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"ございませんと。私は０歳から１歳児、２歳児、３歳児、４歳児、５歳児と全部の年齢で、定数はこうですけれども、現実的にはどういうふうになっているのかなというのを、ちょっとそれを聞きたかったんですが、全年齢で。その数字を知りたかったんです。１園１園聞くわけにいかないので、一番多いところが何人いるのか、その数字を教えていただきたいということで質問したんですけれども、全年齢で。","respondent":"立川保育課長","answer":"保育士の配置につきましては、いわゆる２０人に１人とか、３０人に１人とか、これを超えた場合については、それに従って人数のカウントをしていくということになります。ですから超えていて人が足りないとか、そういうような現状ではございません。","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"今日は所管事務調査ということで、この資料をつくり、説明もいただいたんですけれども、当然これに関して質疑するということがあるわけですから、それに関して資料がないから答えられないというふうにはしないで、やっぱりできるだけ対応していただけるようにお願いしたいなというふうに思っているんです。","respondent":"立川保育課長","answer":"職員配置につきましては定員で配置をしているわけではございません。実際預かっている子どもの数に従って、職員については配置していますので、現行の厚生労働省が定める基準を下回っているとか、そういうようなことは一切ございません。","id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"ちょっと聞き方が悪かったのかもしれないけれども、定数としては１人の職員が、３歳児であれば２０人までですよと。２１人になったらもう１人職員を増やしますよという、こういう考え方ですよね。違うんですか。","respondent":"立川保育課長","answer":"全体の保育時間と子どもの人数につきましては、非常勤の職員、また派遣の職員を配置いたしまして、全体として適正な職員の配置を確保しています。","id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"今、言っていることがちょっとよくわからなかったんですけれども、さっき部長さんが首を振っていたので、ちょっとその首を振っているあたりを説明していただければわかるかなと思ったんですが、まずちょっとそれを１つお願いしたいのと、今、課長さんの説明では、非常勤の職員を配置しているという話なんですけれども、品川区の公立保育園４３園、この資料によると８９ページに４３か所と、区立保育園が。","respondent":"立川保育課長","answer":"お手元に事務事業概要、あると思いますけれども、その４ページに職員の配置状況ということで、保育士につきましては６８４名、看護師２６名、用務４２名ということで、一覧になっているところです。非常勤につきましては、有資格、無資格含めまして、約６００名を配置しています。","id":"exchange-036"},{"speaker":"南委員","kind":"質問","question":"首を振っていたあたり、ちょっと説明してください。教えてください。","respondent":"立川保育課長","answer":"すみません。職員配置についての説明をもう一度します。国の基準ですけれども、こちらについては８時間開所を基本としておりますので、それに従って、まず基本的な人数というのは出ているところです。","id":"exchange-037"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっとそのあたりの現実的な姿を見てみたいと思って質問したんですけれども、わかりました。看護師がいますよね、それと栄養士も保育課勤務の栄養士ということでカウントしていいと思うので、あと保育士と用務、園長職というのは保育士に入るのかなとちょっと思ったんですけれども、これでいいかどうか確認をしたいんですが、正確に教えてください。","respondent":"立川保育課長","answer":"４ページの表ですけれども、合計欄の１つ上のところが保育課というところになっておりまして、園長については保育士６８４名の中に含まれております。園長によっては看護師の資格である者もいますので、それもこの２６名の中に入っているところです。","id":"exchange-038"},{"speaker":"南委員","kind":"質問","question":"私今質問して一番知りたかったのが、保育園運営、保育に携わる、そういう職員の方が、正規に対してかなり非常勤の職員も多用されているんじゃないかなとちょっと思ったりするので、私の問題意識としてはそこのところをどういうふうにバランスをとって見たらいいのかというのはあったので聞いたんですけれども、保育士に園長が含まれている、あるいは看護師にも含まれているというふうになると。","respondent":"立川保育課長","answer":"〔「保育課じゃないの、保育園」と呼ぶ者あり〕保育園におきましては、現在４２園で７５２名という数字が、ちょっと上の表の保育課の、保育園４２園というブランチがあるんですけれども、こちらを見ていただければと思うんですが、この７５２名の中には、当然保育士資格を持つ。","id":"exchange-039"},{"speaker":"本多委員","kind":"質問・要望","question":"今後の国の動向をにらみながら、いろいろいと取り組みを考えていっていると思うんですけれども、国の方針が決まる以前に、区でできること、独自の取り組み、なかなか難しいのかもしれないんですが、今後の取り組みについてどのようにお考えなのか、まず方針をお聞かせいただきたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今後の施設の類型につきましては、今、子ども・子育て支援制度では、今の現行の施設がそのまま残るということ、運営をそのままできるという形で国のほうは取り組みを進めておりますが、中には家庭的保育事業などは小規模保育事業などへの一定の切り替えのときもありますので。","id":"exchange-040"},{"speaker":"塚本委員","kind":"確認","question":"現行保育施設の類型ということで１枚物でまとめていただいて、大変に考えやすいというか、思考しやすいのでありがたいんですけれども、今日は子ども・子育て支援制度についての、類型とともに課題ということでの事務調査で、今、本多委員の質問の答弁で、現行制度はそのまま、特に何もしなくても平成２７年度４月を迎えられるというようなご答弁があったんだと思うんですけれども、そこが特に。","respondent":"今井制度改革・待機児童対策担当課長","answer":"こちらのほうは、保育ママのイメージでいいますと、６人から１９名までの方をお預かりする小規模保育事業という形がつくられてまいりまして、この基準も今、国は検討中です。","id":"exchange-041"},{"speaker":"塚本委員","kind":"質問","question":"今の話で、施設型給付というものを受けていくためには、区としての基準を満たしていただく必要があるので、そこに一定のハードルなり何なりというのが出てくるかもしれないというお話だったんですけれども、施設型給付を受けない選択肢というのはあるということでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"国の方針はなるべく認可外ということではなくて、施設型給付の中で、子ども・子育てという大きな枠の中で補助していこうというのが国の方針ですが、例えば一例を挙げますと、幼稚園では現行の私学助成という制度のまま残ることが可能です。","id":"exchange-042"},{"speaker":"沢田副委員長","kind":"質問","question":"こうやって見ると本当にいろいろ制度が複雑で、いろいろな条件とかがあって、特に都市部に関してはさらに認可外保育施設の関係とか、複雑になっていると思うんですが、これは国が決めていく方向性というのもあると思うんですけれども、この先へ、これからどういうふうにこういった教育、子ども・子育て施設がどういう方向に向かっていくのかというのは、さっきのインセンティブの話もありましたが。","respondent":"今井制度改革・待機児童対策担当課長","answer":"実際に私どもも、今、さまざまな類型の施設を持っておりますけれども、区民の方にこれからお示ししていくのはなかなか難しいなという部分ありますが、１つは、やっぱり働き方等の面で、社会の受け皿がどう変わるかということもあるかもしれないんですけれども、区としましては。","id":"exchange-043"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"そうやって少しずつでも使われる保護者の方のニーズに合った制度というのが必要ですし、そういう方向に向かっていくということはすごく大切なことだと思うので、これからも区としてもいろいろな細かい基準等、ニーズもありますけれども、そういうのを使い分けて子育てが充実していく、品川区は子育ては進んでいると言われていますから、充実していく方向になっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"高橋委員","kind":"質問","question":"どういう方針かというところで、ちょっとお話幾つか出たんですけれども、認定こども園のところにインセンティブがないのと事務が煩雑だというお話があったんですが、あとは文部科学省と厚生労働省の縦割りという、そういういろいろな制度上のことがあったんですけれども、何というかな、新認定こども園の思想というか、そこにおける幼児教育に対して、区としてそこにどう達していこうとするか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"品川区は、やはり平成１３年度のモデル実施から、幼保一体施設という品川区独自の取り組みを国に先駆けて進めてまいりました。","id":"exchange-045"},{"speaker":"高橋委員","kind":"確認","question":"確認をして、じゃあ新しい制度については現行の品川区の幼保一体と思想的にはつながるところがあって、ただそちらに行くことによって、必要がないというか、そういうようなところまで考えていると。今、じゃあ差を、どういう違いがあるかを検討されているという状況なんですか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"ただ、委員、先ほどからご指摘のとおり、質の高い幼児教育を、これから保育も含めて保障していくというふうな理念の部分は、新しい幼保連携型認定こども園の理念の部分は十分現行の幼保一体施設が満たしているものというふうに考えております。","id":"exchange-046"},{"speaker":"南委員","kind":"質問","question":"したがって子どもに、０歳とかそういう小さな年齢の子どもは、保育室が一定の広さがあればほふくできる、ハイハイね、ほふくできるそういうスペースがきちんと確保されていればまだいいんだけれども、幼児となると、やっぱり保育室だけでは不十分ですから、跳んだりはねたり、飛び回ったり、駆け回ったりする、そういう場所が必要なので、園庭だとか、そういう場所がなくちゃいけないんだけど。","respondent":"立川保育課長","answer":"園庭の有無につきましては、ちょっと現在手持ちの資料がございませんので、後ほどお示ししたいと思います。","id":"exchange-047"},{"speaker":"南委員","kind":"質問・要望","question":"それでここの、今のつくっていただいたこの資料で、「付近の適当な場所で代替可」という、ここのところをもって認可になっているんだろうというふうに思うんですけれども、果たして担当者として子どもの豊かな成長発達を保障するという、そういう何というんでしょうか、設置の思いのある保育園で、しかも２歳児以上の子どもさんたちが通う１日の大半の時間を過ごす保育園で。","respondent":"今井制度改革・待機児童対策担当課長","answer":"私どもやはり、こういうふうに施設基準を出してしまいますと、その施設基準の形態ということがどうしても議員のご指摘のところがあるとは思いますけれども、区としては、実際その中でどのような保育がなされているかということを。","id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"どこの部署よりも、子ども未来事業部しかそこのところは主張できないところなんですから、やっぱりそこは何としても頑張っていただきたいというふうに思っています。どこに入れてもいいんだという、そういうことで事業展開していただきたいと思います。改めてそこについて、答弁できる部分じゃないと思うので答弁は求めませんけれども、しかし本当に率直に、真摯に受けとめていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/947507?Template=document&Id=4800#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":43255,"voices":126}},{"id":"h25-20130826-5","meetingId":"h25-cm08","date":"2013年8月26日","dateIso":"2013-08-26","committee":"総務委員会","time":"午後 １時００分～午後 ４時５４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","topics":[{"id":"topic-01","title":"平成２５年度都区財政調整交付金当初算定の結果","agenda":"平成２５年度都区財政調整交付金当初算定の結果","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで、普通交付金にすると３９０億円ぐらいなんですけど、それに比べて、今年度はここの中で出されているのが３２６億円ということなので、すごく、何十億ですかね、かなりの額が、６０数億円、財調の普通交付金が減っているという状況になっているんですけども、これはどういう理由なのか、基準財政需要額が減っているということなのか、５５％というのがずっと同じで変わらないということであれば。","respondent":"本城企画財政課長","answer":"一番大きな要因は、リーマンショックがあったのをきっかけに、法人関係の税収が減って、調整３税というのが、５５％を掛ける元手になっている住民税の法人分と言われるものがありますが、それが法人の企業経営によって左右されることになり、大きな落ち込みがありますので。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"基準財政需要額というのは、もともとの、積み上げ方式でいくと、逆に仕事量というのは増えているような気がするんですけど、そこら辺の基準財政需要額の変更の中身と考え方というのはどうなっているのか教えてほしい。","respondent":"本城企画財政課長","answer":"基準財政需要額はそれをもとにして、全体の仕事量を算定し、各区の配分の基準になるという意味なんですが、あくまでもその元手となります調整３税、そのものを分けるための基準ということなので、この間、今ご指摘のあった推移の減っている要因としましては。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それが減っているのは税収が減っているから、それだけ減っているということはわかったんです。ということは、基準財政需要額もそれに合わせて少なくしない限りは、そういうふうになっていかないわけじゃないですか。その減ってはいないという中で、財調を減らしていくというのは、どういう考え方でやっていくのか、そこら辺のところを教えていただきたい。","respondent":"桑村企画部長","answer":"それには２３区で需要額をある程度落とせる部分があるんじゃないかというような考え方で、それで、平均的にやれるのはどこなんだろうということを検討してやっているものなので、そういう意味では。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"何か、それであれば、そういうふうに減らすというよりは、５５％の基準財政需要額は必要なんだというところで、２３区の中でさらに５５％を何か大きな仕事が来ない限りは増やせないというのではなくて、パーセンテージを変えてほしいという東京都への働きかけというのはないのかなというふうに思いますけど、その点はいかがでしょうか。","respondent":"桑村企画部長","answer":"それで、その中で特別区が３税の中でどういう仕事をしようかというのはまた別の話で、財源の話はこの間いろいろ事務事業をどうする、都区のあり方で検討しているわけですけれども、その中で一定の結論を出していこうかというのが今の考え方です。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"５５％ありきということで、それに合わせていくということなんですけれども、そうすると、平成２０年度から平成２４年度にかけて６０数億円減ってしまった、その主な要因というのはどんなものなのかというのがわかったら教えていただきたいのと、あともう一つ、財調分には、特別交付金があると思うんですけど、特別交付金も、これは平成２３年度の決算で見ると。","respondent":"本城企画財政課長","answer":"それとあと、特別交付金としてどのようなものがあるかということで、これにつきましては、典型的には災害関係ということですが、この間、防災対策等も含めて、災害にかかわるものも含めて、いろんな事業をやっておりますけれども、そのようなものを含めて。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"すみません、私７０億円が減ってきた要因というのは税収が減ったということ、そういうことではなくて、品川区の基準財政需要額の積み上げの中で、７０億円ぐらい減った主な中身というのは、どういう中身かというのがわかったら教えていただきたいということでお聞きしましたのでお願いします。","respondent":"本城企画財政課長","answer":"それで、実態と財調の基準を突き合わせまして、過不足がないか１個１個吟味していく決算分析をやっていきます。","id":"exchange-006"}]},{"id":"topic-02","title":"大井競馬場で１１月８日に開催される品川区長賞レースの愛称","agenda":"大井競馬場で１１月８日に開催される品川区長賞レースの愛称","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"応募数は１９４件ということで、それなりの応募者がいたと思うんですが、何か特別ご意見とか何かはなかったですか。応募の名称、応募の人たちだけだったでしょうか。何かほかに、今回こういうこと、愛称、皆さんに公募することに対して何かご意見とかは特段なかったでしょうか。","respondent":"工藤総務課長","answer":"名称の、レースの愛称の選定委員会ですので、選ぶという目的ですので、それ以外の部分はございませんでしたけれど、１９４件の中では、例えば区名、地名、施設名ということで、品川、大井、きゅりあんという名前であったり、東海道の品川関係だったり。","id":"exchange-007"}]},{"id":"topic-03","title":"品川区工事成績評定実施要綱の改定","agenda":"品川区工事成績評定実施要綱の改定","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"ちょっと内容なんですが、これはあくまで公共工事、ここに書いてあります品質確保の促進に関する法律を前提として、その区で発注した施設、工事に関して業者がどのくらいきちんとやったか、見ばえももちろんですけど、品質的にも優れているということを評価するということですか。","respondent":"平澤経理課長","answer":"委員ご指摘のとおりでございまして、品川区の公共工事、区が発注した工事につきまして、３００万円以上のものにつきまして、区の所管課ならびに検査員がその点数をつけるです。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"例えば、新築のときはきちんと、壁でも何でも意匠はきちんとできていると思うんですが、余りにも短期間の中で評価するというのはいいんでしょうかということと、普通新しい建築物なんかは、瑕疵担保責任がありまして、１０年間、やはり保証するんだよというものがあります。そうすると、その１０年間の中で、問題が起きたら、やはりそれは請負業者が直さなきゃいけない。そういう責任もある中で、２週間。","respondent":"平澤経理課長","answer":"ただ、こちらにつきましては、できばえもありますが、こちらの裏面のところにあります評定の内容、施工体制、現場管理、施工管理、こういったところで、できばえ以外の部分でも工事につきましては、その工事が円滑に行われている。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"でも、一定の期間を置くことによって、建物のふぐあいというのは建物自身が教えてくれると思うので、どうなのかなということもあるので、ここの時点ではこういう評価方式を今採用するということは、もちろんそれはそれで方針としていいのかもしれないけど、やはり１年ないし５年とか、そういう評価も、実際は本当はあまりよくなかったとか、そういうこともあるんじゃないかと思うので。","respondent":"平澤経理課長","answer":"見直しの体制です。ちょっと繰り返しのご説明で大変恐縮ですが、そういったふぐあいが生じた場合には、当然ながら点数は見直すということになってあります。もう一つ、次の資格です。","id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"最後に一つだけ。評価は区のほうできちんとやられると思うんですが、実際、建物というのは、それぞれ専門的な観点から見るということがすごく大事だと思うんですね。やはり、壁にしろ、配管にしろ、それぞれやっぱり専門の方が見ないと、私はいいんだろうか、悪いんだろうかというのはなかなか判定できないんじゃないかと思うんですけど、その辺についていろいろ、よりいい評定結果が出ることを望んでいます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"幾つか教えてください。対象工事の３００万円以上というのは、年間どれぐらいあるのか。どうしてもそこを評価していくと、多分区内でこういう実績がということを入れ込むのか、この辺の実績主義、そうすると、新しい業者を育成していくという観点、そういうのを入れ込んでいくというのも一つの考え方なので、ここら辺の考え方をどう捉えていらっしゃるのか教えてほしい。","respondent":"平澤経理課長","answer":"今回も東京都の担当職員を呼びまして研修をやる予定です。そういったところから、知識、技能の向上といいますか、より評価ができるような形に整えていくという作業をしてまいります。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今３００件弱というお話を伺って、その体制が何名かであると。ここは要望で言っておきますが、私はその中で行政側も切磋琢磨していく部分の人というのはいなくちゃいけないような気がします。これは要望にしておきます。それから、今の区内業者を育成するのもそうしていただきたいし、新規業者の話なんだけれども、これはちょっと答弁が欲しいのは、民間同等工事というのがありますよね。","respondent":"平澤経理課長","answer":"ただ、先ほどの繰り返しで恐縮ですが、新規事業者に門戸を広げていく、競争性の高いというんですか、公平であるべきもの、そういったところにするためには、委員ご指摘の新規事業者の参入を促すような、非常に重要な側面ですので。","id":"exchange-013"},{"speaker":"浅野委員","kind":"質問","question":"今回の実施要綱の改定ですけれども、評定内容の件で５項目あるわけですけど、合計で１００点満点ですが、総合評価の中では、２０点中だったと思うんですけど、基本的な考え方で大体２０点ぐらいとっている中で、どのぐらいの点数の割合になっているのかなというのをまず教えてください。","respondent":"平澤経理課長","answer":"ちょっと申しわけございません。工事の成績評定と、総合評価の評価項目は全く別のものです。今回ご提案申し上げているのは、これまで品川区で昭和５５年からずっと行ってまいりました工事の成績評定につきまして、評価方法は変わっておりません。評価項目は変わっておりません。","id":"exchange-014"},{"speaker":"浅野委員","kind":"質問・要望","question":"今答弁いただいたんですけれども、多分今後、品質確保ですか、これに基づいてきちんとした工事を行っていってもらうというようなことになると、やはりこういう今回の評価というんでしょうか、成績ですね、それをある程度評価していくのかなというふうに考えまして、ちょっと質問させていただいたんですけれども、先ほども他の委員からもありましたとおり。","respondent":"平澤経理課長","answer":"それをどういうふうに品川区の中で取り込んでいくかというのは、これからの課題というふうに認識しています。","id":"exchange-015"},{"speaker":"浅野委員","kind":"質問・要望","question":"今後検討されるということですけれども、やはり区内業者ですとか、他の区の業者であったとしても、やはり成績、どれだけいい点をとっているか、どれだけの実績があるかというのは、工事の品質を確保する上でも重要な観点だと思いますので、そこらあたりも今後の検討の総合評価、どうするかということもあるかと思いますが、考えていっていただければなと、このように要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"いながわ委員","kind":"意見","question":"ちょっとダブるところもあるかもしれませんが、新たに評定や苦情申出とか、苦情処理ということが加わったんですが、苦情処理というのは非常に難しい部分なのかなという思いの中で、実際に、想定される苦情というのが、うちは８５点以上なんだけど、何で８０点なのかとか、合格点が先ほど６０点とか、そんなことをちらっと聞いたんですけど、例えば５５点の通知をもらって、うちは６０点以上じゃないかと。","respondent":"平澤経理課長","answer":"これはただ単に紙を渡すだけじゃなくて、こういうところで、こういう結果なんですよということをきちんと工事主管課のほうで説明すると、こういう段取りもとってありますので、こういったところからも苦情処理というふうには至らない。","id":"exchange-017"},{"speaker":"いながわ委員","kind":"質問","question":"もし、それがないのであれば、当然のことながら行政の仕事ですから、行政だけじゃなくて、民間においてもやるべきことはやっぱり匠ですから、１００点でなければいけないと僕は思っているので、こういう委員会が必要なのかなというふうに今感じているんですね、その辺について。","respondent":"平澤経理課長","answer":"工事の主管課長が入って、こういう形で評定をつけたという説明をする。そういう段取りです。苦情処理委員会のほうでは、きちんとした手続にのっとってやっているのかどうか、当然だと思うんですけど、やっている。ただ、そうは言っても、事情変更がある場合があるかもしれません。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/599487?Template=document&Id=1958#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":25081,"voices":61}},{"id":"h25-20130827-14","meetingId":"h25-cm08","date":"2013年8月27日","dateIso":"2013-08-27","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ４時０２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査、「契約のあり方に関すること」","agenda":"特定事件調査、「契約のあり方に関すること」","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"すみません、工事成績評定の点数。もう一つこのペーパーからなのですけれども、評定結果の通知があって、その下に苦情の申出という形になっているのだけれども、工事主管課長に対し評定内容についての説明を求めることができるというのは、これは苦情申出とは別に、何らかの手続をとって行われるべきものなのか、それとも電話もしくは来庁等で済まされるものなのか、その２つをご説明ください。","respondent":"平澤経理課長","answer":"苦情申出の前に、評定結果につきましてご説明をいたしますが、ご説明の中身につきまして、評定結果について事業者のほうで、これは説明してくださいということをお話しいただければ、特に様式等があるわけではございませんので、すぐに電話等で対応できると思いますが。","id":"exchange-001"},{"speaker":"渡部委員","kind":"意見","question":"評定者の件について、わかりました。２つ目の問い合わせるということは、あくまでも問い合わせを受けた上で、また次のステップとして苦情申出があるというような考え方で、それは間違いないわけですね。","respondent":"平澤経理課長","answer":"こちらの後ろの、主な改定内容の表にお示ししましたとおり、説明につきましては工事主管課です。","id":"exchange-002"},{"speaker":"渡部委員","kind":"質問・要望","question":"品川区に対して、もしかしたらＣＳＲに入っていて貢献しているということもあろうかと思いますので、考えられる項目等をピックアップしていただいて、多岐にわたって１回考えていただきたい。他の自治体を見ても、さまざまな違った形で入っています。ワーク・ライフ・バランス等ありますので、そのようなことを私らとしてはお願いしたいのですが、その件についてはいかがでしょうか。","respondent":"平澤経理課長","answer":"しかしながら、こちらは国の定める、法律に定める総合評価方式です。ですので、例示から大きく外れる、大きく逸脱するようなものはなかなか難しいのかなと考えています。","id":"exchange-003"},{"speaker":"渡部委員","kind":"質問・要望","question":"そこだけが目立つわけではなくて、やはり価格の問題、品質の問題、当然あるわけですので、さまざまな配点方法、例えばここに書いてあります技術評価点は最高２０点と書いてありますけれども、よその自治体は足してみると２０を超えているのです。必ずしも２０で収めているわけではないと思います。それは要望として終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"質問","question":"どのくらいの企業に対して、一通りの評価が出るのか、１工事で１者しか出ないのでしょうから、それによって、総合評価に持っていく時期というのがものすごく変わってくると思うのです。大体、区として、区内の事業者に対して、どのくらいの期間で評定をしていくというふうに見込んでいるのでしょうか。","respondent":"平澤経理課長","answer":"工事成績評定の評価点というのが、現の要綱を見ると、この辺とかは変わっていないのですけれども、総合評価のところの新しい要綱でどう取り入れていくかということで、これからの検討項目ではあるのですが、現在の総合評価の試行の要綱でいきますと、３年間で最終的な。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。ただ、やはり多額な工事、大きな工事をやりますよね。例えば、Ａランクの区の業者を考えたときに工事が入らないのではないかと。何社もありますよね。その事業者は、直近には評価に入ってこないところも出てきてしまうのではないかという心配もあったので、その辺は大丈夫だということでよろしいですか。","respondent":"平澤経理課長","answer":"委員ご指摘のとおり、契約の大原則は門戸を大きく広げるです。今度、私どもの内部の規定で門戸を狭めてしまうのは言語道断のことですが、そういうことはないようにできるところからやっていくという考えです。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問","question":"３枚目の最低制限価格制度の運用状況について、この表を見せていただいて、落札者がほとんど９０何％という１００％に近い数字が出てきています。これは落札者がこの数字ですよね。当然、何社かが応札しているわけでしょうから、これ以外の会社は契約予定金額をオーバーしていたととれてしまうのですが、そういう感覚でいいのでしょうか。","respondent":"平澤経理課長","answer":"制限付き一般競争入札の場合、品川区では予定価格を公表しています。ですので、予定価格オーバーというのはなかったわけでございまして、辞退というのは何社かございました。ただ、これより少し上の範囲で張りついていたといいますか、本当に微妙な差の部分もございました。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問","question":"予定価格以上でとなると、逆に言うと、これだけの予定価格というのは相当厳しいのかなととれてしまうのですけれども、当然基準どおりの評価をして、品川区としては予定価格を出しているのでしょうけれども、前の委員会でも話しましたけれども、品川区は結構厳しいという話がある、業者の間でよく言われているけれども、この数字を見ていると本当に厳しいのではないかなという気がしたので。","respondent":"平澤経理課長","answer":"予定価格の算出の仕方です。１点だけ、新聞にもよく載っているところですが、消費税絡みの話ということで、かなりの駆け込み需要があるということは報道にあるところです。そういったところから、実際には関係のないようなところまでも値上がり傾向にある、これも事実です。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問・要望","question":"成績評定実施要綱の改定についてから伺いたいのですけれども、詳しくわからないので教えていただきたいところがあって、評定時期に工事が完了したときとあるのですけれども、これは４者が、工事が終わった後に現場に行かれるということですか。それとも、工事に、現場に定期的に行かれて、内容を見られるということなのでしょうか。そこのところを教えてください。","respondent":"平澤経理課長","answer":"この辺は非常に大事な要素です。こういったふだんの現場を見た上で評価していく。積み重ねて評価していって最終的に、最後のできばえのところは、この１４日以内ということで、評価するです。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"確認","question":"今までもやってこられたと思うのですけれども、１００点満点で細かく採点をされるということで、しかも、これが総合評価方式において、私も国土交通省のマニュアルを見ましたけれども、ほとんどの自治体で、ここの項目は非常に大きな割合を占めているということで、もちろん皆さんプロフェッショナルでいらっしゃると思うのですけれども、本当に次の工事にどれだけ影響するのか。","respondent":"平澤経理課長","answer":"この評定項目につきましては、評定表そのものが東京都と同じものを使ってございまして、品川区の評定表は載せていないのですけれども、業者には東京都と同じですとご説明をさせていただいた上で、東京都のホームページをご覧になっていただきます。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"提案","question":"このマニュアルを読むと、市区町村向けのものについては、市区町村において発注体制が十分に整備されるまでの間、市区町村向け簡易型（特別簡易型）を活用し、価格と品質にすぐれた調達を図るというようなことが推奨されているのですけれども、今、品川区がどのようにお考えかわかりませんけれども、今後は、そういった体制が整えば、これに限らず、そういった規模に応じての発注体制を検討されるのかどうか。","respondent":"平澤経理課長","answer":"今回ご提案申し上げているのは、通常、区が管理する工事につきまして、いち早く総合評価特別簡易型を実施する。そういう段取りといいますか、案件ごとにどうやっていくかということを、今後も考えていかなければいけないと思っているところです。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問","question":"それと、評価項目なのですけれども、私もこんなものがいいのかなと考えたところ、例示をされていたところが本当にぴったりくるというか、非常に区としても考えられているなという内容でした。そういったことについても細かく決めていかれるのかどうか、そこのところを伺いたいと思います。","respondent":"平澤経理課長","answer":"これは事実です。こういったところもあわせて、今後の総合評価の項目を設定する場合、先ほどの答弁の繰り返しになって恐縮ですが、品川区に最も適した評価方法をどうやっていくのかというのを、これからきちんと決めていかなければいけないと思っているところです。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問","question":"今回、評価項目の見直しがテーマに挙がっているということでしたので、細かいことに触れさせていただきました。これを強調すべきであると。国土交通省のマニュアルを読んで思ったのですけれども、こういったものに対する苦情とか、入札に関しての駆け込み機関として第三者機関というものを設けることを推奨されているのですけれども、これについて、何か品川区としての考えはあるのでしょうか。","respondent":"平澤経理課長","answer":"品川区におきましては、現在、工事成績評定につきまして、実施要綱を改定して新しい取り組みの緒についたところです。こういったところも運用の中身を見た上で、それが必要なのかどうかもあわせて、今後の１つの検討課題だと考えているところです。","id":"exchange-013"},{"speaker":"あくつ委員","kind":"質問・要望","question":"他区においては、それを監査委員がかわって、入札に関してのいろいろな点検を行っているところもあると聞いておりますので、そこのところはしっかりと制度設計をお願いしたいと思います。前回もお伺いしたのですけれども、価格点と技術点ということで、価格点のところの最低制限価格の適用がない、今回に関しては考えてはいない。もう少し詳しく教えていただきたいと思います。","respondent":"平澤経理課長","answer":"そういったことが可能であれば、そういったことも視野に入れてやっていくというのも、これからの検討課題だと考えています。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問","question":"品川区では、よもや根拠のないような歩切りは、根拠のないということはないとは思いますけれども、先ほど９９％という状況の中で、なかなか積算が厳しいのではないかという話を私もよく耳にしますので、先ほど申し上げました、全て総合評価方式、最低制限価格、先ほどの工事成績のことも三位一体というか、どれが欠けても効力を発揮しないと私自身感じますので、これについての理事者側のご意見といいますか。","respondent":"平澤経理課長","answer":"そういったものの準備をするために、工事の成績要件につきましても見直すようにさせていただいている。今年の第１回定例会でもご答弁申し上げたとおり、総合評価方式について拡充の方向で検討する、そういったこともあわせて行っているです。","id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"例えば、創意工夫と熱意というところは、一見しただけでは判断できないところだと思うのです。現実的に、工期が１０カ月なり１年の工事について、何回くらい現場に訪れて、チェックするのですか。","respondent":"平澤経理課長","answer":"それをやっていくことが、よりよい工事、できばえにつながっていくです。税金をお預かりして工事を発注しているわけですので、品質のいいものをというのは、区の職員が目指さなければならない最も大事な、基本的な部分ですので、それに向けた手続はきちんとやっていくです。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"私は、そういうことをもっとしっかりとやっていただいて、そして１つ１つの企業の技術力を高めるという点でも大いに大事なことだと思うし、いい品質をつくっていくということは品川区民の共通の利益にもつながるという点で評価、期待を持っているのですけれども、現実的にそれがどこまで出向いてなり、事前の打ち合わせの中でできるかというところが。","respondent":"平澤経理課長","answer":"品川区においても、６月１日からそれを再開させていただいたというところで、取り入れてきたところです。そういった総合的なものを全て取り入れて、法を遵守して取り組んでいくのが、私たち経理課の職務だと考えています。","id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"そういうところをどうやって公共事業が、そういう事業者、労働者に対して、追い打ちをかけるような工事発注の仕方ではなくて、きちんと生活そのものを確保していくという角度からの物事の捉え方というのですか、契約金額のあり方、そういうことが私は大事にしなくてはいけない部分だと思うので、そのあたりの考え方について伺いたいと思っているのですが、いかがでしょうか。","respondent":"平澤経理課長","answer":"今回、設計労務単価の大幅な値上げ、上方修正、金額を上げたことも、品川区として直ちに対応させていただいて、契約変更をやっているというところも１つだと考えているところです。","id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"私も、これ以上質問はしないつもりでいるつもりなのですけれども、やっぱりこの間の、例えば６月定例会で出された補正予算で、いろいろ聞いてみると、賃金の引き上げの部分だけでどこまで、第３次、第４次下請けの建設作業員の方々の給料がどこまで増えているかということが、保証というか見届けられないという状況が、品川区でもあったという関係で、今、いろいろお話を伺っていると。","respondent":"中山総務部長","answer":"そこで働く人の確保云々ということについては、さまざまな方策もありますけれども、経理課長が申し上げたように、基本的な法令遵守については、契約のいろいろな場面で伝えているですので、総合的にそのようなものはきちんと確保しつつ、本来の価格だけでない、ある意味では。","id":"exchange-019"},{"speaker":"南委員","kind":"意見","question":"したがって、そういうシステムを、システム上つくるべきだと私は思っているので、その１つのツールとして公契約条例があると思っているので、ここで公契約のことを言うつもりはないのですけれども、そういう角度で物事を見ていただく姿勢が大事なのではないかと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"あべ委員","kind":"確認","question":"工事の評定の要綱なのですけれども、これについては、繰り返しの確認になりますけれども、通知、苦情処理、公表といったところを変えるのであって、評定内容については、今回はいじらないという理解でよろしいでしょうか。どう聞けばいいのかしら、平均点でどのくらいなのかとか、あるいは大体何％くらいが８５点以上の成績を得ているのかといった、何か８５点のイメージを教えていただければと思います。","respondent":"平澤経理課長","answer":"２点にわたるお尋ねです。委員ご指摘のとおり、評定内容については一切いじってございません。２つ目、８５点ですが、成績につきましては、大体なのですけれども、七十四、五点が平均です。８５点というと、年間に一件あるどうかという、非常に優秀な工事を考えています。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問・要望","question":"なかなかハードルが高いという印象です。そこは過小評価されることがないようにしていただきたいと思っているのですが、その点何か、ここまでは品質にかかわるところでいくのだというようなものはあるのでしょうか。どのようにお考えなのか、教えてください。このままでいくと、だんだん工事の質の部分が、評価対象として少しずつ小さく削られていくような気がするのですけれども、いかがでしょうか。","respondent":"平澤経理課長","answer":"学識経験者はどのような方かというと、この前ご説明申し上げましたとおり、例えば東京都の建設事務所長、そういう人が入ってあります。そういったところからも大きく逸脱したような形の評価項目を設けることは、ほとんど不可能だということになります。","id":"exchange-022"},{"speaker":"あべ委員","kind":"質問・要望","question":"もう一つ、先ほど失格基準という話が出てきました。一方で、前回も労務監査という話をさせていただいたのですけれども、どういう制度によるかは別として、やはり社会保険未加入ですとか、あるいは労災事故が多発しているとか、そういった労務管理自体のクオリティーというのも、どこかきちんと、一定以下のところは排除なり、評価をしないような形で選定していただきたいと。この視点については、どのように。","respondent":"平澤経理課長","answer":"そういった中で、どう入れていくのかというのは、今の段階ではなかなか難しいとしか申し上げられないです。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問・要望","question":"今日、私資料を持ってきたので、いい加減な数字を言ってはいけないのですけれども、労務管理、２３区の中でも総合評価ではなくて、入札の前の段階。そういった意味では、今のご答弁の中でも、観点自体の価値は一定受けとめていただいていると考えていますので、さらに研究をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"原委員","kind":"質問","question":"それであえて、その次でお伺いしますけれども、積算といっても、経理部門だけで全部の答えが出てこないでしょうから、あれなのですけれども、わかりやすいのは建築士が何人いるかとか。一番初めのところとしては、積算できる人間が足りているのか、そこからお聞きしたいのですけれども。区としては、どんな感じで考えてらっしゃるのか。","respondent":"平澤経理課長","answer":"契約を担当する者では、なかなかお答えしづらい部分でございまして、ただ、区として責任を持って発注しているという事実。この事実１つをとってみても、現在の人員でやっている、足りているです。","id":"exchange-025"},{"speaker":"原委員","kind":"質問","question":"当然、品川区ではしておりませんので、ただ、時折、日本全国見ていますと、そういった事態が発生してしまうということがあるので、まず、それについて、制度上で何かお考えとか、より注意されたり、防止をするために頑張っていらっしゃるかというご意見を１点聞きたい。今日の部分においては、お金の部分も含めてなのですけれども、その２点をお答えいただけますでしょうか。","respondent":"平澤経理課長","answer":"予定価格の事前公表ということで、これを対応しています。予定価格の事前公表につきましては、いろいろな国のご意見があるということは承知しています。ただ、大きな面でいきますと、公表することによって、官製談合はやっても意味がないということになりますので、防げるです。","id":"exchange-026"},{"speaker":"原委員","kind":"質問","question":"ところが、それによって、具体的な例を出してしまえば、ガードマンが２人より、３人、４人のほうがいいというのは当たり前の話なのですけれども、そうすると今度は全体的なコスト高になってくる。ですから、職員内での話し合い的なものはケース・バイ・ケースなのか、事案ごとなのか、その辺のところは常時どんな形でやっているのかをお聞かせいただければと思います。","respondent":"平澤経理課長","answer":"そういった体制は整ってございまして、そういった場合には、一定のバランスというか予算の範囲の中で、契約を変更する場合もあります。そういったところで担保しています。","id":"exchange-027"},{"speaker":"原委員","kind":"質問・要望","question":"なお一層努力していただきたい。その中では、要望になりますけれども、ある意味で、年数ではなくて、個別の専門職というか専門的な能力を、内部で職員が各自で養っていただいて、品川区の職員のチームワークですから、より一層強くしていただいて、業者関係を当たっていただきたい。これはお願いですので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"井上副委員長","kind":"質問","question":"ここでは、今までは３００万円以上の工事についてされていたということで、工事契約のところで、総合評価でやっているところというのは、２,５００万円以上の工事ということだったので、そこでもされていると思うのですが、先ほど言われた２８０件の中で、大きな工事のものはここに含まれているのでしょうか。","respondent":"平澤経理課長","answer":"工事成績評定の使い方と、２８０件の中にどのようなものがあるのかというご質問ですが、後ろから、２８０件というのは全件です。ですので、大きな工事も３００万円ギリギリのところも全部入っているです。成績の使い方なのですが、これまでは試行で総合評価をやってまいりました。","id":"exchange-029"},{"speaker":"井上副委員長","kind":"質問","question":"今、指名停止ということがあったのですが、ほかの自治体の資料を読ませていただくと、入札条件として、評価をした点数以上の方たちの入札資格というものを設けて、いい仕事をする業者が報われる制度ということでされているというのがあるのですが、そういった形で、何点以上が資格になるというものは、公表しないまでも何かあるのか、それともこういうところを線引きしていますというのは。","respondent":"平澤経理課長","answer":"したがいまして、委員ご指摘のような中身につきましても、今後、工事成績評定が全ての事業者にそろってつくまで来た段階で、もう一度検討しなければならないところだと思いますが、今のところはまだそこまではいっていません。","id":"exchange-030"},{"speaker":"井上副委員長","kind":"質問","question":"ホームページで表彰をしたりとかそういったことで、事業者のスキルアップにもつながると思うので、その辺はまだこれからだということで、あと先ほど苦情申出の委員会の中で、委員長が特に必要と認めた場合は臨時委員ということで外部の方という意味合いだと思うのですけれども、ここでは本当に品川区だけの、閉ざされた中での苦情処理の議論しかないということで、初めからそういった方たち。","respondent":"平澤経理課長","answer":"これにつきましては、必要な場合は個別、その個別の中身について、例えば最終的なできあいの部分がどうかとか、そういうことになった場合があるかもしれませんけれども、通常の工事の成績評定の中の一定の手順を踏んだつけ方をしている上では。","id":"exchange-031"},{"speaker":"井上副委員長","kind":"質問","question":"そこで、先ほどから「品川区に合った」という表現が何回かあって、その部分をどう説明していくのかということと、公金を使っての事業ですから、価格と品質というところをいかに頑張るかということが役割だと思うのですけれども、その部分と、もう一つ指摘されているのが、総合評価方式をした場合に、通常の入札よりも入札をされる事業者の負担が増えてくるという指摘があるのですけれども、その辺について。","respondent":"平澤経理課長","answer":"入札事業者の負担というところからお答えさせていただきたいところですが、先ほどご説明いたしましたが、例えば簡易型につきましては、提案書が必要だということが具体的に定められてあります。そういったところが負担になってくるです。","id":"exchange-032"},{"speaker":"井上副委員長","kind":"質問","question":"国土交通省のマニュアルにもあるような地域貢献という部分は、入札のところとは、どういうふうに入れるかという問題が１つと、また事業者が生活できるそういった部分というのが、一緒くたに考えられると、また別の問題になってくると思うので、その辺は整理をして総合評価というところで取り組んでいかなくてはいけないと思っているのですが、地域貢献について。","respondent":"平澤経理課長","answer":"スケジュールというお尋ねでよろしいでしょうか。","id":"exchange-033"}]},{"id":"topic-02","title":"」を聴取いたします。 「未利用国有地にかかる取得等の要望","agenda":"」を聴取いたします。 「未利用国有地にかかる取得等の要望","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"年度が切りかわって、例えば新年度からやっていくといったときに、委員会のまとめが新年度に入ってからでは、何の要望も……。こういう委員会では、言葉では出ていますけれども、ペーパーとして中間報告を出しておくほうが、委員会としての実績、我々の検討した結果が出てくるのではないかということで、正式にまとめて出したほうがいいのではないかと私は思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"そこら辺がよくわからなかったものですから、今日、あわせて説明と、それから２回の議論という中で、していったほうがいいのではないかということになれば積極的にしていきたいですし、今その段階なのかなという、今後のスケジュール的なものをどのようにお考えなのでしょうか。","respondent":"山元委員長","answer":"前回と今回、皆さんのご意見をいただいて、先ほど皆様のお手元にお渡ししたものも中心に考えて、それをある程度正副で考え、次回、こういう形でできましたというのを、皆さんに。","id":"exchange-035"},{"speaker":"あべ委員","kind":"質問","question":"それは、こういう意見がありましたという感じでの中間まとめということになるのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"あべ委員","kind":"意見","question":"どういう中身にするかというのは、次にお示ししていただいた中でまた議論をしていくという。","respondent":"山元委員長","answer":"次回には、もうある程度形をつくって、皆さんにこういう形にして提出というか、行革として、このようにまとめましたという形でお見せをする予定ではいるのですけれども。","id":"exchange-037"},{"speaker":"あべ委員","kind":"意見","question":"前向きに考えたいとは思いますが、最終的にはもう出すものがある。こういうものという中身を示されてのお話かなと思います。出すこと自体は、こういうタイミングですので悪くはないと思います。内容次第ということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"南委員","kind":"提案","question":"私もまとめて出すということは、別に反対するものではないと思うのですけれども、行政側の動きとの関係で、改めて確認しておきたいと思っているので、先ほど鈴木真澄委員の発言のところかなとは思ったのですけれども、正副で今の時期に出していきたいというふうに考えて提案された、そのあたりの思いと背景を改めて確認したいと思うのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"南委員","kind":"確認","question":"大体、特別委員会のまとめというのは、１年間の締めくくりの時期にやってきていたではないですか。そういう状況の中で、この時期に、８月、９月に、まとめていくという、そのあたりのことをもう１回、ちょっと確認をしておきたいと思って言ったのですけれども、先ほどの委員長のお話には、そのあたりが触れられていなかったので、もう１回伺いたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"この説明書の中にも、さっき経理課長のお話にもあったかと思うのですけれども、本格実施に向けて検討しているという状況とのお答えもありました。私のほうでは、それを含めて、本格実施に決まりましたと出されるのではなく、我々委員会での意向として、やはり先に出すべきだろうと。震災対策特別委員会を考えても、まとまる前に委員会の要望として出された。それと同じ発想です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"南委員","kind":"確認","question":"７月３日に、この委員会の１年間の動きみたいな委員長から説明していただいた、そこを改めて確認したのですけれども、なかなかそういうふうには、私としては読み切れなかったので、今この時期にというところを確認させていただいたのですが、本格実施に向けて、この時期しかないだろうということで、そのこと自体はよくわかるところなので、まとめをしていくということは大事なことだと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"あべ委員","kind":"確認","question":"１つお聞きしたいのですが、非常に詰めて詰めて中間まとめ、目的としてはわかるのですけれども、行政側のスケジュールとして、いつまでに提言を受けとっていないと検討に間に合わないというのはあるのですか。そこのデッドラインに向けて、今走っているから、こういうスケジュールになるのだと思うのですけれども、行政側のスケジュールを確認させていただければと思います。","respondent":"平澤経理課長","answer":"私どもは、まさに工事の成績評定は、１０月１日から開始するところです。それが順調に進んでいくという大前提があります。","id":"exchange-043"},{"speaker":"あべ委員","kind":"質問","question":"そうすると、こちらとして出すデッドラインというのは、いつごろになってくるのですか。９月６日だと、本当にもうすぐではないですか。だから、どういう日程で動いていらっしゃるのかというのを伺ったので、平成２６年度当初を目指すというのは常識的にわかるので。","respondent":"平澤経理課長、中山総務部長","answer":"委員会運営にまで踏み込んだ答えになってしまうので、ただ、一般的にどうかということでまいりますと、こういった大きな変更をする場合には、事業者への説明は必須項目になります。議会へのご報告も必須項目ということになります。今、経理課長から、１つの節目ということで申し上げましたけれども、あくまでこれはこういうご議論を含めて、先ほどの委員会の中でもありましたけれども、そういう中でのご意見、それから試行の状況、そういうもの踏まえて。","id":"exchange-044"},{"speaker":"あべ委員","kind":"質問","question":"今の質問は、本来であれば行政側に聞くのは酷なことで、むしろ委員会あるいは委員長として、来年度に間に合わせたいから１０月までには私たちが出しておきたいのだという形で示して、〔「それで予定表をつくったんだ。このころまでに出したいから、こうしたいのだということを委員会の意思として言って、そのうちにこのスケジュールのことを言ってほしかったと私としては思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/812388?Template=document&Id=5952#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":39033,"voices":111}},{"id":"h25-20130828-17","meetingId":"h25-cm08","date":"2013年8月28日","dateIso":"2013-08-28","committee":"震災対策特別委員会","time":"午後 １時００分～午後 ３時０６分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","topics":[{"id":"topic-01","title":"の１「特定事件調査」","agenda":"の１「特定事件調査」","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"避難誘導ワークショップ実施ということで実績が示されました。平成１８年度から平成２４年度までと、２５、３２、２２、１３、１５、１６、７、これは全部足しても１３０です。これはどういう数字の捉え方として見ているのか。先ほどあったような気もいたしますけれども、改めてワークショップ実績で減っていることに対してどう思っているかについてお聞きしたいと思います。","respondent":"鈴木防災課長","answer":"これにつきましては防災課としても対応が必要と考えておりまして、この数が減ってきた主な背景としましては、当初、開始直後はしっかりと取り組まなければならないということで関心、注目が集まっていたのですが、今、過半数を超える町会が実施された中で。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"答えはそういうふうに言うしかないだろうとは思いますけれども、実際的に荏原地域のように防災危険度の高い地域はそれなりに活発化して行っているのかとか、地域別に出ていないですからわかりませんけれども、そうすると、やはり平成１８年度から始めているということで、早いところは７年前に行っているわけですから、今言われたように未実施のところに勧めるのもそれはひとつ大事なところですけれども。","respondent":"鈴木防災課長","answer":"委員ご指摘のように、一度訓練をすればよいというものではございませんので、過去にやった町会も今後も継続してやっていただけるように働きかけをするとともに、区としてもしっかりと支援をしていきたいと考えております。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問・要望","question":"６ページの（２）福祉避難所の2)で、ただし書きの後、「電源喪失により生命に危険が及ばない者」、これの対応と、それと「６.今後の取り組み」で一番最後の２行目ですけれども、福祉ボランティアということで検討を進めていくということですが、この福祉ボランティアのイメージはわかるのですけれども、専門性とか専門性でない部分とか、その辺をもう少し詳しく教えていただきたいです。","respondent":"鈴木防災課長","answer":"１点目の電源喪失により生命に危険が及ぶような方についての対応ですが、この想定はいわゆる医療的な機器ですね、人工呼吸器であるとか痰の吸引器、そのような方は電源喪失して機器が停止してしまいますと生命に危険が及ぶ影響が出てまいりますので。","id":"exchange-003"},{"speaker":"つる委員","kind":"質問・要望","question":"本日配られた中の災害時要援護者の定義のところと、それから５ページの1)名簿登録対象者、これは対象者の定義の違いというか、幅があると思いますけれども、その辺の考え方を教えていただきたいと思うのですけれども。","respondent":"鈴木防災課長","answer":"５ページの（３）、1)の対象者の方の定義ですが、これは防災課で主管をしております災害時助け合いシステムで対応できる方ということで要件を３つに絞っておりますので、その大きな違いは。","id":"exchange-004"},{"speaker":"つる委員","kind":"確認","question":"多分、何か別の機会にも似たようなことを確認させていただいて、今少し思い出しましたけれども、逆に、そうではない人たちの、この定義されている人たちの把握と連携ですね、区としてのそういったやっていただく側の機関との連携はどういうふうにやっていくのかというのと、あと、あわせて地域防災計画の１９６ページにあるところの定義と。","respondent":"鈴木防災課長","answer":"１点目、この災害時助け合いシステムで対応できない方の対応についての各課との連携ですが、基本的には先ほど２ページでご説明いたしましたように、各福祉部門、それから保健部門の通常業務の中でほとんどの方の把握ができておりますので。","id":"exchange-005"},{"speaker":"つる委員","kind":"質問","question":"すいません、あと１つ、ごめんなさい、聞き漏れてしまったのが、内訳とかはわかりました。そうした方の把握は通常業務の中で、これは防災課ではないかもしれませんけれども、保健センターで把握をして連携をとるという形でよろしいでしょうか。","respondent":"鈴木防災課長、大石荏原保健センター所長","answer":"今、委員からのご質問にありましたように、防災課だけでは把握や対応をし切れませんので、保健センター、それから健康課を含めた医療部門と連携をして、状況把握や対策についての協議を進めているというのが現在の状況です。今、防災課長からもお答えありましたように、優先順位をつけながら、やはりまず一番大切になるのは人工呼吸器をつけている方、この方たちに関しましてはある程度そういったことが実際に起こったときに、医療機関につながるまでの間。","id":"exchange-006"},{"speaker":"つる委員","kind":"確認","question":"ありがとうございました。では次に、避難所関係で、６ページのところで二次避難所になります。「妊産婦などの要援護者のうち」とありまして、その上で受け入れのときに、別のときにもいろいろ確認させていただきましたけれども、いわゆる文京区で今やっている妊産婦乳児避難所のような機能ですね。","respondent":"鈴木防災課長","answer":"前提となりますそういう方への対応ですが、今ちょうど区内の両医師会や、それから各病院、医療機関との災害時の連携会議の設立について、ご相談、協議を進めているところでございまして、その中で。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問","question":"２点お伺いしますけれども、１点は防災アドバイザーですが、大体でいいですけれども、高齢化が進んでいる中で、年齢はどのくらいの方がどのようにやっていらっしゃるのかを聞きたいのと、最後の６ページですけれども、二次避難所と福祉避難所の大体の受入人数です。お願いします。","respondent":"鈴木防災課長","answer":"そういう意味では、要援護者の方も適切な支援を受けながら、まずは身近なところでの安全確保をしていただいた上で、避難生活が必要な場合には状況に応じた各避難所への移動というような段階を追って考えておりますので、初動の段階での把握状況によりまして。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問","question":"もう１点のほうですけれども、とりあえずなさるということはわかっていますが、ただ、最悪のことを考えて、人数が多い場合はどうしようとかということが、この人数だからここまでというわけにはいかないので増やしていこうというお考えだと思いますけれども、それをちょっと心配させていただいているので、そのお気持ちはわかりますが、どのようなところを広げていくというのを具体的に。","respondent":"鈴木防災課長","answer":"実は今年度もその発想がありまして、一例ですが、区民大学の中に防災に対するコースを１つつくっていただきまして、今年、全６回の講座を、防災区民組織を通した働きかけではなくて、一般公募の集まる方への取り組みということで実施したところですので。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"参加していただくことも重要ですけれども、育てていくというのもアドバイザーに関してはとても必要だと思うので、ぜひそれは進めていただきたいということと、先ほど課長からちょっと出ましたけれども、物はあっても人がいないというのは困ると思うのです。避難所はできましたけれども助けてくれる人がいないというのがあるので、その辺は両方について考えていただきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"沢田委員","kind":"質問","question":"災害時要援護者名簿の作成のところで、この名簿登録者数が今４,０００名弱ということですけれども、先ほども昨年度から約５００名増えたということですが、この対象者が実際大体どれぐらいいて、そのうちの４,０００名という、特に登録を希望する方を除いた場合、上の２つの条件の対象者はどれぐらいいて、そのうちの４,０００名が登録されたのでしょうか。","respondent":"鈴木防災課長","answer":"毎年、年に１回、対象の方に通知を差し上げておりますが、前年度に登録された方は当然除外されておりますので、申しわけありません、単年度ごとの増減での把握をしておりまして、実態数が例えば障害者福祉課、高齢者福祉課で含まれる中の何人ぐらいが毎年の対象かというのを。","id":"exchange-011"},{"speaker":"沢田委員","kind":"意見","question":"その１万件の方が対象でということで、区としてはやはりこの対象の方全員に名簿登録をしていただけることを望んで、こういった名簿を作成しているのかと思いますけれども、そういうことであって、そのうちの現在の数の登録者ということをどのように考えられていますか。","respondent":"鈴木防災課長","answer":"それ以外の方につきましては、先ほどから説明しておりますように、各主管課や関連福祉施設等の連携という区内全体の資源の中で対応し、協力しながら講じていくというのが現実的な方法であると考えております。","id":"exchange-012"},{"speaker":"沢田委員","kind":"質問","question":"この名簿を作成ということで、ここの説明の中にも出てきますけれども、本人の了解を得るなどプライバシーの保護に配慮しながらということですけれども、やはり中には登録は別にしたくないという方もいらっしゃるのかと思いますけれども、そういった方に対しての対応はどういうふうにされているのでしょうか。","respondent":"鈴木防災課長","answer":"やはりそこの部分が気になって登録はという方が実際にはいらっしゃいますので、その方につきましては、例えば民生委員であるとか、それから先ほど申し上げました地域の中、近所付き合いの中での状況の把握や、そういう方がいらっしゃるという現状の把握ですね。","id":"exchange-013"},{"speaker":"沢田委員","kind":"質問・要望","question":"先ほどもちょっとありましたように、二次避難所のことで、想定数は特にまだ、これから施設を増やしていくということだったと思いますけれども、想定される人数は把握されているということでしたが、増やしていくということを説明されていましたが、大体の数を、どれぐらい人数が増えていくということは把握されているということでよろしいのでしょうか。","respondent":"鈴木防災課長、松代防災まちづくり事業部長","answer":"要援護者の方の把握というのは、先ほど申し上げましたように、基本的に今、区でいろいろな情報を総合して把握できているのが各課などの把握によります約４万１,６００人ですので、ただし、この方が全員二次避難所。したがいまして、その計画に基づいて今後はしっかりとその施設の受入体制を構築していくことが必要だろうと思いますし、また、そういう構築をしていく中で、さらにこの人数を上回る収容等の可能性があれば。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"災害時助け合いシステムによる災害時要援護者名簿の作成についてですけれども、今のやり取りを伺ったのですが、１万人の方に送付されているということでよろしかったのでしょうか。現状の登録は約４,０００人だということ。そうすると、残りの３万人といいますか、２万６,０００人といいますか、その方にはなぜお知らせの用紙そのものが届かないのか、伺いたいと思います。幾つかまとめて伺います。","respondent":"鈴木防災課長","answer":"設置が昨年で、報告書が出たのが３月ですが、これは内閣府で要援護者の支援に関する検討でいろいろな課題の洗い出し、それからそれに対応するための国と都、各自治体それぞれの役割分担についての主な項目の検討計画が示されたものですので、当然これとの整合性なり、また。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、マニュアルについてですけれども、国の報告書については一つのガイドラインとしてやっていくというお話でしたけれども、この委員会の６月１２日、今後の取り組みの中で、今後は業務確定マニュアル作成を行いますとありましたけれども、いわゆる災害時業務マニュアルとは誰がどのように動くマニュアルなのかご説明いただきたいのと、それと障害者、高齢者自身がどう動くのか。","respondent":"鈴木防災課長","answer":"具体的には来週９月２日と３日で各業務のグループごとに関係する課長と担当者に集まっていただきまして、今後のマニュアル作成についての手順、それからスケジュール的なものを説明しまして、その直後から既に作業に入っていただく。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、この災害時助け合いシステムそのものは避難所に行くまでの仕組みですから、そこからどうなるかというのは結局まだ示されていないのです。つまり、一体これはいつできるのかというのを改めて伺いたいと思います。こっちがいつできるのか、改めて伺いたいと思います。いざとなったときにそこに障害がある方、高齢者の当事者参加をぜひ位置づけていただきたいと思いますけれども、いかがでしょうか。","respondent":"鈴木防災課長","answer":"ただし、そこにつきましては各施設や医療機関につきましても、通常の発災時にいる利用者の方への対応がまずは第一でありますので、それに対応しながら、いかに区の全体の要援護者への支援をあわせて実施していくかというところを今相談しておりますので。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"数字のところは正直よくわからないので、後でもう１回確認します。改めて伺いますけれども、目標を設定してこのマニュアル、プランをつくる考えがあるのかどうか伺いたいと思います。非常に深刻だと私は思います。先ほど伺ったのでお答えがなかったのが、障害がある方、お年寄りの方々、ぜひ当事者参加でこのプランをつくっていただきたいと思いますけれども、この点についてもご説明いただきたいと思います。","respondent":"鈴木防災課長","answer":"目標を設定してマニュアルづくりという件についてのご質問ですが、委員がいう目標が何の目標を指すのか、ご質問に出ていなかったので。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん簡単な計画だとはとても思いません。ただ、遅れていると、重大な問題だというふうに、どんなふうにそこを考えているのか率直に伺いたいと思います。障害のある方が障害者のことを障害者抜きに決めないでほしいという位置づけがあると思いますけれども、どう生活していくかを決めるわけですから、ぜひ当事者参加をしっかり位置づけるべきだと思いますので、改めてこの点は伺いたいと思います。","respondent":"松代防災まちづくり事業部長、鈴木防災課長","answer":"それを今後どういう形で今まで以上にこういった方としっかりと向き合ってしていくか、これはさらに我々の務めで、しっかり取り組んでいく内容だと考えていますけれども。施設は施設なりの、自分の災害時の対応とあわせて地域への貢献がありますので、こちらで一方的に決められるものではありませんし、複数の法人と施設が相手ですので。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、まず検討過程を明らかにするということ、検討を公開して進めるということ、区が今どこを考えているのか、ぜひその公開を求めていきたいと思います。何がどういうふうな議論でそういう整理をしたのか、ぜひ改めてご説明いただきたいと思います。要するにこういうところを拡大していくということであれば、早くしていただきたいと思いますけれども、ぜひそこは具体的に伺いたいと思います。","respondent":"鈴木防災課長","answer":"区での取り組みや考え方、状況についての報告や公開というお話ですが、昨年度、地域防災計画を修正して、防災会議での承認をいただいて、議会に報告をしたのが平成２４年度末、つまり今年３月です。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に一言意見を述べますけれども、品川区が現在進めている業務マニュアル、これからどこまでどう進めるかわからないですが、災害時要援護者のマニュアル、ぜひ公開をして、当事者参加を位置づけて、意見を聞きながら、また、現状を共有しながら、何が必要なのか、どうすれば生命・身体・財産を守ることができるのか、そうしたことをぜひ公開の場で意見を言う場を設けて。","respondent":"鈴木防災課長","answer":"業務マニュアル自体が区民の方の支援のためにどういうふうな動きをするかというのは、まとまりましたら、区としてはこういうふうにしっかりと考えてこういう対応をします。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"話がごちゃごちゃなのです。今、マニュアルと言っているのは２つあるのです。区がどうするかの業務マニュアルと災害時要援護者のマニュアル、２つなのです。今、おっしゃったのは区のほうですね。では、災害時要援護者マニュアルも当事者参加、公開のもとで進めたらどうですかと。そこについて伺っているのです。先ほどから伺っているので、ぜひご答弁いただきたいと思います。お願いいたします。","respondent":"鈴木防災課長","answer":"災害時要援護者の防災行動のマニュアル、つまり要援護者の方ご本人の行動マニュアルにつきましては当然必要性は認識しておりますが、まずは区の対応と関係機関がどういう対応ができるか、それがはっきりしないと、あわせて、独立してできるものではございませんので。","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"災害時要援護者名簿の件についてですけれども、先ほどからいろいろ議論がありまして、防災課として高齢者福祉課とか障害者福祉課とかと係るところで、一定の要介護１から５、身体障害者の一定の障害を持った方の１級から３級が希望されるという条件のもとで名簿作成をしていますよということですが、それで、4)の個別支援プランの作成ということで、いわゆる先ほど。","respondent":"鈴木防災課長","answer":"各課との連携の進め方ですが、基本的には各主管課とも通常の行政業務の中で把握したり、対応についても考えている部分がありますので、防災課からの役割としては、それを全体調整しながら要援護者の方全体の把握と適切な役割分担ができるように調整するというのが。","id":"exchange-023"},{"speaker":"塚本委員","kind":"質問","question":"今の突合、名寄せということですかね、ということで、１人の個人名で皆様がこの人はどういう方かというのがわかるようになるという、名簿が１つに集約されるということで、それは大変進めていただくべきことだと思いますけれども、そこで、今、その後で答弁いただいた個別支援プランについて、これは個々人の要援護者、現在で言えば４,０００人弱いらっしゃる方。","respondent":"鈴木防災課長","answer":"これにつきましては、通常の各課の業務の中では一定程度のものは進んではおりますけれども、申しわけありません、防災課で全体を把握してしっかり調整するところまではまだ段階が進んでおりませんので、そういう意味では委員ご指摘のように。","id":"exchange-024"},{"speaker":"塚本委員","kind":"質問","question":"今、今後の検討課題ということでご答弁ありまして、まさに課題だと思いますけれども、やはり一元化して、名簿と同じようにプランも一元化というほうが普通に考えると支援計画とかそういう部分で非常にやりやすいし、いざというときに活用する上でも活用しやすいのではないかと私は思いますけれども、いろいろな個人の事情とかによって難しいというところもあるのかもしれませんが。","respondent":"永尾高齢者福祉課長","answer":"発災の当初の段階と、数日たってからの段階とで対応が異なってくるかと思います。それで、防災課のほうの災害時要援護者の名簿の個別支援プランは、発災当初の部分のプランかと考えています。","id":"exchange-025"},{"speaker":"塚本委員","kind":"意見","question":"そうすると、ごめんなさい、認識がちょっとずれているのかもしれないですけれども、個別支援プランは、防災課が発災直後に個々においてどういうふうに支援しましょうということのためにつくるものという認識で、まずは合っていますか。","respondent":"永尾高齢者福祉課長","answer":"防災課のほうでつくる災害時助け合いシステムの個別支援なので、その方の現状の状態を見ながらどうやって避難していくかという計画になると思います。","id":"exchange-026"},{"speaker":"塚本委員","kind":"質問","question":"今のご答弁を聞くと、やはり防災課で名簿と一緒に個別支援プランも一本化が望ましいのではないかと思いますけれども、その辺、どのようにお考えですか。","respondent":"鈴木防災課長","answer":"発災直後の、要は避難誘導に関する個別支援プランにつきましては、委員ご指摘のとおり、やはり防災課としてしっかりと全体像を把握して、一元管理しながら、各地域における対応をしていただける組織への情報提供をしっかりととれる体制を維持していきたいと考えております。","id":"exchange-027"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。よろしくお願いしたいと思います。どのようにその辺は、それは課題ということでしようがないことなのか、具体的に何かこうやってうまく受け入れていくというところが少しあればお示しいただきたいのですが。","respondent":"鈴木防災課長","answer":"ご質問の福祉避難所における具体的な対応の体制なりやり方ですけれども、現時点でこの各施設を指定させていただいたのは、委員ご指摘のように福祉に対応する人的資源であったり、ノウハウであったり、それから施設、設備であったり、そういうところに着目をしまして。","id":"exchange-028"},{"speaker":"塚本委員","kind":"意見","question":"ここを福祉避難所として避難できる体制ができるというのはすばらしいことだと思いますけれども、現実に受け入れられる体制をつくっていくというのは、私でもすぐにこうしたらどうだろうと軽々にはいえない問題だと思いますけれども、これからということなので、経験のある皆様の、施設の方々のお知恵を拝借しながら、ぜひ多くの方が避難できる体制を考えていっていただければと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"木村委員","kind":"質問","question":"災害時要援護者名簿の作成のことですけれども、これは１万人の方に通知をしていることをお聞きしました。これは年に一度なのか、それとも数回に分けてやっているのか、そのやり方を教えてください。","respondent":"鈴木防災課長","answer":"ただし、それ以外に登録を希望する方というのもありますし、４月、５月に通知をしまして、６月、７月ぐらいでその年度の名簿登録をしまして登録者数を確定はいたしますが、それ以外のタイミングでも。","id":"exchange-030"},{"speaker":"木村委員","kind":"質問","question":"プライバシーですからいろいろな情報、そういうものがやはり一番問題であろうかと思うのですけれども、どこどこにどういう人が住んでいるというぐらいの情報であれば、そういうことで法律に触れるようなことになるのかどうか、もしくは、私個人としてはある程度半強制的に、強制的はおかしいですけれども、そういうことで名簿というのか、そういうものをつくっていくべきだと思うのですが。","respondent":"鈴木防災課長","answer":"ですから、その部分については個人情報の扱いで問題というか、注意が必要なのは、そういう区以外の組織、警察・消防とか防災区民組織に提供する場合に当たる部分ですので、そういう意味では区では把握をしておりますし、万が一災害時の場合には、ご本人が登録をされていなくても。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"さっき聞き漏れたかもしれませんけれども、二次避難所と福祉避難所について、知的障害の方々、精神障害の方々、自閉症の方々、この方はどっちなのかと伺ったのですけれども、答弁がよくわからなかったので、どっちなのかということと、どうしてなのかということを伺いたいのと、例えば学校の保健室とかすまいるの畳の部屋ですとか、あらかじめ指定しておいたほうが非常にいいのではないかと思いますけれども。","respondent":"中山障害者福祉課長、鈴木防災課長","answer":"そんな中で、福祉避難所にはかもめ園ですとかかがやき園のような、もともと知的障害の方を受け入れている施設もありますので、場合によってはそこの対応になろうかと思いますし、そこでも環境設定が難しかった場合に。ですので、発災直後、一時的な安全確保のための受け入れとか利用者の方の対応はもちろん区役所の庁舎も対応できるようには考えておりますが、それ以後、避難所、つまり避難生活に関しては。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"発災時に、もちろんいろいろな用事があって区役所には来られるかと思いますけれども、東京、品川区が被災地になったとき、第一義的に通常業務が優先されると位置づけられていらっしゃるのか、それともそれぞれ職員の方々もどこにどう動くというのも決められているわけですから、何かそこの説明がよくわからなかったので、もう１回ご説明いただけますか。","respondent":"鈴木防災課長","answer":"それは災害対策本部、つまり区全体の災害対応をするための部隊の拠点ですので、そこは避難生活が必要になった場合には避難所生活ができる施設に移動していただくというのが現在の考え方です。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/433468?Template=document&Id=6438#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":42156,"voices":84}},{"id":"h25-20130920-4","meetingId":"h25-c-settlement","date":"2013年9月20日","dateIso":"2013-09-20","committee":"決算特別委員会","time":"午後 ３時３５分～午後 ３時４１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/230807?Template=document&Id=1370#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":2010,"voices":16}},{"id":"h25-20130924-6","meetingId":"h25-cm09","date":"2013年9月24日","dateIso":"2013-09-24","committee":"区民委員会","time":"午前１０時００分～午後 ０時１４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を60件抜き出しています。","topics":[{"id":"topic-01","title":"第５９号議案 平成２５年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第５９号議案 平成２５年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"この補正予算の前提になった、要するにこの交付金が平成２４年度終了予定だったものが、いわばぎりぎりの時点で交付されることになったわけですけれども、その理由は、国はどんなふうに説明しているのか、理由というか、目的というか、そこを伺いたいのと、品川区がそういう状況になったので提出し、内示を受けたとありますけれども、提出したのがいつごろなのか、その経過を伺いたいと思います。","respondent":"米田商業・観光課長","answer":"国が延長している考えですけれども、消費者庁が創設されてから消費者センターを支援するという意味では、まだその支援の取り組みが始まったばかりであって、この辺のところの基金等による支援の下支えなしには取り組みがまた後退する懸念もありました関係で、また再度。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"消費者庁ができて、消費者行政といいますか、それへの支援を強めていこうという流れのご説明ですけれども、ご説明の中で、なかなか都市部ではまだまだ充実していない課題があるのかというご説明が、今、ありましたけれども、特に都市部ではどういう課題があるのかご説明いただきたいのと、消費者センターの機能を充実させるわけですけれども、具体的に最近多い相談の傾向とか、中身とか。","respondent":"米田商業・観光課長","answer":"明日またご説明しますが、高齢者になりますと、なかなか判断能力ということでは年齢を重ねるにおいて鈍ってくることもありまして、高齢者の相談が非常に増加しているところもあります。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に一言。インターネットのトラブルであったり、高齢者の相談であったり、また消費者センターそのもののＰＲの強化だったり、消費者を守る取り組みは非常に大事だと、必要だと思いますので、いろいろ相談、事例や実態に見合った対策を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"石田（し）委員","kind":"質問","question":"基本的なところなのですが、改めてお聞きしたいのが、消費者センターと品川区行政の関係はどのような位置づけで運営がされているのか、その辺をまずお知らせください。お願いします。","respondent":"米田商業・観光課長","answer":"消費者センターは、区の内部機関の一つです。いわゆる、今、所長ということで係長の職員が配属されておりますけれども、その上位に所管しているところが、現在は商業・観光課であるということで、地域振興事業部の中の組織の一つに位置づけられているものです。","id":"exchange-004"},{"speaker":"石田（し）委員","kind":"質問","question":"幾つか購入されている例があると思うのですが、今回、購入というのは、あくまで国から交付金ということで購入されるのか、それとも、リースと購入を照らし合わせたときに購入のほうが効果があるというか、削減できるということで購入されるのか、その点、購入に関しての考え方を教えてください。","respondent":"米田商業・観光課長","answer":"大分、プリンターも消耗品化してきておりまして、単純に比べてどちらが安いかということもあるかとは思うのですけれども、日進月歩の世界で新しいものがどんどん出ているという中では、大型のプリンターは目的・用途も限られておりますので、ある程度最初に買って。","id":"exchange-005"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そういった中で、本当に電車内での１５秒のＣＭが効果てき面なのか、それとも、例えばケーブルテレビでの何らかの啓発のほうが効果的なのか、そういった幾つか広告のやり方がある中で、今回、バスのもともとあるものをさらに拡大していくことと電車内でのテレビ広告という２点の広告が出ているのですが、その点は、区としてはどのように、今回、２つを選択して。","respondent":"米田商業・観光課長","answer":"今回については、電車内の限られた時間ですけれども、スポット広告も打つというようなことで、ある種、試験的に１カ月ということもありますので、それがどれだけ認知性が高まったか、当然、ビジョンの会社は。","id":"exchange-006"},{"speaker":"山元委員","kind":"質問・要望","question":"事業予算の中で相談員の謝礼で五十数万円ということですが、これは先ほどおっしゃっていた週１回のベテランの方のためのものなのか、その目的を教えていただきたいのですけれども。","respondent":"米田商業・観光課長","answer":"ただ、ある程度経験が物を言う世界ですので、その新人の相談員の方の相談等に対する指導も含めプラスアルファということで、週４時間、月１６時間の従事をお願いしているものです。","id":"exchange-007"},{"speaker":"山元委員","kind":"質問","question":"すると、あくまでもその方が指導とか、それからいろいろキャリアがおありになるので、その人のためのこの五十数万円ということで、そうすると、先ほど週１６時間、変な話、細かくて申しわけありませんが、どのぐらいになる。要するに１時間単位というか、週１６時間でどのぐらいになるのですか。","respondent":"米田商業・観光課長","answer":"こちら、報償費という形で交通費等は一切度外視するような形で、１回いらしていただいたことに対して、たしか私の記憶では１万１,２００円だったかと思いますけれども、大体、時給当たりで２,８００円ぐらいで、それが交通費込みでというようなことで計算しています。","id":"exchange-008"},{"speaker":"山元委員","kind":"質問・要望","question":"今、時給２,８００円という、もちろんキャリアがおありになってそういうことに使っていただくので、それが妥当かどうかはわからないのですけれども、いずれにしても、ぜひその辺を活用していただきたいと思います。","respondent":"米田商業・観光課長","answer":"いわゆる相談の対応の仕方であったりとか、そういうものについては上がってくるということで、そんなにたくさんはありませんけれども、上がってきましたら、「こういう対応についてのご指摘がありました」というようなことで全体で共有するようにはしています。","id":"exchange-009"},{"speaker":"山元委員","kind":"質問・要望","question":"これは要望ですので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"今のお話の続きなのですけれども、時給２,８００円というのは一般的に考えると、大変なお仕事だとは思いますけれども、少しお高いのではないかと思いますが、その２,８００円に交通費込みということですが、キャリアも含めて理解ができるようなご説明をいただきたいです。その金額に関してですね。申しわけないです。","respondent":"米田商業・観光課長","answer":"別に時給というわけではないのですが、それぐらいの数字になるように１回当たりの報償費ということで設定したものですが、いわゆる相談員の世間的な相場から大きく外れているということではないと考えています。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。要するにキャリアがあって幅広くいろいろな知識があるということを実際にお話を聞いたのですけれども、これから先、この方はどうなのでしょうか。こういう、先も続けていっていただけるのかということですが、その辺はどうなのでしょうか、お聞きしたいです。お願いします。","respondent":"米田商業・観光課長","answer":"そういった意味では、もうその期間を過ぎてあります。で、あとは私ども、その方の可能な範囲での引き続きの従事ができるような形であれば、そちらのほうはお願いしていきたいと考えているものです。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"できればそういう方にこれからも続けていっていただいて、次のそういう方が出てきていただけるような最善の努力を続けていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この消費者センターとシルバーセンターの連携、高齢者いきがい課になるのか、高齢者福祉課になるのか、そこら辺のところ、消費者センターは割合待っている立場ですよね。シルバーセンターを使っている高齢者の方に対して今もやっているとは思うのですけれども、何ら関連性、今やっているのと今後の展開をもう一度教えていただければと思います。","respondent":"米田商業・観光課長","answer":"あわせて、そういう区が所管している、関係する、いわゆるシルバーセンターですとか、あるいは外郭にはなりますが、社会福祉協議会、こういうところとは密に連携、情報交換をしつつ、近いところにそういう方々がいらっしゃったら。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"シルバーセンターというと、割合と高齢者の方が来ていても、自分たちの会でというか、例えばこういう話を余り受けてくれないのかというメンバーが多いような気がするのです。その辺、うまくお話を詰めていただいて、万が一、何しろ起きないような対応をこれからもぜひお力添えをいただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"消費者センターの強化は、今、必要なことだと思いますので、賛成です。あわせて、今回、補正にはないけれども、ぜひ商店街とか、中小企業とか、こういう支援もしっかり考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-02","title":"「品川区地域安全のつどい」の開催","agenda":"「品川区地域安全のつどい」の開催","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけ確認したいのですが、そもそもこの「地域安全のつどい」は誰のために、何の目的でやられているのかというのが実はあって、これは多くの参加者の方たちは、私が知るところによると、ほとんどが常に地域安全の運動を積極的にしていただいている方たちが基本的にそこに来て、結局は身内ですね。","respondent":"上垣外生活安全担当課長","answer":"そのために、一時的にはこの招待する方にありますように、防犯協会関係者の方を中心にお呼びいたしまして周知活動を行います。もちろん、それに伴いまして、この方たちを通じて、区内に広く犯罪の発生状況、防犯のための手法などを広めていっていただくというのが目的です。","id":"exchange-017"},{"speaker":"石田（し）委員","kind":"質問","question":"そうすると、基本的には会員の方対象に、地域の安全運動はこうあるべきとか、こういうふうにやってもらいたいとかというようなことを会員の皆様に伝えるためのつどいという認識でよろしいのでしょうか。","respondent":"上垣外生活安全担当課長","answer":"はい、そのとおりです。基本的には防犯協会の関係者を中心として周知をするのが目的です。","id":"exchange-018"},{"speaker":"藤原委員","kind":"質問","question":"目的もよくわかりました。それで４の内容なのですけれども、この地域安全のつどいに、まずは何で対談・歌謡ショーをやるのでしょうか。そして、歌謡ショーのゲストの方に幾らぐらい予算をつけているのでしょうか。何で大月みやこさんを呼んだのか。","respondent":"上垣外生活安全担当課長","answer":"第１点目の、歌謡ショーで大月みやこさんを招致する理由です。","id":"exchange-019"},{"speaker":"藤原委員","kind":"確認","question":"課長の説明でよくわかりました。大月みやこさんが来てくださるから、それで呼べるのだ、集客できるのだということでいいわけですよね。改めて確認ですけれども、次もいろいろなものが出てくるのですけれども、そのときはまたそのときで聞きますけれども、基本的には歌謡ショーをやらなければ集客は厳しいという現実があるということも把握していかなければいけないのでしょうか。そこを確認させてください。","respondent":"上垣外生活安全担当課長","answer":"必ずしも歌謡ショーでなければ人を集めることができないということではないと思われますが、今までの経験則からして、やはりこういった方法をとるのが一番ベストであろうという考えのもとに開催させていただいているものです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"「品川区地域安全のつどい」ということで、「目的」にある「犯罪の発生状況および運動の目的などを周知し」とありますけれども、最近の犯罪発生状況や特徴、そこをご説明いただきたいのと、それとこのつどいがどうかかわってくるのか、歌謡ショーの話もありましたけれども、去年参加された方も「え、」という話は私も聞きまして、やはり、まずは犯罪の発生状況はどういう特徴なのか。","respondent":"上垣外生活安全担当課長","answer":"こういった傾向から、こういった犯罪の状況、被害の状況を知っていただくために、例えば今回のプログラムの中で寸劇をする予定にしておりますけれども、この中では、振り込め詐欺に関する事例をもとにした寸劇を想定しておりまして、どういった形で皆様が騙されるのか。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"振り込め詐欺にしろ、ひったくりにしろ、万引きにしろ、本当に被害に遭われた方の話を聞くと、人生を狂わされるすごい思いをされている方が大勢いらっしゃるのです。もちろん大勢集まっていただきたい、大勢集まっていただくことで趣旨を伝えることができるという意味合いもありつつも、やはりこういうスタンスを考え直す時期に来ているのかとも思うのですけれども、そういった議論はあるのでしょうか。","respondent":"上垣外生活安全担当課長","answer":"現段階では、こういった形での寸劇、実際の役者による受け答えを見て、実際の被害の状況を見ていただくのが一番効果的と考えています。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問・要望","question":"我が会派で藤原委員からも対談・歌謡ショーは集客の目的ということで、では、第２部のほうを聞いてみたいと思うのですけれども、２００９年から２０１０年、２０１１年、２０１２年と見せていただきまして、第２部のほうの講話等も「泥棒の稼げないまちづくり」とか、防犯員などの先生の「住まいの防犯」とか、毒蝮三太夫さんの防犯講話、あとは去年、２０１２年でしたか、防犯落語。","respondent":"上垣外生活安全担当課長","answer":"小宮先生からは、「身近な犯罪から身を守るための手法」ということで、先生の専門の分野であると思われますが、この話をしていただく予定としております。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問","question":"この人選に関しては、毎年、目的はわかるのですけれども、年々見てみるとすごく広範囲に考えられるのですけれども、人選に関してはどのようなお考えなのですか。","respondent":"上垣外生活安全担当課長","answer":"人選といたしましては、決定的な要因はございませんので、この趣旨に沿った方を幹事署である警察署と私どもで相談して決めているものであります。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問・要望","question":"内容的にも沿っていると思うので、それを意識しての講話はこれから毎年、毎年、今年でこの企画は１８回目ですか、その辺をお聞きしたいのですけれども、それに関する人選をもう少しコアな、第３部もわかるのですけれども、第２部はしっかりした防犯とかそういうことの周知に、私などの思いとしては、つまりそういうことに沿っていただきたい、目的に沿っていただきたいと思うのですが。","respondent":"上垣外生活安全担当課長","answer":"回数につきましては、今回が１８回目と認識しております。中身につきましては、もちろんこの目的に沿った内容としていくように常々考えております。","id":"exchange-025"},{"speaker":"山元委員","kind":"質問・要望","question":"」という思いがするのですが、そういう具体的なことをなさっているのか、それとも、これからしようとしていらっしゃるのか、何かその辺の考えはどうなのでしょうか。","respondent":"上垣外生活安全担当課長","answer":"その場に実際に警察署の担当の者が参ってご説明したり、あるいは私も直接招かれていってお話する機会をいただいております。これからもこういった機会を設けていただいて、どんどんこういった手口、被害に遭わないような対策をお話させていただきたいと考えております。","id":"exchange-026"},{"speaker":"山元委員","kind":"質問","question":"ごめんなさい、しつこいのですが、実際、今おっしゃったように、お年寄りの多いところにお話していただくということですが、でも、大体、地域によって若干違うと思いますけれども、お年寄りは何度も何度も言っても、なかなか頭に入ってこないというか、やはり言っていくしかないかと思うのですが、現実的に今までの数でいいのですが、大体どのぐらい地域センターに集まるのか、また。","respondent":"上垣外生活安全担当課長","answer":"具体的な数は、申しわけございません、正確なものは把握しておりませんけれども、私がこれまでお話させていただいたのは１回あります。既に予定が入っているものもありますので、積極的に話をさせていただきたいと考えております。","id":"exchange-027"},{"speaker":"山元委員","kind":"質問・要望","question":"最後です。地域パトロールの方も流していただいて、気をつけましょうという、そんな感じなのですが、もうちょっと身近な、本当に切羽詰まったというか、振り込め詐欺に遭うと大変なんだよみたいな、何かもう少しアナウンスを、今のだけではなくて、何か工夫をしていただければと思いますので、これも要望ですけれども、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-03","title":"(2)「大崎盛り場環境浄化キャンペーン」の開催","agenda":"(2)「大崎盛り場環境浄化キャンペーン」の開催","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"この題名というか、報告で「大崎盛り場」と出ていたのですけれども、「大崎盛り場」となったときに、どこかと思います。「大崎盛り場」とはどこだ。文章を読んでいると、「五反田有楽街」と出るのですけれども、「大崎」とは、大崎署が所管するからという意味で、まず、いいのでしょうか。","respondent":"上垣外生活安全担当課長","answer":"管轄警察署が大崎署ですので、このような表題としています。今回、運動の中心地となるのは、先ほど申し上げました東五反田一丁目地区が中心となりますけれども、この活動そのものは、大崎署管内全体で実施するものであります。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"「大崎盛り場環境浄化キャンペーン」は初めてだと思うのですけれども、このキャンペーンをしようとした背景について、まずお伺いします。","respondent":"上垣外生活安全担当課長","answer":"背景につきましては、まず１点が、今回、地域安全運動という形で、きれいなまちは犯罪を起こさせないということでするものと、かねてから大崎署でこういった行事をやりたいと考えていたのですけれども、今回、この機が熟したということで実施するものであります。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"機が熟して初めてやると。いいですね、区民の気持ちも高まってすばらしいと思うのですけれども、目的の中で「違法風俗店の営業」とあるではないですか。「違法風俗店」とは具体的にどういうことなのですか。","respondent":"上垣外生活安全担当課長","answer":"具体的には、今、検挙の対象となっているのが例えば違法な客引き等、こういったものが顕著な特徴となっております。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"質問の仕方が、私が悪かったかもしれないですけれども、「違法風俗店」は具体的にはどういうことですかと聞いて、それがイコール客引きですと、客引きをしているところが違法風俗店と思っていいのですか。今の答弁だと、客引きがという、迷惑な客引き。","respondent":"上垣外生活安全担当課長","answer":"違法行為についてはいろいろ種類がありますので、例えば無届け、無許可、こういったものも違反の対象となっております。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"それを１点答えてください。違法行為がきちんと認められるのであれば、それを摘発するのが警察の仕事だから、それをまずどんどんやるべきだと思うのですけれども、いかがですかということと、もう１点は、課長、当然それとは別に、区民が約５００人参加しますよと言うのですけれども、これをやって何を区民に求めるのですか。だけれども、これと歌謡ショーはどういう関係になるのかもお伺いします。","respondent":"上垣外生活安全担当課長","answer":"１点目の警視庁が取り締まるとかそういうことですが、この点につきましては、もちろん大崎署のみならず警視庁の本部においても取り締まり活動を実施しているところであります。決して取り締まりをやらないでこういうキャンペーンだけやろうという趣旨ではございません。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問・要望","question":"課長、これをやるのだから、もちろん五反田の有楽街に行かれたことはありますよね。私は思うのですよ。ですけれども、これは名指ししてしまっているではないですか。だから、すごくある意味、イメージダウンにならなければいいと、五反田の地域の全部ではないですけれども、そういう怖さもあるので、うまくやっていただいて、どういうふうにこのキャンペーンをやることによって本当にまちが浄化されていくか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、ぜひうまく意識を持ってもらいたいのですけれども、ただ、今回参加する人たちは、もともとその対象ではない人たちがほとんど来てくれるわけですよね。ですから、対象になるような業種、それから、悪質な客引きをやっているようなところはこの中に入ってこない。警察としては警察の対応もありますけれども、品川区としてどう考えていくのか。具体的に言うと、新宿で条例をつくりましたよね。","respondent":"上垣外生活安全担当課長","answer":"条例化というお話をいただきました。現段階では、現在の法令に基づいて必要な指導・取り締まりを行いまして、これで十分ではないという実態があるようであれば、そういったことも検討する余地があると思いますけれども、現段階ではそういう段階ではないと考えております。","id":"exchange-035"},{"speaker":"鈴木（真）委員","kind":"質問","question":"地域の方と現段階もひどいのではないかというお話もあるけれども、そこら辺が地域の方と警察というか区としての感覚としては、差があるのかという答えに聞こえてしまうのだけれども、ことに地域振興事業部というのは地域の方からのお話が一番入ってくる部署だと思うのですけれども、例えば地域の中での区政協力委員会、区政懇談会とか、そういうところはそんなに話が出てこないものなのですか。","respondent":"上垣外生活安全担当課長","answer":"区政協力委員会等でのご意見というお話でしたけれども、私の知っている限りでは、そのような意見は上がってきていないのが事実です。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"意見","question":"そういうときに町会長クラスは控えてくれているかもしれないですけれども、割合と我々の耳、私は五反田とはちょっと離れた地域にいますけれども、そういう人たちからも話は結構入ってきます。その方たちからも、少し品川区の条例はどうなのという話は聞かれる中で、今の答えだと、非常に消極的、区民の方の意見が伝わってこないのかという気がするので、そこら辺、もう１回お願いします。","respondent":"中川原地域振興事業部長","answer":"警察と区とのこういった安全・安心のまちづくりについての考え方なのですけれども、ご案内のとおり平成２３年３月に４警察署と共同宣言しまして、先ほど来ご質問がありましたが、取り締まりとかそういった現場の対応については警視庁が。","id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先ほど言ったように４署との覚書をつくったというのも、すごく品川区としてはいいと思いますし、これをやることによって地域の方も、区としても警察署も一生懸命やっているのだということを意識してもらえることは非常にいいと思うのですけれども、ぜひ１点だけ、件数が減っていって、それと同時に万が一減らなかったときには。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ほかの委員からもありましたが、タイトルは「大崎盛り場」ですよね。五反田の有楽街だったら「五反田の盛り場」と言ったほうが明らかにわかるではないですか。「大崎」と言ったら、どこだろうとなってしまいます。であれば、行政用語を使わずに、しっかりと区民がわかりやすいように、こういった大きいタイトルでは考えてやっていただきたいと思うのですが、改めてその考え方を教えてください。","respondent":"上垣外生活安全担当課長","answer":"今後、こういった行事を行う際は、表題のつけ方をわかりやすくしていきたいと考えています。今回は、この当初の計画で実施させていただきたいと思っているのですけれども、次回からは検討していきたいと考えております。","id":"exchange-039"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは要望です。例えば最後、「警視庁生活安全部幹部等」で来賓を一くくりにすると思うのですが、これはあえてここに個名を出されているということは、私の中では来賓はこの人たちだけだということで認識しているのですが、あくまで声をかけている人たちというのは来賓という位置づけではなくて、協力してもらうということで位置づけをしているのか、その点だけ最後に教えてください。","respondent":"上垣外生活安全担当課長","answer":"それ以外の方については、来賓といいますか、あるいはパレードの参加者といいますか、表現はいろいろあり得ると思いますけれども、参加を広く呼びかけていきたいと考えております。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、やりとりの中で、平成２３年３月に共同宣言をしたというご説明がありましたけれども、それはその都度タイトルは伏せるのかもしれませんけれども、「大崎盛り場排除共同宣言」になるのか、どういう宣言なのか、改めていつ、どのように宣言されたものなのか、その内容は、そもそも宣言だから文面があるのかと思うのですけれども、どういう文面なのか、そこを伺いたいと思います。","respondent":"上垣外生活安全担当課長","answer":"共同宣言の正式な名称につきましては、「品川区民の安全向上に関する協働宣言」となっておりまして、これは平成２３年３月に区と４警察署との間で締結させていただいたものであります。今回のキャンペーンで予定されます宣言とはまた別のものです。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回の見立ての宣言は、どういう名前の宣言なのか、いつ、どのように、誰がつくられて、どういう内容の文面なのか、そこをご説明いただきたいと思います。","respondent":"中川原地域振興事業部長","answer":"今回、大崎警察署が幹事署になって、新たに「盛り場」ということについての取り組みをやりたいということなので、区と幹事署の大崎署で相談してこの１０月１４日に向けてキャンペーンの準備を進めてきたというのが本日の報告の内容です。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問","question":"私の聞き間違いだったのか、初めの説明で、大崎盛り場、解除だったか、何とか宣言というのが、では、そういうのはなくて、全体の今言った計画だと、そういうことですか。それとも、このキャンペーンの中に何かそういう宣言をするという、そういうことで、要するに「調印式」と書いてあるので、何かアピール文もあるかとは思うのです。では、当日も含めてもう一度ご説明いただけますか。","respondent":"上垣外生活安全担当課長","answer":"平成２３年３月に結びました宣言とはまた別の趣旨で宣言をいたすものであります。当事者としましては、警察署と、区と、料飲組合との中で、今、調整をしている最中であります。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問","question":"要するに当日、式典の中で宣言というかアピール文を、今、発表するということだと思うのです。その宣言の内容とか、趣旨とか、もちろん当日、それを決めるわけですから、今の文では「（案）」かもしれませんけれども、どういう中身のものを決めるのか、いずれにせよ、その趣旨はそれ以前に何を決めるのかがわからないので、そこをご説明いただけますか。","respondent":"上垣外生活安全担当課長","answer":"宣言の中身につきましては、まだこれから詰めていっている最中でありますけれども、大まかな柱といたしましては、犯罪のないまちにしよう、そういった内容を柱にいたしまして、その細目を詰めているところであります。","id":"exchange-044"},{"speaker":"山元委員","kind":"質問","question":"先ほど中塚委員もおっしゃっていましたけれども、調印式があるということで、実際はそこで調印された、例えばその後、まちのお店にキャンペーンしたから反対だとか何か、張る物というか、そんな、今おっしゃったようなお話ではないけれども、そんなような内容の物を何か張りつけるというか、こういう調印をしましたので、うちの店は反対だよとかと何かそういうことまで考えていらっしゃるのですか。","respondent":"上垣外生活安全担当課長","answer":"具体的な表示をするか否かについては、検討はしておりません。","id":"exchange-045"},{"speaker":"山元委員","kind":"質問","question":"なさっていない。これだけいろいろな来賓の方にいろいろと地元の連合会長に出ていただくわけですから、やはりまちを挙げてということであれば、そういうもの、うちは反対だよというもの、賛成するところはないとは思いますけれども、そういうこともアピールすることは、やはりこういうキャンペーンをやるわけですから張るとこまで考えていくべきではないかと思いますが、いかがですか。","respondent":"上垣外生活安全担当課長","answer":"ただ、これを１店舗ごとに表示することについてはいろいろよろしくないと思う方もいらっしゃるのではないかというところです。かえって攻撃を受けるのではないか、こういったような形で、その表示につきましては、機運の盛り上がりに応じまして実施していきたいと考えております。","id":"exchange-046"},{"speaker":"山元委員","kind":"質問","question":"機運はぜひ盛り上がってもらいたいと思うのですけれども、やはり生活安全担当課長の中で張ることによっていろいろ被害とおっしゃっていたのですけれども、それを今度は逆に守るのが警察だし、追放というか、それをするためには、それは勇気が要ることかもしれないけれども、大事ではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"}]},{"id":"topic-04","title":"区立総合区民会館および区立体育館における指定管理者のモニタリング・評価結果","agenda":"区立総合区民会館および区立体育館における指定管理者のモニタリング・評価結果","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"いわゆる決算としての要素が強いのかどうか、そこを１点伺いたいと思うのです。総合区民会館も、区民の比率が上がったとおっしゃいますけれども、それは数値的には上がってはいるけれども、まだまだとりにくいという話もよく伺うのです。つまり、この総括シートそのものは指定管理者が作成しているという、そういう位置づけだったのでしょうか。よくわからなくなってしまったので、ご説明いただきたい。","respondent":"安藤文化スポーツ振興課長","answer":"このシートの位置づけと申しましょうか、報告の意味と申しましょうか、これは品川区指定管理者制度活用に係る基本方針、平成１７年７月２９日に決定されています。","id":"exchange-048"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひガイドラインの様式そのものをできるだけわかりやすく常に改善していただきたいと思うのですけれども、その点を１点伺いたいと思います。もう一つ、このつくり方も、結局、ヒアリングをして区がつくると。区民のための施設ですから、適切な利用率、利用状況といいますか、１００％では、大体７割を超えるととりにくいというのが実感だと思うのですけれども、どこかにラインがあると思うのです。","respondent":"安藤文化スポーツ振興課長","answer":"それから今の総合体育館の利用料の話ですが、これも「評価の視点」のところでたくさん項目があって、予算の財政の視点はどうかというような問いに対して私どもが考えるには、指定管理者の目的の一つの経費の節減は指定管理者の大きなものです。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり納得いかないと思います。指定管理者からヒアリングで聞いて何らかの調整の中にはいろいろ計画があって議会に報告するときに、このシートでは実態がわからない。ぜひそこは改善していただきたいと思いますけれども、改めていかがでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"このシートにつきましては、先ほどもご説明しましたけれども、全庁的なシートの中でやってあります。その意見がございましたことは企画当局にも話を申し上げます。","id":"exchange-050"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは区行政目線ですよね。彼らに対して必要があると。これは図っていくのは指定管理者ですから、指定管理者目線になります。それは確かではないのであれですが、もちろん総合体育館においてはものすごくいい経営状況だというのは私も認識している中で質問しているのですが、その辺の改善も含めてぜひ検討していただきたいと思うのですが、今後のもしビジョンがあればお答えいただければと思います。","respondent":"安藤文化スポーツ振興課長","answer":"先ほどの表現方法だとかそこら辺も、来年度に向けてはちょっと研究させていただきたいと思っています。","id":"exchange-051"}]},{"id":"topic-05","title":"品川歴史館特別展「大井に大仏がやってきた！ ─養玉院如来寺の歴史と寺宝─」","agenda":"品川歴史館特別展「大井に大仏がやってきた！ ─養玉院如来寺の歴史と寺宝─」","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"今回、大仏のこういうイベントを特別展として品川歴史館でするわけですけれども、本家本元の如来寺には担当課長として伺いましたか。もし伺ったのであるならば、どういう感想を持ったか教えてください。","respondent":"安藤文化スポーツ振興課長","answer":"私も実際に歴史館の副館長の柘植と如来寺に行ってきました。そして、その住職にお会いしまして、如来寺のお話だとか、また、先ほど冒頭に言いましたけれども、ここには本当に大きな仏像がお寺の本堂の中に５体おさまっているというものでございました。","id":"exchange-052"},{"speaker":"藤原委員","kind":"質問・要望","question":"だから、これを機会に、やはり前回も委員長のお計らいで観光をやらせていただきましたけれども、その観光の一つという形にこれをどうか結びつけていただきたいということを大井出身としては思うのです。最後に、その辺はいかがですかということを担当課長と、それとせっかく所管の課長がいらっしゃいますので、お二人にそれをどういうふうに結びつけていくかということをお伺いして終わりたいと思います。","respondent":"安藤文化スポーツ振興課長、米田商業・観光課長","answer":"そんな中で、また特別展を契機にそういうコースの中に入れていただいて、区民の方に知っていただきたいと考えています。観光担当といたしましても、こちらの特別展、十分、観光協会とともに拝察させていただきまして、今後の事業の取り入れというようなことでは、ほかの寺社等の見学等のツアーも随時行っておりますので。","id":"exchange-053"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり地域にいる方は、自分たちが大事にしてきたものが紹介されるのはすごくうれしいことですから、ぜひこれを機にいろいろなところにも目を向けていただきたいと思うのですけれども、この特別展の選考は、やはりこういう掘り出し、掘り起しが大事だと思うのですが、どういうふうに決めていらっしゃるのか、そこを伺いたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"この特別展は、年に１回ずっとやってまいりました。そして、歴史館の企画展ならびに特別展の事業につきましては、歴史館の専門委員会があります。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問","question":"このせっかくの特別展ですけれども、区内の小中学生の参加、そういう機会があるのかどうかをお伺いします。授業の一環としてですけれども、お願いします。","respondent":"安藤文化スポーツ振興課長","answer":"情報提供として、こういう特別展については議会報告ならびに皆様に周知していますので、そこら辺は周知されると思いますけれども、今の段階では子どもたちについては自主研究ということで進めます。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問・要望","question":"今、働きかけのお話ですけれども、できれば、せっかく区内にいいものがあって、歴史館に行って特別展ということで、こういうチャンスを活かしていただいて、区内の学校等にも働きかけていただき、参加していただければいいと思いますので、その辺を要望としてよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"向副委員長","kind":"意見","question":"今回、私も大変楽しみにしているのですが、海外向けとか、海外の方がここといって従来どおり訪れれば対応していただけるのか、それとも、これだけ力を入れていただいていて１カ月半にわたる公開ということなので、特別な対策を今回は考えていらっしゃるのか、そこを簡単にお願いします。","respondent":"安藤文化スポーツ振興課長","answer":"先ほどの話ではございませんけれども、関係所管と連携をして、より海外の方にも来ていただけるような工夫をしていきたいと思っています。","id":"exchange-057"},{"speaker":"向副委員長","kind":"質問","question":"淡い期待があったのですが、文化スポーツ振興課長の答弁はちょっと残念です。なので、広告を出すにしても、空港だったり、駅だったり、ポスターを張ると結構お金もかかるので、そのあたりは今後の課題ということで、一つのきっかけとして考えていただければいいと思うのですが、いかがでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"その展示のための一部ではありますけれども、英語版は用意しています。今後、特別展などに特別にそういうものができるかどうかは研究させていただきたいと思います。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"伺いたいのは、どのような可能性を、現在、検討されていらっしゃるのか、ぜひその中身を伺いたいと思います。明日もまた少し説明しますけれども、やはり大事な分野で、しっかり進めていきたいという思いもありますので、現状考えている問題意識や、現状の把握や、そこを伺いたいと思います。その辺も「検討する」ということの中身に含まれているのかとも思いながらも、現状の検討の中身を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"藤原議員と渡辺議員から、東京オリンピック・パラリンピックの誘致に絡んで、八潮地区の中で実施されることから、八潮との関連性がもし聞ければ、その辺も確認させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/972690?Template=document&Id=2676#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":40755,"voices":159}},{"id":"h25-20130924-7","meetingId":"h25-cm09","date":"2013年9月24日","dateIso":"2013-09-24","committee":"厚生委員会","time":"午前１０時００分～午後 ３時１２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"井上委員","kind":"質問","question":"ですから、そこのところから設計に至る段階で認識で随分変わってくるのかなというふうに思っていますので、グループホームというものを区はどう捉えているのか、そこの認識をお願いします。","respondent":"中山障害者福祉課長","answer":"グループホームの５床についての認識ということですが、知的障害者の方が親亡き後の生活の拠点としてグループホームは今後も整備していく必要があると考えております。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"質問の仕方がまずかったのかなと思うんですが、５床というベッド数でカウントしていくのか、住宅として、住まいとして位置づけているのか、区はどちらと捉えているのですかという質問をさせていただきました。","respondent":"中山障害者福祉課長","answer":"あくまで住まいという捉え方で考えております。","id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"特に特性を考えると、やはり外の障壁を、その人が生活、さっきもちょっと担当の方に伺ったら、洗濯とかも共用で、それはいたし方ないとして、生活をする中で変えていってもらいたいと言われましたけれども、こういった特性を持っている人たちは、自分を変えるのではなくて、周りを変えていくということが社会障壁をなくしていくという今の障害者差別とか、対処法とか。","respondent":"中山障害者福祉課長","answer":"今回、設計するに当たりまして、できるだけ居室部分をある程度の広さを担保することと、収納スペースをとることも考えまして、その結果、水回りについては共用でいいだろうということで落ち着いたところです。","id":"exchange-003"},{"speaker":"井上委員","kind":"質問・要望","question":"これはもう動き出しているので、設計的には変更は大変難しいと思いますので、今までグループホームはそういう形だったというのと、今の認識は変わっていますので、その前のずっと前につくったグループホームがそうだから、今、それでよしということではないということを十分に理解していただいて、これからグループホームが足りているとは到底思えませんし。","respondent":"中山障害者福祉課長","answer":"区内に実はもう一つ、通過型の精神のグループホームがあります。そちらは通過型ということで、２年間そこで生活する中で地域の一般のアパートを借りるということになっておりますので、そこの居室については、ミニキッチンとかを設置しているんですね。","id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問・要望","question":"いただいている説明資料の今の設計図がついているところの表紙のところに、知的障害者のグループホームのところの書き出しで、来年度、法改正に対応するためのケアホームに準じた整備と書いてあるんですけれども、この辺の意味を教えていただきたいのと、あと、今、指定管理者を公募しているんだと思うんですけれども、２階に児童のほうの思春期サポートが入りますよね。","respondent":"中山障害者福祉課長","answer":"実際には、思春期サポートに通われている方の中から就労ということで、今、予定しているのが、パソコンを活用した就労を考えているところではありますが、そういったものに向いているというお子さんがいらっしゃったときに。","id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問・要望","question":"１点目のほうはわかりました。そこはぜひ区が主体的に調整していただきたいなと、これは要望させていただきたいと思います。それから、ちょっと基本的なところの質問なんですけれども、この第６４号議案の中で、第９条以降に、この施設をいわゆる指定管理にしますよという条例なんですよね。そこをまず確認なんですが。","respondent":"中山障害者福祉課長","answer":"委員ご指摘のとおりです。","id":"exchange-006"},{"speaker":"たけうち委員","kind":"質問","question":"そうしますと、たまたま今、ホームページに既に指定管理者の公募が出ているんですよ。そうすると、それに先んじて、今、公募してしまって手続的にいいのかなと私はちょっと疑問に思うんだけれども、どうしてもそうせざるを得ないスピード的なものがあるのだったら、それは事前にご説明いただいたほうがいいんじゃないかなと思うんだけれども、どうなんですか。","respondent":"中山障害者福祉課長","answer":"ただ、おっしゃることは本当にもちろんですので、今後もう少しスケジュール管理のほうを十分にして、例えば、本来であれば第２回定例会できちんと議案を上げてご承認していただいた後、適正な公募のスケジュールということで今後は注意していきたいと考えています。","id":"exchange-007"},{"speaker":"たけうち委員","kind":"質問","question":"ぜひ丁寧に、その辺がちょっと、私もホームページを見ていて、今日ここで議案で指定管理するのかどうかと決めるのに、既に指定管理を公募しているということは、やっぱりうがった見方をしてしまうと、ちょっとどうなんだろう、議会が軽視されているのかなと思いかねないので、そこはもう、例えばスケジュールで事前に丁寧に説明していただいておけばいいのかなと思いましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"渡部委員","kind":"確認","question":"それの確認が一つと、あともう一つが、やはり今回の条例の中で、指定管理者は、次に掲げる業務を行うものとするでは、当然、維持修繕、それはそうだと思うんですが、例えば、この先、その施設の修繕等を行っていくのにも、これは区が主体になるのではなくて、あくまでも弘済会のほうで当然設計も施工もなさるわけですから、つき合いをこれから２０年つなげていかなければならないものなのか。","respondent":"中山障害者福祉課長","answer":"今回は閑静な住宅街にあるということで、例えば、就労継続支援につきましても、工場みたいなものはちょっと建ちにくいということで、パソコンを活用したような室内でやれるような作業ということで、こういったスペースが必要なのではないかということと。","id":"exchange-009"},{"speaker":"渡部委員","kind":"確認","question":"もう１回確認です。区の考えは、しっかり入っているというふうな認識でいいですねというのが１点と、先ほど現地でもご説明がありまして、昭和３０年代の建物だったでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"渡部委員","kind":"確認","question":"建って３０年ですね。ごめんなさい。これから２０年間をこの形でやっていく中で、まだ２０年後のことなんですが、例えば、建物全体の寿命等も考えたときに、あらあら今回これはイメージとして２０年なんだというので私たちもいいのでしょうか。確認です。","respondent":"中山障害者福祉課長","answer":"３０年たった建物ということで、残りの２０年というところで、区のほうでは借りて事業を行う予定です。まだ２０年後のその先というところまでは、実際のところ、鉄道弘済会とそこまでの話はできていないのが現状です。","id":"exchange-011"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほどの２階の直営でやる発達障害の相談のところ、パルレが今までやっていた事業のところで、ここにはパルレを想定しているということはもう既に明らかなことだと、思春期の北品川つばさを移行ということなので、そこの施設について、そういったことの経験者であるパルレの意向がどこに反映されているのか、あったら教えていただきたいということと、もう一つは。","respondent":"中山障害者福祉課長","answer":"発達障害の方の就労継続支援というところで、パソコンについてのニーズ調査をやられたのだろうかというお尋ねですが、実際に今、パルレで思春期サポートの中でパソコンクラブですとか、そういったこともやっております。","id":"exchange-012"},{"speaker":"井上委員","kind":"質問","question":"第６４号議案のほうの第４条で、事業の内容で、第４条第２項で発達障害者に係る相談ということで、パルレのところは発達障害児も含むだろうというふうに思うんですが、ここの部分で、これは発達障害者に係るというのは、幾つを想定していますでしょうか。","respondent":"中山障害者福祉課長","answer":"ですから、具体的に年齢で言うと、思春期というのは人によってちょっと違うんですが、早い方であれば１２歳ぐらいから、そこから成人期ということで、長ければ４０代ぐらいまでというふうに考えていただければと思います。","id":"exchange-013"},{"speaker":"井上委員","kind":"質問","question":"そこで安心しました。それとあと、就労継続Ａなんですけれども、品川区に就労継続Ａは、これで幾つになって、どこがあるのでしょうか。","respondent":"中山障害者福祉課長","answer":"ただ、就労継続Ａ型というのは、すごく難しく、要するに、雇用型なので、それだけの仕事を確保しないといけないんですね。なので、２３区の中でもＡ型の事業所をやっているところはすごく少ないというふうに認識しています。","id":"exchange-014"},{"speaker":"井上委員","kind":"質問","question":"ここでは、説明によると、発達障害就労継続Ａ型事業も行うということで、それはどういうイメージでされて、就労継続Ａ型事業という私の認識だったら、一般とか就労できる人たち向けの訓練みたいなものをＡ型というふうに思っていたので、福祉工場みたいなものをここにつくるという今の感じですか。","respondent":"中山障害者福祉課長","answer":"区内には就労継続Ｂ型の施設がたくさんありますし、Ａ型は、今、お話ししました福祉工場しながわだけなんですけれども、何が違うかというと、その雇用型なのか非雇用型なのかというところになります。","id":"exchange-015"},{"speaker":"井上委員","kind":"質問・要望","question":"できればそういうふうにしていただきたいということも思うんですが、そこで就労継続で指定管理者の中に、そこのところは仕様書として、それをしてくださいということを盛り込むということですか。","respondent":"中山障害者福祉課長","answer":"その中には、事業の具体的なイメージだけではなくて、実際にそれが仕事として、Ａ型というのはそこが一番大変なんですけれども、最低賃金を保証するだけの、要するに、仕事をとってこられるかどうか。","id":"exchange-016"},{"speaker":"井上委員","kind":"確認","question":"最後に、この鉄道弘済会のケアセンターの区が参入する事業としては、新規の事業だというふうに捉えるのだろうなというふうに思うんですけれども、弘済会がやっていた事業と同じようなことを区もやるんですよということではなくて、明らかにこの地に区が事業をしていくというときに、新規の事業として、地域の方たちにどのようなアプローチ、説明をされてきたのか、同じような事業なので。","respondent":"中山障害者福祉課長","answer":"９月に入りましてから、工事説明会をしますということで、９月４日に、一度、近隣の方も含めてお集まりいただきましたところ、やっぱり事業に対する中身をもう少しよく知りたいというご不安な声もいただきましたので、その後、２回。","id":"exchange-017"},{"speaker":"井上委員","kind":"質問・要望","question":"鉄道弘済会が長きにわたってここでいろいろな努力をされて、住民の皆さんと関係をつくってきたというところをこれから区が入っていくわけですので、もう区は新規というふうな視点に立って、ぜひいろいろな方たちとコミュニケーションをとっていくということを、ぜひこれからも続けていただきたいというふうに思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"それが移行してくるということですけれども、そして、先ほども就労のほうでは２カ所目だということなんですけれども、この相談、成人期になればやっぱり就労のほうが大変になってくるのかなと思うんですけれども、小さい保育園や学齢期は、学校の中でどうしていくのか。","respondent":"中山障害者福祉課長","answer":"それで、Ａとしては２カ所目の事業所になるんですが、発達障害の方に特化した就労継続施設というのは今回が初めてになります。","id":"exchange-019"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"発達障害者の支援、本当にすごく待たれて期待もされているというところでは、今回のこの施設、本当に待ちわびていたという声も聞かれるんですけれども、先ほども指定管理のところで丁寧にということもありましたけれども、私もこのプロポーザル方式実施要領を見させていただいて、募集資格のところで、現在、障害者総合支援法に基づく障害福祉サービスの指定を受け事業を実施していること。","respondent":"中山障害者福祉課長","answer":"株式会社を決して否定をしているところではないんですが、この事業実績のところで、障害者福祉サービスの指定を受けてグループホームの事業をやっていることであるとか、あるいは、就労継続の事業をやっていること。","id":"exchange-020"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"実際は社会福祉法人になってくるということですけれども、１０月１日からですよね、手を挙げていく、募集をされていくというところで。それで選定していく中で、これは株式会社でもなかなかいいところがあったぞということになれば、そういう方向に株式会社もありだと、社会福祉法人でやっていくという担保があるのかどうかをお聞かせいただきたい。","respondent":"中山障害者福祉課長","answer":"ただ、事業の選定の中では、実際に事業をやった経験があるだけではなく、経験があれば、そこの中身とかもチェックしますので、しっかりと安心して区立施設を任せられる、そういったところに事業のほうを委託していきたいというふうに考えているところです。","id":"exchange-021"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"共産党としては、本当に必要な施設だと、待たれている施設だというところでは本当に設置には歓迎するものなんですけれども、私たちも求めてきたことですけれども、建てても、施設ができても、やっぱり運営が一番要になってくると思うんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-02","title":"の第５９号議案、平成２５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"の第５９号議案、平成２５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"井上委員","kind":"質問","question":"高齢福祉のところで、このケアの充実追加分というのは、完全に新規事業としてスタートするものかということと、スタッフの選考は、これからどうするか。なぜこれができたのかという、その理由をお願いします。一つ、一緒に言ってしまいます。上大崎の債務負担行為で１,９００万円余というのは、基本設計全部を言っているのか、それとも一部が債務負担行為となっているのか、その辺をお願いします。","respondent":"永尾高齢者福祉課長、中山障害者福祉課長","answer":"開始ですけれども、９月をめどに準備を進めているところですが、まだ準備の段階でございまして、できるだけ早くに、予定としては９月だったんですけれども、医師会との調整が、今、内々には終わってはいるんですけれども。それに伴い、品川区のほうも東京都の事業を活用する形で実施するものです。","id":"exchange-023"},{"speaker":"井上委員","kind":"質問","question":"最初の認知症のところ、区のほうのスタッフの総勢が何人かということと、交代でと言われて、荏原医師会のほうは３名の方が交代でというふうなお話だったので、それはアウトリーチで何班かグループができて回っていくという仕組みなのか、その辺は完全に固まっているものなのか教えてください。","respondent":"永尾高齢者福祉課長","answer":"それで、荏原病院につきましては、専門の精神科医の方がチームリーダーというふうに決まっておりまして、そのもとにチームのメンバーを、精神科医の方１０名のうち６名、また、精神内科医の９名のうち５名、そのほか看護師１名、臨床心理士等で構成しておりますけれども。","id":"exchange-024"},{"speaker":"井上委員","kind":"質問","question":"具体的に、支援センターと、訪問看護のほうの推薦をいただくといったそのメンバーが何人になるのかということと、あと、このアウトリーチをするときに、どういった方に対して、だれがそこに行ってくださいという仕組み、地域包括支援センターに情報が行って回ろうとするのか、訪問する人たちはどういうふうな経緯で行くのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"在宅支援センターの方につきましては、まだ検討が十分なところではないんですけれども、現在のところ、その地区の担当のケアマネに行っていただくことがいいかと考えております。","id":"exchange-025"},{"speaker":"渡部委員","kind":"質問","question":"二つお伺いしたいと思います。でないとわからないですよね。保護者とかが気づくべきものなのか、本人たちが知るものなのか。それか、当初計画どおりに何か進んでいないようなところがあって、その基本計画が遅れますということで５０％減額しているのか、ちょっとその辺の理由といいましょうか、なぜなのかという、その２点をお伺いできますでしょうか。","respondent":"中山障害者福祉課長、永尾高齢者福祉課長","answer":"どのぐらいの方が該当になるかということなんですが、この事業を今回東京都が始める前から区の単費でやっていたのは、大田区のほうで実施していました。大田区で年間で１件あるかないかということで聞いております。それを考えますと、今年度中に基本設計まで終わらせるというのは難しいということで、もう一度スケジュールを組み直しまして、今回の補正に至ったというような内容です。","id":"exchange-026"},{"speaker":"渡部委員","kind":"質問","question":"もう１件、特養ホームのほうは、７月１日の厚生委員会資料のスケジュールをいただいていますよね。このとおり行っているということなんですか。このとおり行っていて、この時点でもう間に合わないやというのがわかっていて、今回、補正が上がってきたということなんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"７月の時点でスケジュールの変更が必要だということで、７月に報告した内容が変更後のスケジュールというふうになっております。","id":"exchange-027"},{"speaker":"渡部委員","kind":"確認","question":"わかりました。では、これに基づいて動いていてということであれば、ちょっとその確認だったので、申しわけございません。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問・要望","question":"認知症高齢者の支援とケアなんですけれども、早期発見と推進事業というところで、明日の資料を見ていたら、そこの事業のところで、都の事業で平成２５年度もモデル実施をされているようなんですけれども、非常にいい、すばらしい内容だと思うんですが、このアウトリーチチームが家庭訪問を行ったと、適切な医療とサービスにつながる支援を行うということで。","respondent":"永尾高齢者福祉課長","answer":"今年度については、まだアウトリーチチームはこれから動くということですので、実績というのは特にはございません。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"確認","question":"失礼しました。今までもこの荏原病院ではなくて、お医者さんにお願いをして訪問をしていただいたとか、そういったことはあるのかと思うんですけれども、そういった今この内容を見ると、それが都のほうの規定で都立荏原病院になったのかなという感じなんですが、今までもそういったことはされていたのかどうか、そこの確認をさせてください。","respondent":"永尾高齢者福祉課長","answer":"区では個別のケースの中で在宅支援センターのケアマネジャーがつなげるということはありましたけれども、こういう仕組みとしてつなげるというのは、今回が初めてです。","id":"exchange-030"},{"speaker":"たけうち委員","kind":"確認","question":"この中等度難聴児の発達支援のところで、基本的には都の枠組みが全部そのまま来ているということなので、一応確認ですけれども、都のホームページだと、基準額、補聴器１台当たり１３万７,０００円という基準があって、それと実際に補聴器を購入した費用との少ないほうの額の１０分の９と、こういう全く同じ考え方でいいのかどうかということと、あともう一つは、先ほど渡部委員もおっしゃいましたけれども。","respondent":"永尾高齢者福祉課長、中山障害者福祉課長","answer":"こちらの事業につきましては、両医師会との調整を必要としておりまして、その調整の時間と、このプレス発表の期間が間に合わなかったということで載っていないということです。都の制度を活用するというところですので、最大ですと、耳穴型が１３万７,０００円ということになりますので、それが必要だよということで医師の診断が出れば、最高額はその金額になります。","id":"exchange-031"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"認知症のケアのところで、先ほども似ているようなことをやっていただいていて、つなげる仕組みが初めてだというところなんですけれども、もうちょっと何がどう違うのかを具体的に教えていただきたいです。それと、生活保護のシステム改修のところで、８月１日から引き下げが実施されていますけれども、このシステムはもう改修されて実施はされているということなんでしょうか。","respondent":"永尾高齢者福祉課長、竹田生活福祉課長","answer":"ですけれども、今度はそれだけではなくて、在宅介護支援センターのケアマネジャーだけではなくて、かかりつけ医からの情報や、そのほかの地域の情報なんかもきちんと取り入れて。基準改定の件ですが、８月１日の基準改定に向けまして、既に実施済みのものです。本来は６月に補正予算を組みたかったところですが、東京都より正式な通知が間に合わなかったものですから、今回の補正とさせていただいたものです。","id":"exchange-032"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"認知症のところはわかりました。それで、生活保護のところで、１０％を引き下げていくという計画で、それを３年かけて軽減措置がとられているというところなんですけれども、そうすると、来年またそのためのシステム、もし引き下げられるのであれば、そのためのシステム改修、再来年になれば、またシステム改修というふうに、そこに予算がまたついていくということなんでしょうか。","respondent":"竹田生活福祉課長","answer":"国および東京都から今回のシステム改修につきましては、来年、再来年にシステム改修が極力必要がないように改修することということで指導されておりますので、来年、再来年を見越して、極力改修が必要のないような形でしたところです。","id":"exchange-033"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"でも、１０％ともう掲げられている中で、それが、要は、その目標を達成していくために３カ年かけていくということなんじゃないでしょうか。なのに、それが来年はどうかわからないというのは、１０％引き下げありきの今回そういう計画なのではないんですか。","respondent":"竹田生活福祉課長","answer":"今回の改定につきましては、厚生労働大臣から告示事項ということで、今年度については確定という内容で示されたものです。来年度以降につきましては、これはあくまでも計画の段階でございまして、実際に計画どおり実施されるかというのは未定です。","id":"exchange-034"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"それで、補聴器の助成のところで、今、相談者は１人ということなんですけれども、もしこれが５人分を超えた場合というのはどうしていくのかなというのと、あと、今年度だけの予算なのかどうかということをお聞かせください。","respondent":"中山障害者福祉課長","answer":"予算上は５人ということにしておりますが、結果、たくさんのご相談がきて、この事業に該当する方がいらっしゃれば、枠の中で対応していきたいというふうに思っております。","id":"exchange-035"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"共産党は、生活保護の引き下げによるシステム改修ということで、その引き下げそのものをすべきでないというところでずっと反対をしてきたものです。ですので、やっぱり人間の命を守っていく、生活を守っていくというところで大変重要なものになっていく、そのためのシステム改修ということですので、賛成できないということで反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"}]},{"id":"topic-03","title":"の３、報告事項、平成２４年度指定管理者の管理に対するモニタリング・評価の結果","agenda":"の３、報告事項、平成２４年度指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"４点質問させていただきたいんですが、二つずつまとめて質問します。最初に、７ページの管理運営委託料と利用料金なんですが、先ほどのご説明で、平成２４年が上下逆だったというお話を聞いたんですけれども、そうすると、平成２４年の委託料が非常に多いような気がするんですが、これはこれでよろしいのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"利用料金については、平成２３年度が２億３,５５７万１１３円、平成２４年度が３億３,８７６万９,５１４円ということで、こちらは稼働率が上がったということでの利用料金の増額ということになっております。","id":"exchange-037"},{"speaker":"鈴木（博）委員","kind":"質問","question":"１２ページの荏原在宅サービスセンターなんですけれども、感染症の最新情報に合わせ「感染症マニュアル」の見直しを行ったと書いてあるんですが、これは結局、何らかの感染症が発生して、それに対する対策としてこういうことをやったということなんでしょうか。具体的にこの辺が、こちらの自己申告だと思うので、ちょっとよくわからなかったのでお聞きしたいんです。","respondent":"永尾高齢者福祉課長","answer":"具体的というよりは、高齢者のサービスセンターの中で、インフルエンザ、ノロウイルス等の感染症というのが多く発生しがちだというところで、事業者みずからがマニュアルの見直しを行ったというふうに聞いております。","id":"exchange-038"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これは特養のところを見ると、地域との交流でなかのぶ会云々と書いてあるんですが、こっちのほうのサービスセンターのほうでは、そういうことは一切書いていないんですが、同じところでやっていて同じ地域なのに、例えばそういうことを利用するとかということも方法としてあるので、いかがなんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"この地域懇談会のなかのぶ会というのは、地域の中で同じ住民として居住するという意味もあって、なかのぶ会の中での懇談会を行っているところですけれども、デイサービスにつきましても、このなかのぶ会等を活用して。","id":"exchange-039"},{"speaker":"井上委員","kind":"質問","question":"最初のほうのところに、改善が必要とされた原因の分析及び対応方針という中で、幾つか短期間での長期入院や死亡するケースが増加しているということを挙げているんですが、これは施設との関係でという表記なのか、何かここにこういうふうに載っているのは、どういう意味で載せているのかということが１点と、３ページも今のことがあるんですけれども、３ページで、改善が必要とされた原因のところで。","respondent":"永尾高齢者福祉課長","answer":"その見学だとか説明とかをしている間に日程的に空白ができてしまって、それが稼働率の上がらない原因になっているというところが施設側としては課題になっているということです。","id":"exchange-040"},{"speaker":"井上委員","kind":"質問","question":"今の説明で、長期入院や死亡というそういったものは、施設との何らかのケアの体制をもう少し違う形にしていけば改善をされるというものであるのかどうかというところも、きちんと検証しないと、この表記では分析に値しないのかなというふうに思うことと、もう一つ、入所できないというところで言えば、じゃあ、認定の方法が本当に適切なんですかと、認定をしました、いやいや、自宅でもう少し見ますと。","respondent":"永尾高齢者福祉課長","answer":"それでまた、亡くなられた後にすぐに入所できないというお話になるんですけれども、やはりご家族の方も特養に入所ということに対して、自分のご家族の気持ちの中で後ろめたさというか、そういうものもあったりということで、葛藤があるように見受けられます。","id":"exchange-041"},{"speaker":"井上委員","kind":"確認","question":"次、管理運営委託料と利用料金方式を特養ではとっているのか、ちょっと基本的なところで確認なんですが、そこはこの今報告をされた中で利用料金制をとっているのは、健康センターだけなんでしょうか。ちょっとそこを説明をお願いします。","respondent":"永尾高齢者福祉課長","answer":"利用料金のところは、自己負担の部分と、あと介護報酬の部分と、合計した金額が入っています。そのほか、ここに書いてあるとおり、食費とか居住費等のご本人の負担というのもこの中に入っているということです。","id":"exchange-042"},{"speaker":"井上委員","kind":"意見","question":"管理運営委託料の算定というのは、各施設それぞれなのか、どういう根拠があるのかということと、もう一つ、表記の中で、「委託事業者」とか、「再委託事業者」というのがありましたけれども、具体的には、多分、特養とかそういった部分で多かったんですが、そちらのどういったところに委託事業とか再委託をされているのか、具体的にお知らせください。","respondent":"永尾高齢者福祉課長","answer":"管理運営委託ですけれども、本日ご説明してある施設は全部区立の施設になりまして、区立の施設としての維持管理の部分の金額を委託料として事業者にお渡ししている内容です。","id":"exchange-043"},{"speaker":"井上委員","kind":"質問","question":"維持管理費の管理委託とすれば、規模は同じなんだから、そんなに毎年この管理委託料が変わるということについては、何か今、説明がちょっと違うのかなと思ったんですけれども、そこについてはどういう状況なんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"この管理委託料は毎年毎年算定をするんですけれども、経常的に発生するものと、例えば、大規模なのは区が直接なんですけれども、ちょっとした修繕だとか、改修とかの部分は、指定管理者にお願いしていますので、その部分で出っ込み引っ込みが出てくるです。","id":"exchange-044"},{"speaker":"井上委員","kind":"質問","question":"稼働率に対して変化があるという認識ではなくていいんですねということが１点と、次に、高齢者住宅なんですけれども、ワーデンのところが出てきたと思うんですが、ワーデンを福祉工場に委託するというような、どこでしたでしょうか……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"３６ページの４番、わかくさ荘のところで、「ワーデン業務は引き続き福祉工場しながわに業務委託し」というのは、就労継続Ａ事業の福祉工場に業務委託をするというのがよくわからないんですけれども、これについてはどういうことでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"ワーデン業務をこの福祉工場しながわに業務委託という、こちらのほうについては、従来からこちらのほうにお願いをして行っているというふうに聞いておりますけれども、今の委員の質問は業務委託になじまないというお尋ねなんでしょうか。","id":"exchange-046"},{"speaker":"井上委員","kind":"質問","question":"ワーデン業務は、ここでは何を言ってるのでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"このワーデン業務につきましては、これまでの管理人業務委託ということで、全てこの指定管理の中で法人のほうにお願いをしているところでありますけれども、ただ、夜間の時間帯が、午後７時以降ということになるんですけれども、こちらについて。","id":"exchange-047"},{"speaker":"井上委員","kind":"質問","question":"福祉工場しながわの人たちが就労支援Ａ型で、その方たちが、ワーデン業務は世話人業務なので、ここに合うというのは適切ではないと私は思っているので、多分表記の仕方が違うのかなというふうに思っているし、サポしながわの３名雇用、これは研修が未実施だったということなので、今、ワーデン業務は、対応してもらおうと思っても、ワーデンがなかなか会えなくて死亡していたという事件が今回明るみに出て。","respondent":"白鳥高齢者いきがい課長","answer":"あるいは、やはりもう少し危機管理、こういった意識も持ちながら、もちろん今までも継続して法人のほうにお願いをしているところではありますけれども、その辺は十分これからもきちんとした体制を築いてまいりたいというふうに思っております。","id":"exchange-048"},{"speaker":"井上委員","kind":"質問","question":"それから５１ページなんですけれども、児童学園のところで、改善を必要とされるというところで、施設の老朽化による経年劣化があって、園庭にある遊具を毎日点検というのは、そもそもこれはもう問題なんじゃないですかと、変えるか、何らかの対策を区が考えないと、点検をして何か事故がありましたという話ではないので、老朽化でなぜこのまま放っておくのかなということについてのご答弁をお願いしたいのと。","respondent":"中山障害者福祉課長","answer":"ただ、職員配置自体は、しっかりとした人数を確保しておりますし、また研修等も充実させていきながら、児童の発達支援のほうをしっかりと対応できるような体制を今整えているところです。","id":"exchange-049"},{"speaker":"井上委員","kind":"質問","question":"基準より多いということだったんですけれども、基準が何名で、平成２４年度に何人いて、平成２４年度に退職された方が何人いて、その分が平成２５年度に採用されたのか、そこの具体的なところはどうなっているのでしょうか。","respondent":"中山障害者福祉課長","answer":"改めてご報告させていただければと思います。ただ、昨年度末にかけて退職された方のところは、当然補充はされておりますので、平成２４年度と平成２５年度を比較したときに、直接処遇する職員の数が少なくなっているということはございません。","id":"exchange-050"},{"speaker":"井上委員","kind":"質問","question":"なかったとしても、行ったときにそういうことを感じたので、何らかの対策が必要と思うんですが、いかがでしょうか。","respondent":"江部健康課長","answer":"苦情があるかというと、ありません。ただ、この問題は確かに私も行ってみてそうだなという気もしますので、今、エスフォルタのほうに検討を指示をしております。その結果はまだ把握しておりません。","id":"exchange-051"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"ショートステイなんかも高齢化、重度化が進んでいて、それを緊急的に受け入れていくというところでは、どんな患者が来るのかわからないで、だけど、そういう方をどれくらい受け入れて、職員の皆さんの心のハード面というか、何が起きるかわからないというところでは、大変なんじゃないかなという、そういうところの声なんかはないものなのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"全て受け入れるということではなくて、可能な方についての受け入れを行っているところです。","id":"exchange-052"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"介護士の処遇改善交付金がなくなってからの実態というのは、各施設、さらなる処遇改善の必要性なんか、現場から声は出ていないのか。そして離職率、今、ほかのページにも書いてありましたけれども、職員がかわらないで安定して接しているので利用者も安心しているみたいなところもあったので、やっぱり離職率が３年以内にどれぐらい割合があるのかというのをちょっと教えていただきたいんです。","respondent":"永尾高齢者福祉課長、早津健康福祉事業部長","answer":"ショートでご利用になられる方ということですけれども、ショートの場合だと、ふだん見ているわけでは、見ている方もいらっしゃるとは思うんですけれども、継続的に見ている方ではない場合もありますので。処遇改善交付金は確かになくなったわけですが、それがなくなるときに、介護報酬自体が人件費分加算されておりますので、全体としてバランスは保たれているです。","id":"exchange-053"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"３ページと５ページの改善が必要とされた原因の分析及び対応方針の１個目の丸のところが、違う社会福祉法人なのに文章が全く同じなんですね。こういったマニュアルがもうあるのかなという。もしくは、こういった傾向だよというのがあるのかなというの、ちょっと素朴な疑問です。","respondent":"永尾高齢者福祉課長","answer":"ですので、文言的に同じということもあるんですけれども、特にこの部分の高齢化や重度化、要医療状態になるというのは、特養の中では共通するような課題になっているので、同じような表記になっております。","id":"exchange-054"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"そうなんですね、ごめんなさい。こういった高齢化、重度化がいろいろ進んでいる中で、体制のプラスなんかは考えられているのかどうかをお聞かせください。","respondent":"永尾高齢者福祉課長","answer":"介護度改善事業のほうは、平成２５年度に開始をしたところですので、この平成２４年度の中にはまだ反映はされておりません。","id":"exchange-055"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"はい、わかりました。それであとちょっと、障害者のところでの就労、４５ページの西大井福祉園のところで、就労Ｂ型事業の利用率というのは、ここに出ている利用率は入所支援の施設入所の利用率なんですけれども、Ｂ型の利用率というのがどこかに出ているのか教えてください。","respondent":"中山障害者福祉課長","answer":"済みません、この１０２％というのが生活介護事業のほうの利用率になっておりまして、就労継続支援Ｂ型のほうは載っていないんですが、こちらのほうも西大井福祉園のほうは１００％を超えているような状況です。","id":"exchange-056"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"指定管理者が更新されるということで、この間も視察させていただきましたけれども、前回、今回のエスフォルタに変わったときに、すごく利用者から、何か利用しづらいものに変わってしまったということで苦情が殺到して、課長なんかも対応をすごくしたということを聞いているんですけれども、今回、更新するので継続なのか変わってしまうのかわからないですけれども。","respondent":"江部健康課長","answer":"ただし、８月に公募いたしまして８月末で締め切りましたところ、説明会のほうは３社ほどいらっしゃいましたけれども、結局、現在は１社が応募されまして、そのプロポーザルは先日終わって、今、決定手続をとっている段階に入っておりますということをご報告いたします。","id":"exchange-057"},{"speaker":"井上委員","kind":"質問","question":"先ほど来、通所デイ、基本デイの部分で、稼働率の向上を図るということがありましたけれども、先ほど、近くに民間のデイサービスもありますよといったときに、そもそも介護認定を受けて、介護報酬でこれを利用しようとしたときに、今、供給過多になっている現状があるのか、利用したいと思う希望のところが１００％ということではないというようなこの数字を見ると、その辺。","respondent":"永尾高齢者福祉課長","answer":"ですので、事業者としては、行きたくないというふうに思わせないようなプログラムの工夫というのは必要なのかというふうに考えているところです。","id":"exchange-058"},{"speaker":"井上委員","kind":"意見","question":"だとすると、来年度からこの総括シートの中に、登録率が何％なのかということを載せていただければ、私たちもこのモニタリングを見て、どういうところに課題があるのかということがわかると思いますので、その評価シートの工夫をちょっと検討いただければなというふうに思います。","respondent":"永尾高齢者福祉課長","answer":"登録率について平均をどういうふうに出すかとか、そういう課題もありますので、事業者全部含めて検討してまいります。","id":"exchange-059"},{"speaker":"渡部委員","kind":"質問","question":"１点だけ済みません。全体的なところでなんですけれども、モニタリングをされて、さまざまな課題というものが浮かび上がってきますよね。これに関しては、当然このシートが先方に行くということはないんだと思うんですが、しっかりと改善をしていただいて、その改善の報告とかが区に上がってくる仕組みになっているのかどうかだけ教えてください。","respondent":"永尾高齢者福祉課長","answer":"この指定管理者のモニタリングの制度ですけれども、ＰＤＣＡサイクルといいまして、Plan・Do・Check・Actionという、このサイクルに乗せて、より質の高いサービスを目指すということを目的としてやっておりますので、今回のモニタリングを受けて。","id":"exchange-060"},{"speaker":"渡部委員","kind":"質問・要望","question":"今日見せていただいたこの福祉の施設の関係とかというのは、やはり私たちから見ても、箱がどうだとか、設備がどうだというよりも、対人だと思うんですね。そのような中で、やはり服薬のミスを招いている。まして当然これは区の施設なわけですから、しっかりと次年度そういうことがないような仕組みづくりのほうを逆に強くつくっていただければと要望して終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"}]},{"id":"topic-04","title":"の４、その他","agenda":"の４、その他","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"それで、それが一覧になっているとありがたいなと思うんです。表になってこの事業に、就学援助とか、非課税のとか、それを人数がパッと見てわかるようになったらありがたいのですが、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/588633?Template=document&Id=3366#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":57392,"voices":173}},{"id":"h25-20130924-8","meetingId":"h25-cm09","date":"2013年9月24日","dateIso":"2013-09-24","committee":"建設委員会","time":"午前１０時００分～午後 ４時２４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を122件抜き出しています。","topics":[{"id":"topic-01","title":"第６５号議案、専決処分の承認を求めること","agenda":"第６５号議案、専決処分の承認を求めること","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"最初に基本的なことをお聞きしたいと思います。滞納の理由を知りたいので、まずこの被告の年齢、家族構成、仕事の有無等、この間生活の変化があったのか、収入の変化などがあったのかどうか、その辺の基本的なことをまず教えてください。","respondent":"大串住宅担当課長","answer":"３点ほどご質問をいただきました。理由につきましては、残念ながらこの方と接触がとれておりませんので、滞納の詳しい理由につきましては把握してございません。それから年齢、家族構成といったご質問です。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"そうなんです。ちょっとその辺も、収入というのはそういった意味でお伺いしたんですが、教えてください。","respondent":"大串住宅担当課長","answer":"平成２３年ごろから滞納がかさむようになってまいりまして、こちらといたしましてもご本人と連絡をとりたいということで、先ほども申し上げましたが訪問や電話、手紙、こういったもので接触を図ろうとしたんですけれども、残念ながらこの方から我々のほうに。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"意見","question":"連絡をしても、手紙を送っても、訪問しても接触がなかったということなんですけれども、もう一回、聞き漏らしたのかもしれないんですけれども、時々は納めていたということですよね。ずっとではないですよね。そういった意味で、指定管理者がこの被告に対してどう接していたのか、また区はその上でどう接触をしていたのか、その辺をもう少し具体的に、判断材料が欲しいのでお知らせください。","respondent":"大串住宅担当課長","answer":"今回の訴訟の目的になっております滞納の金額ですが、１６１万６,９００円ということで１１カ月分の滞納額になっております。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"平成２４年６月から滞納が始まったということでは、何らかこの時期に起こったであろうなと普通は考えますよね。税金とか介護保険料、その他の部分での滞納とかは把握していらっしゃるんでしょうか。","respondent":"大串住宅担当課長","answer":"こういった滞納を重ねる方につきましては、先ほど申し上げましたように一義的には指定管理のほうで対応していただいておりますし、あわせてこちらのほうでも、言葉はあれですけれど、住宅担当のほうに来ていただいて事情をお聞きする、あるいはまた督促の指導を行う。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"提案","question":"平成２４年のこの時期から困難が出てきたというのは、それなりに理由があるのではないかということを推しはかっていくことも大事なのではないかと思うので、その辺の努力、どうしたらいいか提案はできないですが、努力は大事であると思うんですが、最後になりますけれどいかがでしょうか。","respondent":"大串住宅担当課長","answer":"ここまでに至る、訴訟に至る方の場合、大多数の方につきましては、今、るるご説明していますけれども、こちらがいくらアプローチをかけても何も返答が出てこない。逆にいうとアプローチをかけて何らかの返答があった方については、それなりに対応ができるです。","id":"exchange-005"},{"speaker":"西本委員","kind":"確認","question":"確認です。契約時はどうなっているんですか。それと、実際の滞納金が１６１万何がしですよね。それで訴訟の目的の価額は６０２万円と、めちゃくちゃ大きくなるわけですよね。これを多分知っていたら、ここまで来たらこうなってしまうよみたいなことを、皆さん理解されているんですか。そこら辺の、借りるときはどういう状況で、皆さん借りられているのか教えてください。","respondent":"大串住宅担当課長","answer":"連帯保証人の方につきましては、今回の訴訟、提起を踏まえた上で、弁護士のほうからまたご連絡あるいは交渉といったことで進めていく、こういったことになってあります。","id":"exchange-006"},{"speaker":"西本委員","kind":"意見","question":"今までもこういうケースはたくさんあったと思いますが、そのとき最終的にどのぐらいの期間で解決されて、どういうケースで解決に至ったのか、詳しく聞きたいと思います。","respondent":"大串住宅担当課長","answer":"ことしも３件ほどですが強制執行を行いました。強制執行を行うにしましても、これはまた裁判所にお願いをいたしまして、執行官という方に来ていただいて、その執行官の立ち会いのもと、初めてその方の部屋の鍵をあけることができる、こういった流れになってまいります。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"その求めるとき、やはり契約時にこういうときにこうなりますよ、こういうケースになりますからということをはっきりと認識した上で、やっておられると思うんですけれど、具体的にこういう訴訟になった場合にはこうなりますよということを、具体的な例をなるべく知らせて、理解を求めて、あまりこういうことでもめるというのはよくないことだと思いますので、いろいろな手だてを、当人に接触できれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"伊藤委員","kind":"確認","question":"今の話にちょっとつながりますけれど、訴訟は最終的な手段だと私たちも思っています。さまざまな民間業者に委託をしていると思うんですけれど、難しいことを聞くのですけれど、こういう方々に対して日常的なアプローチをして、家賃滞納をしないような努力はどのようにしていらっしゃるのでしょうかという確認をお願いいたします。","respondent":"大串住宅担当課長","answer":"こういったケースは、正直申し上げて少数のレアケースと認識しております。大多数の方は基本的に滞納もなく、使用料を毎月お支払いいただいております。","id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問・要望","question":"実際訴訟にもうなってしまったので、このことについてはどうこうできないけれども、今まさに課長がおっしゃったように、前の段階でいろいろなアプローチをしていただいて、できる限りこういうケースを少なくしていただきますよう、言葉で言うのは簡単だけれども相当現場は大変だと思います、だけれどそれはやはり理解を求めていくところもありますので、よろしくお願いします。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"原委員","kind":"質問","question":"聞きたいのは、この弁護士費用ですけれど、どなたが持っているんでしょうか。指定管理者でしょうか。","respondent":"大串住宅担当課長","answer":"これは法律事務所への委託ということになります。１件の訴訟当たり２６万円、法律事務所のほうには委託料ということでお支払いをして、訴訟事務を進めていただいているところです。区の負担です。","id":"exchange-011"},{"speaker":"原委員","kind":"質問","question":"今、伊藤委員からもありましたけれど、今回の件だけではなくて、もうずっと何年もこういったケースというのは続いて、質問的にももう同じような内容になっているものですから、そうすると指定管理者制度があるので、その辺のところをもう少し検討できないかということと、あと訴訟になってくると全てがオープンに開示されてこないという部分もあるんですね。ですから、今後においてその辺のご意見があれば。","respondent":"大串住宅担当課長","answer":"２点質問いただきました。１点目の指定管理者ですが、なかなか指定管理者にこの滞納のリスクを背負わせるというのは、難しいと考えております。","id":"exchange-012"},{"speaker":"原委員","kind":"質問・要望","question":"まったくわかります。ですからその辺のところまでもう少し、この件ではないです、この件はこれで結構だと私は思っているのですが、先々でそういった動きをやはりしていっていただきたいと。品川区は自治体として非常にいい財政内容を持っているわけですから、なお一層いい形にしていただきたいので、その辺ちょっとご意見をいただければと思います。","respondent":"大串住宅担当課長","answer":"ただ、現状はなかなかこういった形で、公営住宅、こちらは特優賃制度に基づいて行っている住宅制度です。その制度自体の根幹にもかかわってくる問題かと考えておりますので、その辺は今後の検討課題とさせていただきたいと思います。","id":"exchange-013"},{"speaker":"こんの副委員長","kind":"質問","question":"先ほど質問はありませんでしたけれども、それぞれの努力されてきたと先ほどの質疑の中でもありましたし、ある一定のそうした動きの中で、残念ですがやむを得ない処置だったのかなと思います。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"意見","question":"意見をつけて賛成したいと思います。不正は許されないことであります。もしかしたら著しい生活の変化などで、救済が必要な人がいるかもしれないというところにおいては、やはり早い時期に接触をする努力、工夫を重ねてお願いして、賛成します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]},{"id":"topic-02","title":"第５９号議案、平成２５年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第５９号議案、平成２５年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"１７ページの国道１５号線の災害時帰宅者支援でお伺いしたいんですが、これは今、補正で出てくるということで、ここで今、これを可とするか非とするかという議論をするということで、議案として上がってきています。そこのところ、前回は報告ということで文言等々いただいておりますけれども、そこら辺の考え方についてお示しいただきたいと思います。","respondent":"鈴木防災課長","answer":"考え方といたしましては、委員ご指摘のように今回の補正予算案、正式に審議いただいて、承認いただいた時点で事業の正式な着手ができるというふうに認識しております。","id":"exchange-016"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、ここの場ではなくて前回の委員会は審査とは言いがたい、議案として出てきていない、報告事項として出てきているわけですから、一定の方向性、議決を求めるべき話の内容ではなかったんですけれども、その話の中、今においても同種同様な話の内容、言葉をかえれば審査に当たると思うんですけれども、前回の報告にまつわる議論の内容、そして今回の議案にかかってきた部分の議論の内容。","respondent":"鈴木防災課長","answer":"前回８月２６日にご報告をさせていただいた時点では、そのご報告した案についての簡単なご質問とご意見を何点かいただいただけにとどまっておりまして、そのときに審議いただいたことになるかどうかはちょっと私の立場からは判断しかねますが、私、防災課長の認識としては。","id":"exchange-017"},{"speaker":"大沢委員","kind":"質問","question":"参考になる意見というのは、それは言葉の欺瞞であって、議案にはかかってこないけれども少なくとも報告で来ている以上は、こちらも真摯に望みながら、それなりの意見を述べるのであれば、時期は違っても同種同様な議論の内容になるのではないですかというお話をしているんですけれども、違いますか。","respondent":"松代防災まちづくり事業部長","answer":"さかのぼりまして、このそもそもの事業の発端は、先ほど課長からご説明したとおり、時期というものがありますし、先方からの問い合わせ等がありました。","id":"exchange-018"},{"speaker":"大沢委員","kind":"質問","question":"いずれにしても非常に、前回もちょっとお話しさせていただいたけれども、確かに思いとか、我々議会の意志を十分尊重しながら、また防災上の地域あるいは国の方針からということで、外に情報を開示したい、報告したいという思いは、本当に一生懸命されている、真剣に取り組まれているというのは十分理解できるんですけれども、やはり議会というものの、役所もそうでしょうけれども、やはり法律なり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"確認","question":"それで質問は、国道１５号線関係について、これはたしか前もあったと思うんですけれど、確かに品川区はこれをやってください、そのとおりだと思うんですけれど、国道１５号線はご承知のように、品川区だけではないですよね。だから何で品川区だけに来たのか、ここでどういうことを、国交省でしたっけ、品川区に何を望んでどういうことをしていらっしゃるのか、ということの確認をお願いします。","respondent":"鈴木防災課長","answer":"ご質問いただきました国道１５号線にかかわる港区、大田区、神奈川県、それぞれの自治体の動きもしくは役割ですが、もともとの事業の依頼をしました国交省の考え方では、この国道１５号線にこだわることではなく、日本全国。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問","question":"確かにその前後の経過はわかりますけれど、品川区の事情と港区の事情、大田区の事情、神奈川県の事情、多分相当違うと思うんです。沿線の住宅の密集具合であるとか、公共施設の散らばり具合とか。前回の委員会でも言ったような気がするんですけれども、少なくとも港区、大田区、神奈川県は川崎市あたりですか、そのあたりと、やはり共通の課題を持って対処していくべきだと思うんですが、いかがですか。","respondent":"鈴木防災課長","answer":"ただし同じ国道を、例えば品川駅から品川区を通過して大田区というふうに、同じ徒歩帰宅者が通りますので、時間的な経過、またはその情報の共有、次のエリアでの連携というところで、一体となって対策を講じるのが効果的であろうというお話は、大田区。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問","question":"それが今の現状で言えると思いますので、よろしくお願いします。それから、２７ページの百反歩道橋架替関連調査委託ですが、年度間事業計画が変更となり、完了の見込みが翌年度となったためとあるんですが、もう少し具体的なことを教えていただけますか。","respondent":"溝口都市開発課長","answer":"これにつきましては、主にのり面の土抗工事が当初工程よりも遅れておりまして、それに伴い、当初は平成２５年度末で調査が完了することになっておりましたが、平成２６年度にずれ込むということで、その分債務負担を、平成２５年、平成２６年の債務負担に組み直すという補正を。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"確認","question":"たしかこれは百反歩道橋が、あそこを建替えるから随意契約の話になった記憶があるんです。要はＪＲ側もさまざまな影響が出る、延期になったのであれば、税金の使い方としてちょっと疑義が生じる可能性があったので、今ののり面の確認ですけれども、おっしゃっているのは百反歩道橋の旧自動車学校側のほうののり面ですか、どこののり面のことなんですか。","respondent":"溝口都市開発課長","answer":"すみません、説明が不足してしまいまして、申しわけありませんでした。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問","question":"のり面の掘削工事は、あくまで東海旅客鉄道株式会社が計画したんですか。","respondent":"溝口都市開発課長","answer":"今回、本体の百反歩道橋ののり面の掘削ですとかそういった工事をやることで、直近の上位に走っております東海道新幹線の構造物等に影響を及ぼす可能性があるということで、それの計測を、変位測定をするための調査委託というのが、今回の補正の対象になっているものです。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"確認","question":"つまり、ＪＲ東日本がやっている路面の掘削工事が遅れたので、結果として百反歩道橋の調査が延期になったという判断でいいんですね。その確認だけ。","respondent":"溝口都市開発課長","answer":"ご指摘のとおり、従前計画した期間というか工事のスケジュールよりもおくれたことは、ＪＲ東日本が区から委託を受けてやっている工事が遅れたことによって、その影響としてＪＲ東海に委託しています影響調査がおくれたということになっているものですから、ご指摘のとおりです。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから実際的にこの６００万円がどこでどう使われていくのか、そのあたりを具体的に教えていただきたいのと。一つは、帰宅困難者の問題が早くからクローズアップされながら、なかなか進んでいないみたいですけれども、現在は全体的にどの程度、本当にほとんどされていないのか、ここにものすごく期待されているのか、その辺の３・１１以降の流れ的な、この位置づけを教えてほしいのと。","respondent":"鈴木防災課長、松代防災まちづくり事業部長","answer":"それから３・１１のときの実態というお話ですが、それにつきましてもしっかりとした情報なり地域での様子、もしくは取り組みについても確認をする必要がありますので、先ほど申し上げましたコンサルタントの委託業務の中で。１０キロ圏内であれば、ある程度徒歩で帰宅されることに支障はないと見ておりますが、それを超える２０キロ、３０キロとなった場合は、やはり何らかの対応が必要だろうと、国も東京都も考えております。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大森駅前の駐輪場の増設なんですけれども、当日に私もあそこを見せてもらったら、大森駅のところってなかなか大変ですよね、水神公園のところにたくさん駐輪場があるにもかかわらず、結構周りのちょっとした細いところにも放置自転車が置かれていて、先日車椅子を利用されている方が、結局１台出っ張っていて、そこに当たってしまうとダダダッと崩れてしまうような状況の中で。","respondent":"鈴木防災課長、谷口交通安全担当課長","answer":"それと区のほうで３００万円の一般財源、３００万円が都の経費で、合計６００万円が妥当かというお話ですが、コンサルタント、いろいろな事務局の諸経費につきまして、これはしっかりと見積もりを複数からとりまして。選んだ理由ですが、この付近は５月１日に放置禁止区域にかけたところですけれど、ほかに区もいろいろ従前から場所を探していたところですが、この場所しか設定することができないということで、いろいろ協議の中で進めたところです。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"もう一点あるんですけれど、駐輪場のところの３,９００万円の内容、内訳を教えてほしいのと、あと防災のまちづくりのところです、２３ページの２カ所なんですけれども、これ、地図をつけていただきたかったというか、具体的にどこなのかなと。大体わかったんですけれども。滝王子通りはどこだかさっぱりわからなかったので、場所もあわせて、この金額をどういうふうに考えているのか、教えてください。","respondent":"谷口交通安全担当課長、品川木密整備担当課長","answer":"事業予算の３,９００万円の内訳ですが、ラックの設置ですとか工事、あと先ほど申し上げました植栽についてだとか、もろもろ含めましての総額です。防災まちづくりのほうの用地取得の件をご説明いたします。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"今回補正で組まれているんですが、ちょっと仕組みがよくわからないんですが、よく用地の取得のときは土地開発公社を利用したりするんですが、今回補正を組んで直接区がという、そこの仕組みを教えてください。","respondent":"品川木密整備担当課長","answer":"本来ですと当初予算で予算計上して執行するんですが、この用地２カ所に関しましては、今年度急遽取得ができることになりまして、補正予算という形で進めようと考えております。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"歳入と歳出の関係を知りたいんですけれど、歳入の土木使用料で自転車の一時利用というのは、これはどこなんでしょうか。これは先ほどの大森の分を想定した金額なのか、それとも全体的に収入が上がるというふうに補正をかけているのかというのが一点。","respondent":"品川木密整備担当課長、谷口交通安全担当課長","answer":"国に関しては補助金が今年度中に出せるという見込みでありましたので、今回補正予算として上げている状況です。歳入の面で大森駅の関係ですけれど、２月以降に供用開始を考えておりますので、２カ月で１５０万円ぐらいを歳入を見込んでいるところです。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"多分限度額とかタイミングがあろうかと思うんですけれど、そこはうまく使っていただきたいと思っています。それで使用料のことですが、すみません、よく理解できなかったんですが、歳入ということで補正をかけたというのは、この大森のところでの収入を補正ということですか。それともほかのところの使用料が増えるということで、計上されているんですか。それはどちらですか。","respondent":"谷口交通安全担当課長","answer":"大森駅の増設によって歳入が増えるです。","id":"exchange-031"},{"speaker":"大沢委員","kind":"意見","question":"し尿の処理というのはこういう防災のときに重要なかなめになるのに、これが手つかずな状態なわけですよ。東京都でも今、はっきり言って全部処理できないような状況で、しっかりしたガイドラインというか方向性が出づらい問題なんですけれど、ここのところはどういうふうに考えて、協議会設立の中に組み込んで議論を深めて、し尿処理に関しては品川区はどういうふうに。","respondent":"鈴木防災課長","answer":"確かに下水道が被害を受けた場合、トイレは通常使えなくなりますので、区のほうでは都と連携した下水道の耐震化とあわせまして、下水道が使えない場合にも対応できるように、使い捨ての簡易トイレの備蓄も始めておりまして、それから従前の便槽式のマンホールトイレ。","id":"exchange-032"},{"speaker":"大沢委員","kind":"質問","question":"マンホール型はくみ取りですよね、そこの部分の費用と効果、いつ起こるともわからない災害に対して備えるというのは、費用がかかるものなのでどうしろとは言えないんですけれども、そこら辺の部分で対応方、きちっと収集する部分の体制というのは考えられて、できているんですか。","respondent":"鈴木防災課長","answer":"し尿の収集処理に関しましては、ご存じのように現在、区で独自のし尿処理車とか処理施設を持っているわけではございません。なので、先ほど申し上げましたように専門事業者の方と協定を結んで、その方たちの協力で処理をするというのが現在の考え方になっております。","id":"exchange-033"},{"speaker":"伊藤委員","kind":"質問","question":"何でそれを審議する当該の委員会に出せないのか、非常に不思議なんです。もちろん記者の方々に資料提供することは理解できるんですけれども、少なくとも同じぐらいをここにも出して、しかもここで審議するのだから、そういう対応については、担当の課なり部で少し努力をしていただければ対処できると思うんですが、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"百反歩道橋のことでしょうか。","id":"exchange-034"},{"speaker":"伊藤委員","kind":"意見","question":"あまり長くこのことで議論するつもりはないので、でも記者懇談会に出されている資料があって、それを私は目にしています。よろしくお願いします。","respondent":"あべ委員長","answer":"すみません、１点だけ。今のプレス発表と委員会については、この委員会だけの問題ではなくて、議会とプレス発表、あるいは区の広報全体の課題だと考えますので、委員会以外の場で取り上げる機会を見つけたいと思います。","id":"exchange-035"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"１点だけ確認と、要望です。大森の駐輪場の件です。先ほどこの補正予算で内訳をお聞きしました。この大森駅は、既に水神公園のほうに設置されていて、大森駅前住宅というところに設置されると思うんですけれど、水神公園のほうは駐輪場に屋根がついております。こちらはどうなるのかということで、同じ大森駅の前で、片や屋根があり、片やないと。この屋根の考え方をお聞かせください。","respondent":"谷口交通安全担当課長","answer":"新たに増設する場所につきましては、屋根なしの当日利用のみです。なぜ設置をしないのかというと、あそこは舗道上ですので、建物でなく駐輪場ということで設置をします。屋根がついていると、建物という判断になります。","id":"exchange-036"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"屋根というのはほかでもある話ですから、建物とそうでないということで、公園内ではそれが許されるということなのかもしれないですが。できる限り、屋根というのはあったほうがいいという声もたくさんある中で、今後研究していただきながら、屋根ということをひとつ考えていただきたいと。この大森駅は非常に違法駐輪がたくさんありますので、ぜひここは積極的に進めていただくよう、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-03","title":"平成２５年請願第１２号、武蔵小山駅周辺地域の開発計画に関する請願","agenda":"平成２５年請願第１２号、武蔵小山駅周辺地域の開発計画に関する請願","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"民主主義の基本となる求めの内容であると思っていますので、私はこれからの時間、十分な審議をお願いしたいと思って、内容に入ります。説明をする対象者をどう考えているか。なので、ポイントは、事業を進めようとしている側と、周辺でいろいろ地域のまちづくりを考えている人との公平性というんですか、説明の度合い、公平性をどう考えているのか、この２点をまずお伺いしたいと思います。","respondent":"溝口都市開発課長","answer":"対象者につきましては、先ほどの答弁と重なりますが、計画については、しっかりまとまったものについては広報しながわ、または品川区ホームページ、そういったもので見られる形、またはお知らせするような形をとってきておりますし、具体の開発計画につきましても。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私はその開発事業を進めようとしていらっしゃる皆さんに対しての区の情熱と、事が明らかになって、これでは地域の環境が壊されてしまう、自分たちの安心安全なまちがおびやかされるのではないかと疑問を持った方たちに対する、説明をしてほしい、意見に対して答えてほしいということに対しての、この違いが、私はあまりにもあるのではないかと思っているので、その辺。","respondent":"溝口都市開発課長","answer":"ご質問の一般に公開されている説明会ということですが、多分２Ｈの範囲でもそれは限定という話になると思いますので、全くオープンで説明されているというものになりますと、この資料でいいますと裏面の５番、武蔵小山パルム駅前のところの１１月２９日。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"その２Ｈの高さのところも、実際には１事業に対して１回ですよね。だからそういった意味では中身をよくわかるように説明してほしい、説明会を開いてほしい。意見を聞いてほしい。関心を持たないのでなく、まちづくりに関心を持っている人たちを、もっと信頼して行政は意見を聞くべきであると思うんですが、その辺と、この不公平さをどうしてくれるのかと思うんですけれど、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"これまでも考え方の違いといういうことは言えませんが、これまでも具体的な事業についてはしっかり説明をしていかないといけない、また都市計画の段階ではなく、それ以前のということで事業者等を指導して、２Ｈの範囲ではありますが説明会を開催して。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問","question":"マスタープラン第６章の「計画の実現に向けて」という、住民参加のまちづくりのところにこう書かれているんですけれども、都市計画法第１８条の２には「市町村は、基本方針を定めようとするときは、あらかじめ、公聴会の開催等住民の意見を反映させるために必要な措置を講ずるものとする」という項目が入っているんですけれども、こういったものが入ったマスタープランにもかかわらず。","respondent":"溝口都市開発課長、藤田都市計画課長","answer":"そういった中で、改めて説明会という話ではなくて、窓口または呼んでいただければ、そういった必要な説明等はしっかりやっていきたいと考えているところです。こういった中で区としては、しっかりと説明するということの中で、事業化を進める中で都市計画の手続にのっとりながら、区民の意見の把握に努めていきたいと考えています。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"聞いてください。「将来イメージとしては、庶民的なまちという希望が多い一方、都会的なまちという希望は少なく、今のよさを残したいという意向が伺える」、これは区が書いているコメントです。最下位は「洗練された都会的なまち」５.６％。ここのところもぜひ、この意向を尊重する方向、もしこれが不十分だったらこれを補完する方法をもっととっていくべきであると思うんですが、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"ですからアンケートを全く無視してまちづくりを進めているというふうには、私どもは考えておりません。","id":"exchange-042"},{"speaker":"伊藤委員","kind":"質問","question":"こういうものでいつも思うのは、大規模な再開発をやればやるほど、こういう問題が出てくると感じています。それは対象する方々が非常に多いということでしょうね。例えば極端なことをいうと、武蔵小山にポッと来る方々も、ここのまちづくりはどうなるかということについては当然関心があると思います。そういう可能性はある。だから、品川区独自の条例で２Ｈ対策をとっているわけであって。お願いします。","respondent":"溝口都市開発課長","answer":"開発につきましては、これまでも同様の方法をとって進めてきておりますし、今後も同様な形で、まずはやはり直近の方々から、周辺の方々にしっかり開発事業を説明しながら、事業を進めていきたいと考えているところです。","id":"exchange-043"},{"speaker":"伊藤委員","kind":"質問・要望","question":"その方々が合意をすれば建物はできるわけだから。それが今の法治国家であり、そうならざるをえないわけであって。だけれどもそれではあまりにも冷た過ぎるし、大きな影響があるからこそ高さの２倍、今回は６,０００名と言いましたっけ、その方々に説明をしていくわけだから、やはりそういうことを品川区がやっている努力を、理解してもらえる方法は何かお考えですか。","respondent":"藤田都市計画課長","answer":"品川区の努力ということですが、住民に対するご説明ということですが、これまでも再三言っていますが、やはりしっかり説明をしていく、またその説明も近隣の方、またこれまでも２Ｈの範囲の説明会というのは、あくまでも法に基づかず任意に。","id":"exchange-044"},{"speaker":"伊藤委員","kind":"質問","question":"今の答弁の中でも、もともと事業者にはそれをする必要性はないわけではないですか、今のさまざまな法体系の中では。やはりこういうことがあるとか、こんなふうにこの計画では進んでいることだということについて、これはきちんと、品川区ができる範囲が限られている中でも耳を傾けて、個々の相談を受けていくとか、そういう内容を一つ一つやっていく必要があると思うんですが、いかがですか。","respondent":"溝口都市開発課長","answer":"それについてはしっかり、またわかりやすく説明できるように職員には指導しておりますし、しっかり対応がとれる職員をそろえておりますので、その件については引き続き真摯に対応していきたいと考えております。","id":"exchange-045"},{"speaker":"伊藤委員","kind":"意見","question":"いろいろな意見をお持ちの方々がいらっしゃるから。だけど大筋で行けば、この建設自体が、今の法治国家であり、日本の法の市政の中ではこれは建築とされているわけであって、だけれどそういう中でも、あまりにも大規模な再開発に及ぶから、個々の意見は最大限取り入れていくという姿勢を貫いていくことが、私としては品川区のあるべき姿だと思うので、品川区のこれからの方向性について、答弁ください。","respondent":"溝口都市開発課長","answer":"ただ地権者だけでなく、周辺に与える影響は大きいと思いますので、そういったものに対しての説明、またはご意見といったものは受けながら、よりよい品川区のまちづくりが進められるように、再開発事業を進めていきたいと考えております。","id":"exchange-046"},{"speaker":"大沢委員","kind":"質問","question":"再開発はやはり当該地域、および近隣地域までを巻き込みながらまちづくりをしていくわけですから、それはそれなりの覚悟と、周りの十分な理解が必要なことは言うまでもないことで、その中で先ほど課長の話で、「何々していきたいと思っています」と、「したい」という希望ではなくて、「します」という断定的にしっかりと、この案件については対処していってもらいたいのですけれども、いかがですか。","respondent":"溝口都市開発課長","answer":"武蔵小山につきましては、区の西の玄関口、また荏原地域の中心核を担っていっていただきたいまちだと考えています。ですからそういったものの発展につながるまちづくりをしていきたいというふうに思います。","id":"exchange-047"},{"speaker":"西本委員","kind":"質問","question":"一番先に平成１９年にアンケート調査、ヒアリングもしている、それをもとにして最終的にはマスタープランをつくっていって、このまちをどうしていくかという流れで、それぞれの地区に対して説明会がなされているという流れで、突発的に来たわけではなくて、いわば品川区をどうしていくのか、品川区のまちづくりをどういう視点で見ていくのか、ここの部分だけでなくマスタープランの中では。","respondent":"溝口都市開発課長","answer":"そういったことを考えていく上で、また先ほどもちょっとお話ししましたが、武蔵小山駅周辺につきましては区の西の玄関口、また荏原地区の中心核という位置づけを持っています、それにふさわしいまちづくりをどのような形で誘導していくのか。","id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"ここは商店街ですから、商店街の方々がどう思っているのか、どういうビジョンを持ってこれから自分たちの商売をして、この町を活性化していくかというのは、もう当たり前の順番なのかなと思っているんですね。だから町会実施ではなくて、住民の方も町会のほうにちゃんと声をかけるとか、この地域をどうしていくんだという議論は、やはりそこから始まっていけないといけないのではないだろうかと。","respondent":"溝口都市開発課長","answer":"町会、商店街に対してですが、資料にはありませんが、事あるごと、また説明会の開催ごとに地元町会長、商店街会長にはちゃんとしっかり個別に、こういう説明会をやりますという事前周知等を行いながら進めてきておりますし、商店街につきましては。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問・要望","question":"最後に要望といいますか。ですから、町会長に話をしてそこで終わりではなくて、次に、これを住民サイドに周知徹底してください、意見を吸い上げて次の理事会に持ってきてくださいというぐらいのところまで言わないと、広がっていかないと思うんです。そういう問いかけ。でも、少しでもわかっていただくような工夫はもう少しできると思いますので、いろいろ考えていただきたいと要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"できる限り努力をして、工夫して、そこを受け入れていく姿勢を常に求めて、足りなかったら改善するという姿勢が必要だと思うんですね。「１９階の周りのことです。そして一つ一つはアセスがかからなくても、面的にまちがどうなるのか、環境を守っていくという立場での区の責任は不十分で、改善が十分求められると思うんですね。その願いが込められている請願だと思うんですが、最後に一つ。","respondent":"藤田都市計画課長","answer":"そういったものをどこでという話ですが、先ほどの２Ｈの説明会でも、そういったご質問をいただいたときにしっかり説明はしていると考えております。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"提案","question":"これから次から次へとできますよね。もう既に、ここの地域の開発は幾つもあるけれども、どこまで区が責任が持てるんですか。今のやり方からしたら、持てないということではないですか、区の力としては。でも地域に住んでいる皆さんが、一緒に考えますよ、もっといい方法を考えますよ、提案もしていくと、そういった姿勢を持っていらっしゃるところを、私は決して拒否するものではないと思うんですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"伊藤委員","kind":"質問・要望","question":"何よりも、先ほども言ったようにマンパワーと税金の使い方を冷静に考えていくと、今、品川区が持っている２Ｈ対策の中で対処しているとこれは当然行われているから、ぜひ進めてくださいということで、お願いします。ただその中で、やはり私たちの要望としては最大限、関係する方々のご意見を聞いてほしい。したがって、この請願については不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"こんの副委員長","kind":"意見","question":"やはりいろいろな意見があるというのは大事なことですが、ではどこまでどういうふうに意見を聴取できるのか、また聞いていけるのかというのは、最大限に努力していただくという答弁の中にもありましたので、となると結論は、この皆さんのお気持ちは十分に酌みつつも、一定の説明なり対処をしているというところから、この請願に対しては不採択としたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"木村委員","kind":"質問・要望","question":"しかし、本当にこの地域の皆さんが、この武蔵小山に住んでいらっしゃる方が、本当に自分たちの将来のことを心配しているというお考えはよく感じておりますし、そういう意味でこの請願書には、協議ができる場の設置を求めるということが書かれていますし、そして請願の理由として三つある中全て、本当にしっかりと説明してほしいという気持ちがすごく強くあらわれている文章だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"意見を述べて採択を主張します。今回のこの請願は、行政とのコミュニケーション、協議のできる場の設置を求めますといった、本当に基本的な願いなんですね。質、量ともに高い情報公開を行っていくこと、そしてルールが明確で誰でも納得のいくものであるべきである、また客観性を維持できる制度であること、なかなかここがまだ不十分であると思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"西本委員","kind":"提案","question":"ただ改善は必要だと思います。そういう意味ではやはり賛同者、もしくはいろいろな意見を言っていただける方、この地域をどういうふうにしていくんだということを考えることについては、行政側だけでなくて住民側もやはり考えてほしいと思います。自分たちでこういう会もあるわけですから、その会でどんどん品川区に、それこそビジョンを提案できるようなところまで育てればいいんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"}]},{"id":"topic-04","title":"平成２５年陳情第１２号、東京都の「木密地域不燃化１０年プロジェクト」不燃化特区制度募集に対する補助２９号線沿道地区の応募除外を求める陳情","agenda":"平成２５年陳情第１２号、東京都の「木密地域不燃化１０年プロジェクト」不燃化特区制度募集に対する補助２９号線沿道地区の応募除外を求める陳情","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"これは１９４６年の計画で、この道路をつくっていく目的は一体何だったのか、その辺が今も受け継がれているのかどうか、現時点において補助２９号線道路は誰のための、何のための道路なのかという点も、改めてお伺いしたいと思います。","respondent":"藤田都市計画課長","answer":"現段階において、説明が十分かどうかという点ですけれども、本会議の中でもご質問がございましたとおり、区のほうとしてご理解が十分ではない部分もあるかと考えておりますので、この辺については説明会、地域のほうで勉強会等が行われるような状況の中では。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"補助２９号線は最終的には必要な道路であると。先ほどの質問の、誰のための、何のための道路なのかというこの辺を、もう一度明確に、道路というのはいろいろな方が利用されるので、特にここの点をもう一回明確に答えていただきたいと思います。","respondent":"品川木密整備担当課長、藤田都市計画課長","answer":"補助２９号線の必要性ということですけれども、まず私のほうから、防災の面に関しての必要性をお答えいたします。誰のための、何の目的かですけれども、これは今、防災の観点から担当課長から説明もございましたけれども、あわせてやはり道路ネットワークの観点もあります。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それと、１９日に一般質問が始まって、共産党の鈴木ひろ子区議が、この延焼遮断帯について質問をしたんですが、このときの答弁とちょっと中身が違っていたんですね。その点を確認したいんですけれども、昼の質問のほうが先だったんですが、両方一致していたのは、冬の夕方の６時という設定で８メートルの風速ということだったんですけれども、区は道路と沿道の不燃化とあわせて防火、火災をとめていくんだと。","respondent":"品川木密整備担当課長","answer":"１点目です。今回の本会議のほうと、当日に東京都から延焼遮断がなされたという説明の点ですが、あくまでも東京都の考え方としては、個人情報に触れることがあると困ってしまうと。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後に車両火災のシミュレーションができない状況だということですよね。ということは、道路を通すことが一定の効果があると、でもその効果が車を通すことでどうなるのかという心配をするのは当然ですよね。特にその辺を、自動車火災のことを正しく認識して検討していただきたいというのは、明らかに一つあると思うんです。この点はいかがでしょうか。","respondent":"品川木密整備担当課長、藤田都市計画課長","answer":"これに当たってたまたま整備地域内に都市計画道路の予定があるということで、これは防災上高いという点があるので、これを進めているという状況であることはご理解いただきたいと考えています。それから３点目。ですので、延焼が起きてしまう部分について不燃化を進めるという考え方を、取りまとめたものです。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"確認","question":"先ほど道路ネットワークが重要であると。こちらのほうが比重は高いんですか。だから完全なものを最初からドンと、２０２０年までにつくるんですか。前にＮＨＫでやったものでは、火の粉はすごく高く舞い上がるし、かなりの高層をしても火砕流は防げないという言い方をしていましたけれど、では伺いますけれど、道路の沿道をどうしていって延焼遮断効果を高めていくのかという点を、もう一度確認したいのと。","respondent":"品川木密整備担当課長","answer":"火の粉が飛んでも耐火建築物、準耐火建築物には延焼しないというふうに考えております。それから地域危険度が５から３という、これは後で説明しますので、ある程度割愛しますが、耐火建築物、準耐火建築物にしていくことが大事なのではないか、それはそのとおりです。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問","question":"今の質問は、耐火、準耐火にしていくことが必要だと。前にイメージ図があったのを抜きましたよね。沿道を超高層のコンクリートと鉄の建物で変えていくんだという図を外しましたよね。あれでなければ延焼が防げないと思っていたのか。それが普通の木造住宅を準耐火、耐火にすることで大丈夫というのか、そこのところをはっきり答えてください。","respondent":"品川木密整備担当課長","answer":"これで沿道３０メートルが耐火建築物でなくても、十分遮断効果があるというふうに考えておりますので、そこに向けて事業を進めているような考えです。沿道を全て高層建築物で固めてというようなイメージは、区としては持っておりません。","id":"exchange-063"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だからそういうことを冷静に考えていくと、この補助２９号線等については、品川区のさまざまな防災に役立っていくということ、実際に関東大震災と阪神・淡路大震災と比較して、間違いなく延焼遮断の効果があったということ、これはもう実際に示されているわけであるから、さまざまな議論が今あったけれども、それは関係する方々にさまざまな影響を及ぼすから、十二分に説明していただきたいのと。","respondent":"片田都市環境事業部長","answer":"それを鋭意進めていくということを、区としても最重要課題として考えておりますので、そのために地域の皆さんのご理解を得るべく、丁寧な説明を心がけているという状況ですので、そういう意味で今、委員にご質問いただきましたような整備をきちっと進めていくというのが。","id":"exchange-064"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ただただ道路を拡幅するということだけで話を進めていくと、何だとなるわけであって、だけれど今言ったようなさまざまな、そちらはプロですから、もっと資料を持っていらっしゃると思うんですけれども、遮断帯があって、こういうふうなことがあって、生命、財産が守られたという事実はこの先たくさん要ると思います。","respondent":"片田都市環境事業部長","answer":"いろいろなシミュレーションの話もありましたけれども、私ども区としてはきちっと丁寧な説明に心がけて、やはり住民の生命と財産を守るという視点に立って、きちっとした説明を心がけていきたいと考えています。","id":"exchange-065"},{"speaker":"西本委員","kind":"質問・要望","question":"認識がどうか、ちょっと教えてほしいんですが、この題名ですね、大きい字で書いてありますけれども、「不燃化特区制度募集に対する補助２９号線沿道地区の応募除外を求める陳情」、応募除外、募集というふうになっていますね。今、補助２９号線はこういう状況なんでしょうか。それでまず気になるのが、この「募集に対する」って、募集している段階なんですか。今、どういう状況なんでしょうか。","respondent":"品川木密整備担当課長","answer":"現在のところ、補助２９号線沿道の不燃化特区については募集をしている段階で、今のところ正式受理というところまで受けております。ただ、確実に決定かどうかということは、今年度末もしくは来年度初頭になるかと考えております。","id":"exchange-066"},{"speaker":"西本委員","kind":"質問","question":"ということは、今の段階で募集をやめてくださいという陳情ですよね。それで、区はどう考えているんですか。","respondent":"品川木密整備担当課長","answer":"区としては、当然延焼遮断効果を高めるため、それから沿道の不燃化を進めていくために、進めていく考えです。","id":"exchange-067"},{"speaker":"西本委員","kind":"質問・要望","question":"それで今年の予算も取っているわけですよね、ある程度。それで、簡単で結構です、ここの中で、今進んでいます、やっていません、やるつもりもありません、というのがあると思うので、ちょっと言いますと、例えば２番、説明会が２カ所されておりません、これはどうされていますかというのが一つ。区としての認識をお聞かせいただきたいと思います。","respondent":"藤田都市計画課長","answer":"区の意見といたしましては、木密地域の耐震化、不燃化を進める事業は非常に大切な事業ですので、いろいろ意見がおありの方はありますけれども、東京都と連携し、ご理解をいただく説明を今後も尽くしていく必要があると考えています。","id":"exchange-068"},{"speaker":"西本委員","kind":"質問","question":"説明会については１カ所、町会のほうからまだ無理ですよというお話があったと、それは考えていただいたということで、ほぼできているということだと思います。そこで、西大井四丁目でも「測量説明会を行ってから、測量を始めると約束したにもかかわらず」という部分がありますが、これはどういう意味なんでしょうか。何か行政の事情が何か違ったのか、状況のほうをお伝えください。","respondent":"藤田都市計画課長","answer":"これはもともとの現況測量の、本来の目的である例えば道路の境がどこであるとか、それぞれのお宅の境がどこであるとか、そういう測量をするということではなくて、道路上で測点をつないでいくための作業でございましたので、直接は周りの皆様に影響がないんですが。","id":"exchange-069"},{"speaker":"西本委員","kind":"質問・要望","question":"やはりそれは誤解なので、そこの部分をとって「とんでもない話だ」というように住民がおっしゃるのはやはり、誤解でそういうことをするというのはやはりちょっと、住民に対してもあまりよろしいことではないので、くれぐれも誤解のないような形で配慮していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問・要望","question":"誤解があるようなので一言。よく読んでいただきたい。延焼遮断効果を否定しているわけではありません。今住んでいらっしゃる方の命も守れない、こんな勝手にどんどん進めていいのかというところにおいて、すごく疑問を持っているので、ここに対して答えてほしいのと、そういった意味では私はこのタイトルは決して、正しくておかしくもないと思っていますので、それをつけ加えながら質問します。","respondent":"片田都市環境事業部長","answer":"したがいまして、当然計画道路で、それぞれの権利者のご理解を得て、測量もする、あるいは土地も取得するという流れになるわけですので、そのことはきちっと、やはり全体の説明会は全体の概略、考え方をお示しすることが必要となりますので。","id":"exchange-071"},{"speaker":"伊藤委員","kind":"質問・要望","question":"つまり先ほど審議の中でもありましたけれども、個々のお宅がこうなるということまで、行政のほうで相当つかんでいると思われます。ですから、意見としてはそういうことはわかるのだけれども、だけど生活がかかわっている以上は、多くの方々に対する十二分な説明と、さまざまな行政の中での対処、生活再建の方向についても、やはり個々に真剣に取り組んでいただいてほしいということを、改めてお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"この陳情を出された方々のお気持ちは、反対意見ということで伺いました。一方で防災の強化、それを求める声というのもたくさんあるかと思います。そういった意味ではこの区の中での防災力をどう高めていくか、こうしたことを考えると、やはり一刻も早く防災力を上げるには、先ほどおっしゃったライフラインのネットワーク、こうしたことの観点から考えると、非常に大事なプロジェクトであると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問・要望","question":"防災のまちづくりが大事だからこそ、今、そこに住んでいる住民の方々とともに十分な話し合いを行って、安全安心なまちづくりを進めていただきたいと思っています。住民が納得をしていない、合議していない、明らかに不十分であるこの道路計画を進めていくのは間違いであると思っています。よって、補助２９号線沿道地区の不燃化特区から除外すべきという意見に賛成なので、採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"西本委員","kind":"質問","question":"そのためにいろいろな補償が出ているわけですから、もともと都市計画道路という指定の中で、どういう状況になるかわからない中で、こういうきっちりとした条件整備も出てきたということにおいては、やはりこれを活用するなり、さらにその地域の安全を皆さんで議論するなりしていくような建設的な、住民サイドと議論をしながら、まちづくりができればいいかなと考えています。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"西本委員","kind":"意見","question":"以前、許可をして、こちらまで出てきて写真を撮られた方がいらっしゃったんですね。ということがありましたので、それはやはり会議運営上よろしくないので、そういうことも含めて考えると、冒頭だけという形でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"},{"speaker":"伊藤委員","kind":"意見","question":"参考までに。今まで例えばマスコミが入ったとき、過去いろいろありましたけれども、大概冒頭の撮影だけお願いして、その後は撮影はお控えくださいということがありましたので、それに倣っていただければいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-077"}]},{"id":"topic-05","title":"平成２５年陳情第１３号、白金幼稚園の日照環境を守ることについての陳情","agenda":"平成２５年陳情第１３号、白金幼稚園の日照環境を守ることについての陳情","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"実際都のほうはどのような、本件について都のほうの態度というか、ご意見はどのようになっているのか、教えていただきたいと思います。","respondent":"藤田都市計画課長","answer":"私どもで今のところ聞いているお話としては、地域の方々のお話を受けて、地元の区のほうにもしっかり説明をするように、事業者に説明を求めたというふうに聞いてあります。それに基づいて私のほうにも説明があり、本日の資料の作成等に生かしたところです。","id":"exchange-078"},{"speaker":"大沢委員","kind":"質問","question":"この建築に関して、法令上については問題があるか、ないのか、それについて教えてください。","respondent":"藤田都市計画課長","answer":"私どもが確認している中では、日影規制についての法律上の観点からいうと、影響がないといいますか、法律の範囲の中で計画されているものだということで、ほかの建築にかかわる部分についても、建築確認の具体的な手続を行う中で、おそらく確認していくことになろうかと思います。","id":"exchange-079"},{"speaker":"大沢委員","kind":"意見","question":"この陳情について、都との中でらちが明かない、請願代表者の方々が、なぜ品川区のほうに陳情を出されてきたのか、そこの部分はどういうふうに区としては判断していますか。","respondent":"藤田都市計画課長","answer":"今回の件についても、まず身近な地元の区のほうに意見申し上げようと思って、品川区に来たのかなと感じているところです。","id":"exchange-080"},{"speaker":"大沢委員","kind":"質問","question":"では伺いますけれども、当該の日照権について、いわゆる教育施設というものに関して、法的には日照権の扱い部分があろうかと思うんですけれど、そこのところを、教育施設についての日照権はどのように区は受けとめられているのか。","respondent":"藤田都市計画課長","answer":"ということで、ひとまずは全域でそういう考え方を展開しているような形で、もちろん港区もやっている形になってありますので、そういう中で、例えばエリア別にいろいろな考え方の中で、この地域については具体的にもう少し違う考え方でやろうというようなことであれば。","id":"exchange-081"},{"speaker":"伊藤委員","kind":"質問","question":"今の話にも重なるところがあるんですけれども、この地上１０階地下２階の建築主は、大林組なんですよね。この大林組の建物自体が、現行の建築基準法等に適用しているものなのでしょうか。わかりますか。わからなければわからないで。","respondent":"藤田都市計画課長","answer":"建築基準法の関係ですけれども、もちろん建築する当時は、その当時の建築基準法に合わせてしっかり建築されたというふうに考えてあります。","id":"exchange-082"},{"speaker":"伊藤委員","kind":"確認","question":"そうすると、大林組ですから、そんな建築違反することはないと思うんだけれども、合法的にこの建物が建てられているという現状が確認できる一方、こういう建設委員会の関係で日照権の話は出るんですけれど、いわゆる日照権の取り扱いについて、例えば行政なり東京都なりが当該業者に指導したり、正す根拠は、品川区にあるんでしょうか。このことに関して。","respondent":"藤田都市計画課長","answer":"その後建築基準法の改正が、１９７６年ですから昭和５１年にあって、その中でこの日影規制という考え方が導入されたです。","id":"exchange-083"},{"speaker":"伊藤委員","kind":"確認","question":"先ほどの説明の中で、１万平方メートル以上の建物については品川区が直接の権限がないと聞いたんだけれども、そうするとこの大林組がやっている目黒駅前プロジェクトは、直接の指導ができるかどうか知らないけれど、東京都になるんでしょうか、確認です。","respondent":"藤田都市計画課長","answer":"資料の１枚目の中ほどに、黒四角で説明会等経過というところがありますが、その一つ上、延べ面積ということで約２万３,０００平方メートルということで、東京都紛争予防条例の適用ありということを書かせていただいてあります。","id":"exchange-084"},{"speaker":"伊藤委員","kind":"確認","question":"そうすると確認しますけれど、計画面積が１万平方メートル以上であるので、東京都紛争予防条例の適用により一義的には東京都の所管なんですねという確認と。それだから議論できなくなってしまうんですけれど、要するに現行の日照規制の中でおそらくこの建物が建てられると推測をするしかないんですけれども、それはわからないですよね、調べてみないと。","respondent":"藤田都市計画課長","answer":"都と区の役割分担の中でいろいろありますが、そういう中で今回の案件は、まず都の案件であるということで、区が勝手に事業者に対してポンポン、ポンポン物を言うということは、東京都の範疇を侵してしまうことになりますので、まずは東京都に。","id":"exchange-085"},{"speaker":"伊藤委員","kind":"質問","question":"そうすると、この陳情書に書かれてありますように幼稚園の環境を守るためには、今まで幼稚園が行ってきていただいた話し合いによる譲歩、これはやはりまだまだ可能性はあると私たちは思っていますから、その話し合いを、加速させるというのは言葉が悪いですけれど、権限もないので何とも言えないんですけれども、そこで何かしら品川区として、地元にある幼稚園だから、多少話を聞いて。","respondent":"藤田都市計画課長","answer":"ご案内のとおり建築紛争の関係の手続ですと、なかなかお話し合いがまとまらない場合については、あっ旋であるとか紛争調停の調停委員会を開くというような手続に入っていきますけれども、これについては区としてできることではございませんので。","id":"exchange-086"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この間お話を伺ったところによると、冬至に残ったわずか、工夫して園舎を建てて、園庭で遊べるように残した冬至の一番大事なところが、この建築で奪われてしまう。そういったところで、今もいろいろ苦しい部分も伺ったんですけれども、今、現状において区はこういった状況をどう捉えていらっしゃるのか。その辺をちょっとお聞かせいただきたいと思います。","respondent":"藤田都市計画課長","answer":"それがなかなかうまくいかなくなると、次のステップに進んでいくわけですけれども、昨年、原因そのものが直接日影の話ではございませんけれども、工事の進め方とかそういった関係の中で、あっ旋まで進んだことが１件ありますが、ここ数年で。","id":"exchange-087"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なかなか厳しい状況ではあると思うんですけれども、今ある部分から、変えられるところは打開していく。そうでないと、もう今、どんどん環境が悪くなる。そういった面でぜひ、正式ではないけれども関係者の方々との話し合い、都と区も連携をして、話し合いの場をつくっていただきたいと切望するんですけれども、いかがでしょうか。","respondent":"藤田都市計画課長","answer":"そういう中で都と連携しながら、区としてできることはやっていきたいと考えていますが、区がまずお話し合いの中心になるということは、ちょっと今の段階では難しいと思ってありますので、この件の取り扱いについては、都としっかりお話をしていきたいと考えています。","id":"exchange-088"},{"speaker":"西本委員","kind":"質問","question":"非常に難しい問題だと考えています。都会ですから、日照といってもなかなかその条件を維持していくというのは、物理的に難しいかなと。それでも当該の方々が地域の方たちと、ビルとかを含めて交渉してきて、今を維持してきたんだろうなと思ってはいるんですが。１１階を１０階にしたということになるので、それだけ譲歩してきたというか、建築用件を変える手間というのは、どういう形になるんでしょうか。","respondent":"中村建築課長、藤田都市計画課長","answer":"当初の設計を変えるという作業ですけれども、通常は絵だけを直せばいいということにはなるんですけれど、ただ既に近隣、周辺の皆様に説明をするという段階になりますと、もうそれで了解が得られた場合には建築工事に取りかかれるように。その中では、建物そのものの形状とかそこまで影響が出るので、設計をやり直すための影響が非常に多いこと、それから免震ということで耐震性を確保するための構造等についても、大幅な変更をしなければいけないということで。","id":"exchange-089"},{"speaker":"西本委員","kind":"質問・要望","question":"ここまで来ると、かなり進んだ話の中でのことだと思うんですね。非常に難しい問題だと思いますけれども、もう一度区の立場として、何ができるんですか。はっきり言ってできませんよと、話し合う場を設けなさいぐらいで、この１０階に譲歩した条件をさらに進めさせるような、そういうところまでの強制力が品川区にあるのかどうか、そこをはっきりしていただきたいと思うんですが、いかがでしょうか。","respondent":"藤田都市計画課長","answer":"それ以外の部分についてはお話し合いの範疇に入ってしまいますので、区としてできることは、具体的な何か、こうしなさいというお話ではなく、お話し合いを継続してくださいというお願いまでしかできないというふうに考えてあります。","id":"exchange-090"},{"speaker":"西本委員","kind":"意見","question":"そういう意味からすると、話し合いってくださいねと言うことしかできない。民民ですし。それだけ頑張ってこられたというのもありますけれども、品川区全体を考えたとき、子供たちのためにというのであれば、子供たちのための日照権をどうするかという、もっと広い意味の議論をしていかなければいけないというふうに思っていて、これは意見として終わりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-091"},{"speaker":"原委員","kind":"質問","question":"先ほど東京都との話し合いのことがあったんですけれども、当該幼稚園自体は港区、港区との話し合いというのは、今度は区同士での関係、区境ですので、その辺はあったのかどうかということを教えてください。","respondent":"藤田都市計画課長","answer":"今回の案件ですけれども、７月３０日に私ども品川区のほうには都から指示があり、事業者が説明に来ました。港区のほうにはどうも９月に入ってからそのような話が行っているようで、現段階では、私は直接港区の方とはまだお話をしている段階ではございません。","id":"exchange-092"},{"speaker":"原委員","kind":"質問・要望","question":"陳情には直接イコールではないですけれども、ですからマスコミ的にもいろいろな関心を持たれている。ただ、先ほどほかの委員もおっしゃったように、日照の問題というのは例えば日野学園だってビルの真ん中にポンとあるわけですから、そういうふうに品川区も大分高層化が進んできて、民間同士でいくと、日照権の問題というのはもう、商業地域であれば言われないのが当たり前になってきてしまっている、公的に。","respondent":"片田都市環境事業部長","answer":"ただ強制力が、先ほども申し上げましたようにありません、相手がその話し合いに乗っていただけるかどうか、それが一番のポイントだと考えています。","id":"exchange-093"},{"speaker":"原委員","kind":"質問・要望","question":"ですからその辺を十分に、これはお力添えを特にいただきたいのは、課長ポストではなくて部長以上の方々にお力添えをいただきたいと、そういうことが私の思いですので、その辺をお酌み取りいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"今までの議論も聞かせていただいて、私も質問したいという点が何点か出ておりました。再度確認なんですけれども、いわゆる区として何ができるのか、強制力等々も含めてどういうことができるのかというところでは、話し合いの場を設ける、そうしたことへのいわゆる口添えといいますか、仲を持つ、そうしたことができるというお答えが、先ほどからも出ておりましたけれど、それはそうなんですかという確認です。","respondent":"藤田都市計画課長","answer":"そういう中で、区として何ができるかという部分ですけれども、例えば１万平方メートル以下の、通常区が受け持つ立場であれば、このようなお話をいただければ、その中で話し合いをまずやってほしいというお話をする、それでもなかなか話し合いの継続ができなければ、申し出があり。","id":"exchange-095"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"この陳情の趣旨というところでは、話し合いの場を設けていただきたいということからすると、区として継続をということはできるというお答えなので、それはこの陳情に限らず、そうした日照の問題に関して、ある一定のルールにのっとった中で、話し合いの継続をお願いされることもあるかもしれないですが、あえてこの陳情が出てきているというところでは。","respondent":"藤田都市計画課長","answer":"話し合いの継続の部分ですけれども、すみません、言葉が足りない部分があるといけないので、ちょっと補足しますけれども、話し合いの継続を区がお願いする前提というのは、まず今回の案件の当事者といいますか、担当である東京都のほうとお話をして。","id":"exchange-096"},{"speaker":"大沢委員","kind":"質問","question":"今、区と都ということで、都からそういうことがあればということでお話しいただいたんですけれど、最初に私、質問で、なぜ区に来たんですかという流れの中で、この方たちはなぜこういうものを出してきたか、皆さんのお話を聞いていて、さっき言葉の節々に聞きとれたところがあるんですが、それは区ですよ、それは都ですよと、お互いキャッチボールして、この陳情者の方たちはそこのところで対処に困ったから。","respondent":"藤田都市計画課長","answer":"今回の件についても、ひとまずは都なので、都が何と言うかというのは大事なところですけれども、その中で区にもということであれば、都とのお話をする中でしっかり動いていきたいと考えています。","id":"exchange-097"},{"speaker":"大沢委員","kind":"質問","question":"これは民民のものですから、民民で基本的には解決しなければいけない。ただお困りのところでは都の部分、区の部分、プロではないからこれは都の部分だよ、区の部分だよとわかりづらいところはありますけれど、そこは指導はできないながらもそれなりの、陳情者に対して誠意が通じるような対処方をお願いしたいと。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"西本委員","kind":"質問","question":"先ほど区のできることという形で質問させていただいたんですけれども、これから採択に入る形になると思うんですね、その前に、やはりここは本来は東京都でやるべきことだということも踏まえて、もしもそういうことがわかっていたとしたら、もしかしたらこういう内容ではなかったかもしれないと私は思うんですね。状況としてわからないことはたくさんある。非常に難しいなと今、感じました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"伊藤委員","kind":"質問","question":"ですが、２３平方キロの中に３６万人の人たちがいる現状の中では、高層ビルが建っていくこともまた事実であります。ですから、これをもしやるなら法改正が必要なわけであって、現時点ではそれができないわけでありますから、繰り返しますけれど、この趣旨、内容について理解するところはあるけれど、権限外だし、今できないことが相当あるので、総合的に判断して不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"が、先ほども申したとおり、民民の話ではありますけれども、教育現場というところが私は一点、品川区民のお子さんがお世話になっている幼稚園だということもあり、そうしたところでは話し合いの場の継続ということでの、東京都からそういったこともある中でできるというお答えもいただきましたので、どうかそこら辺のお気持ちは組んで差し上げていただきたいという思いから、趣旨には賛同したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"木村委員","kind":"質問","question":"これは大変難しい問題であります。各委員の意見を聞いておりまして、本当にこれだという結論が出せない案件でありました。そして東京都の問題というか、東京都の裁定になっている問題ということ、そして品川区は何ができるのかということを考えますと、これも大変難しい問題であります。ですから、この問題に関しては趣旨採択でお願いしたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"原委員","kind":"意見","question":"我々会派の中でも意見がいろいろ割れているところです。ただ、やはりこの陳情に絞って話をすれば、「ご指導いただきたく」というところで品川区は指導権限がない。であれば、責任を持ったご返答ができないので、不採択という考えです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-103"},{"speaker":"飯沼委員","kind":"意見","question":"都のところでなかなか困難があるのかもしれませんが、都と区と連携をして、ぜひ話し合いの場を設けていただくということで私は採択を主張したいんですが、もし趣旨採択で一致をしてまとまるのだったら、趣旨採択にしてもよろしいですけれども、そうでなければ採択を主張いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"先ほどから、区の権限はどこにあるのかということを再三強くお聞きしました。非常に難しい問題と感じておりますけれども、やはり民民の立場、行政側の立場から考えると、特に大林組に対して直接的な指導ができないというのが私たち品川区の立場ではなかろうかと。それと、教育環境保全ということにおいては非常に参考にさせていただきたいと思っています。残念ですが、今回は不採択という形にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"}]},{"id":"topic-06","title":"「」を行います。 はじめに、(1)専決処分の報告","agenda":"「」を行います。 はじめに、(1)専決処分の報告","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"第６５号議案と同じような質問をしてしまいますが、平成２４年１０月からの入居で、当初から滞納があったということで、月額幾らの家賃なのかというのと、この方も理由を把握できていないのか、その確認をさせていただきたいと思います。その継承できる場合の特例の説明をちょっとしていただけたらと思います。","respondent":"大串住宅担当課長","answer":"この方は入居をされて以来、１回も納付が行われておりません。当然１カ月目から、先ほどの午前中のときにもご説明させていただきましたが、１カ月滞納あるいは２カ月滞納といった少ないときから、納付指導、督促といったことを行っている状況です。","id":"exchange-106"},{"speaker":"西本委員","kind":"質問","question":"すみません、すごく基本的なことなんですけれど、第６５号議案は議案審査で、この２件は報告で、これは金額なんですか。","respondent":"大串住宅担当課長","answer":"委員おっしゃるとおりで、３００万円というのが一つの壁になっていまして、３００万円を超えた場合には承認という形、３００万円以下であれば報告という区分けになっております。","id":"exchange-107"},{"speaker":"西本委員","kind":"質問","question":"第３０号のほうです。この１万３,１１０円という購入費となっていますが、この算定はどういう、申告になるんですか、どういう算定の方法なんでしょうか。","respondent":"小林品川区清掃事務所長","answer":"損害賠償の対象となりましたのはブラウス、パンツ、レギンスの３点ですが、それぞれ購入した店舗、内容、購入した時期を確認いたしまして、通常の耐用年数を５年、そして経過年数それぞれたった時期、それを減価いたしました結果。","id":"exchange-108"}]},{"id":"topic-07","title":"地震に関する地域危険度測定調査（第７回：東京都）結果報告","agenda":"地震に関する地域危険度測定調査（第７回：東京都）結果報告","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"地震に関する地域危険度測定調査（第７回：東京都）結果報告についての資料の裏面、(2)火災危険度２３区上位１０丁目の変化とありますけれど、これは何でこうなったのかというと、地盤の部分の評価があったということを聞きましたけれど、あまり当該町、豊町５丁目、二葉３丁目、さまざまな事業が進んでいないと思われる中にあっても、これだけ変わったのは、ほかに何が原因があったんでしょうか。","respondent":"品川木密整備担当課長","answer":"一つには、豊町５丁目、二葉３丁目等、先ほど説明しました上位１０位内に入っていた町丁目につきましては、この危険度調査以後、密集事業、防災生活圏促進事業等の建て替えに関する事業、道路整備に関する事業、こういったものをかなり集中的に行ってきたという結果が。","id":"exchange-109"},{"speaker":"伊藤委員","kind":"質問","question":"今のお話だと、密集事業が確かにあるんですけれど、地盤の評価でこれだけ変わってしまうということを思うと、前回は随分と上位の中に入っていたから聞きたいのですけれど、もちろん東京都の調査だから相当さまざまなシミュレーションをしているんでしょうけれども、前回の調査よりも今回の調査のほうがより具体的な被害の状況に、そもそも明確になっているんでしょうか。","respondent":"品川木密整備担当課長","answer":"それから地盤の面に関しましても、当然以前より大きな力をかけておりますので、やはり地盤の弱いところでは、以前よりもさらに大きな地震が起きるというところもありますので、前回の調査よりはより現実性に向けた形で調査ができているのではないかと考えております。","id":"exchange-110"},{"speaker":"伊藤委員","kind":"確認","question":"確認したい部分と、今のお話ですけれど、つまりは品川区の総合的な安全性は高まったと判断しているわけですよね、東京都は。だけれど数値が１年だけでこんなに変わるというのは、もちろん東京都の調査だから相当のことをやっていらっしゃると思うんだけれども、どこまでこのデータを信用していいのかという思いもどこかにあるんですけれども、もしおわかりになれば、何か説明していただけますか。","respondent":"品川木密整備担当課長","answer":"このランクが下がったということで、品川区の木密が解消されたとか、そういうことではございません。現時点でもランク５からランク４に下がったぐらいですので、まだまだ我々は木密事業を進めていかなければならないというふうに考えております。","id":"exchange-111"},{"speaker":"飯沼委員","kind":"質問","question":"まだ膨大な資料できちんと見ていないんですが、特に今回わからないのは、災害時活動困難度、新しい言葉でここに説明が書いてあるんですけれど、よくわからないので、もうちょっと具体的にこういう計算だというところと、これが今後どういうふうに活用を、これを参考にしていろいろなことが行われるのかというのを教えてください。","respondent":"品川木密整備担当課長","answer":"こういった形でやはり道路を整備していく方向性が、危険度ランクの高い地区については道路整備なり、地区計画等そういったものが必要になるのではないかというふうには考えております。","id":"exchange-112"},{"speaker":"飯沼委員","kind":"質問","question":"今のご説明の中で、広い道路があるかどうか、６メートル以上あれば避難しやすい、火も消しやすいというところにおいて、こういったものを受けて、ある一定のランクが出ましたよね。それで道路幅というのをどう考えていくのかというのを、今伺ったところで疑問を抱いたので、その辺が一点です。","respondent":"品川木密整備担当課長","answer":"それから２点目、こういう相対評価の点について、区としてどう説明していくのかですが、先ほども答弁しましたとおり、密集地区に関してほとんどランクが５から４に下がった、もしくは４から３に下がったということで、全体の町丁目を見ていただきますと。","id":"exchange-113"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味では、午前中から引きずりますけれども、道路が有効だということは絶対否定をしているわけではないけれども、道路以外のことをどれだけ進めていくのか、とても厚い報告書なので全部しっかり読み込みながら、この品川区内で何が求められているのかというところでは、しっかりやっていただきたいし、特に住民の方の声をしっかり受け取ってやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"西本委員","kind":"質問","question":"そうすると、全体のパーセンテージでなくて、建物を含めた形の変動といいますか、例えば品川区で耐震化とかいろいろな事業を展開する中で、どれだけ反映できているのかというのは、数字で比較したほうがわかりやすいのではないか、動向が見やすいのではないかと思うんですけれど、いかがでしょうか。","respondent":"品川木密整備担当課長","answer":"円グラフにつきましては、各町丁目の中で、ランクの集まりという形で円グラフを出しておりますので、ここに建物棟数とかそういう要素を入れて出すというのは、非常に難しいところであると思います。","id":"exchange-115"},{"speaker":"西本委員","kind":"質問","question":"いい指針になるのではないかと思うんですね。だからこの第６回と第７回の比較をして、対策が進んでいますねとかいうのはなかなか言いづらいというところを非常に感じたんですけれども。それはそれとして、これらのデータを見て品川区の事業がかなり進んでいるというふうに、検証されているかどうかの評価は、どうでしょうか。","respondent":"品川木密整備担当課長","answer":"そうはいいましても、ランク等につきましてはそういった要素もあるし、もう一つは先ほど説明しましたとおり、今回地盤の部分での評価が入ったという点がかなり、大きく順位を変えているのではないかと感じます。ですので、両方の要素を抱えているというふうに思っております。","id":"exchange-116"},{"speaker":"飯沼委員","kind":"質問","question":"資料１の下のほうに書いてあることが気になったんですが、２の(3)総合危険度のところで、「品川区南西部や大田区に広がる地域でも危険度が高くなっています」という表現があって、今日の資料だと１００位までしかデータが出ていないのでわからないので、その点と、その下の(4)災害時活動困難度を考慮した総合危険度のところで、「中野区や杉並区東部などでは危険度は上がっています」と。","respondent":"品川木密整備担当課長","answer":"これにつきましては、本日資料で出すことができなかったのですが、ランクごとに色別をしますと、例えば総合危険度については、荒川区、墨田区のあたりがランク５が多いとか、品川区はランク４が非常に多いかとは思います、大田区でもそういった地区があるということで。","id":"exchange-117"}]},{"id":"topic-08","title":"武蔵小山駅前通り地区再開発計画に関する都市計画案","agenda":"武蔵小山駅前通り地区再開発計画に関する都市計画案","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"２のところの都市計画原案の縦覧は、いつまでか教えてほしいのと。この原案の縦覧と今後のスケジュールの都市計画案の説明会、縦覧とありますね、この間の流れが、どうすると原案が案になっていくのか、その辺の流れとか手続とかを教えていただきたいのと。関係権利者が全体で何人いらっしゃるのかというのを教えてほしいのと。","respondent":"溝口都市開発課長","answer":"説明会については、今現在１０月１７日の開催を目途に、調整等図っているところですが、周知につきましては広報等を使いながら、周知を図っていきたいと考えているものです。権利者数ですが、今回１６条の説明をするに当たって、約１,６００名の方に対して説明を行っております。","id":"exchange-118"},{"speaker":"飯沼委員","kind":"提案","question":"委員長に対してお願いなんですけれども、ぜひこの地域、図面で見てもなかなかわからない地域なので、ぜひ現地の視察も含めて、この開発について皆さんに知っていただきたいという意味では、やはり今、品川区で開発を進めているのは武蔵小山だけですよといったことでは将来的にないと思うので、ぜひ品川区の開発のあり方を皆さんとしっかり受けとめていただきたいと思うので、この道路計画とかは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-119"},{"speaker":"飯沼委員","kind":"質問・要望","question":"当委員会にかかわるところで、共産党の鈴木ひろ子区議の質問の中身なんですけれども、特に１番目の「巨大地震による住宅倒壊から区民の命を守る対策を急げ」の中で、答弁がよくわからなかったところがあるんですけれど、消防車の台数と消火箇所のところをもうちょっとわかりやすく、消防車を求めたんですけれども、いろいろな答弁があったのでここのところをわかりやすく、あと消火の箇所をもう一回。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"飯沼委員","kind":"質問","question":"消火活動の問題ですね。区内の消防車の台数は何台かということ、同時多発で起こった火災に対して何カ所の消火対応が可能なのかというところを、詳しくお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"飯沼委員","kind":"質問","question":"初期消火というところかなと思ったんですけれど。消火対策の一つで伺っているんですが。仕切りはお任せいたします。震災はまだこれからなので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-122"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/483820?Template=document&Id=4084#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":99856,"voices":344}}]);
